/* 平成29年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h29.committeeSessions.push(...[{"id":"h29-20170309-3","meetingId":"h29-c-budget","date":"2017年3月9日","dateIso":"2017-03-09","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時１５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を156件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"質問に入る前に、明後日、３月１１日、東日本大震災６年を迎えます。初めに２つ、お伺いしたい質問を先にさせていただきたいと思います。それと、感震ブレーカーなのですけれども、感震ブレーカーも昨年度は１１０件と出ていて、これから平成２９年度は２１０件に拡大するということで、どういう経緯で拡大するのかということも、まずお知らせいただきたいと思います。","respondent":"古巻防災課長","answer":"ただいまの委員のご質問にお答えさせていただきたいと思います。防災行政無線の更新ですけれども、防災行政無線は、設置後、既にもう３０年以上が経過しておりまして、そういった設備の老朽化への対応というのが急がれているところです。第１に、そういった老朽化への対応。","voiceIndex":4,"id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"感震ブレーカーは、関連しまして防災体験館が１年が経過して、来館者が１万人来られたということで、多くの区民の方、あるいは区外からも多くの方が足を運んだという中で、これはあと町会と自治会に対していろいろ啓発活動もやっていると思うのですけれども、実際の避難訓練は、当然、地域ごとにやっていますけれども、やはり感震ブレーカーなどを見ていただくというためにも、ぜひ町会・自治会に対して。","respondent":"古巻防災課長","answer":"それで、具体的に子局がどこということは、今現在、検討中ですけれども、考え方といたしましては、どこか１カ所というか、まとまった地域をというよりは、区内全域を見据えまして、なるべく聞きにくいところをピックアップして。","voiceIndex":6,"id":"exchange-002","title":"町会・自治会支援"},{"speaker":"高橋（伸）委員","kind":"質問","question":"これは本当に、デジタル化が平成３３年度までに全部終わるということで、いつ来てもおかしくない有事に向けて、当然、自助の部分も大切なのですけれども、公助も含めて、ぜひ構築をよろしくお願いしたいと思います。続きまして、１８７ページ、歩行喫煙防止についてお伺いします。","respondent":"濱田生活安全担当課長","answer":"歩行喫煙防止、現在、月１回、生活安全サポート隊が一斉に取り締まりを行っているところですが、これを来年度から毎月１６日間、３名体制で路上喫煙の禁止地区の取り締まりを行っていきます。","voiceIndex":8,"id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問","question":"私も愛煙家であれなのですけれども、これは関連して歳入の話で、過料が１万５,０００円だったのですけれども、１万５,０００円という数字は、数人の方に対して、ひどい、マナーが悪いから過料を取ったということで認識していいと思うのですけれども、その辺で、過料のことで、本当にずっと、何というのですか、たちの悪い人に対して過料をやっているということの認識でよろしいのでしょうか。","respondent":"濱田生活安全担当課長","answer":"過料の徴収方法ですが、先ほどもご説明いたしましたが、路上禁止地区で一斉に、１カ月に１回取り締まっております。その路上地区において、いわゆるサポート隊が喫煙を現認した場合に取ります。","voiceIndex":10,"id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これから喫煙マナーアップというのは本当に重要だと思うので、これから広報啓発を十分にまたやっていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-005"},{"speaker":"つる委員","kind":"質問","question":"１７３ページ、ホームページ等経費、１７５ページ、品川音頭リニューアル経費、２０９ページ、戸籍事務費などについて伺っていきたいと思います。ホームページ等経費の中で、車いす利用者向け動画の道案内、いわゆるバリアフリー動画の拡充についてお聞きしたいと思います。２０１５年３月３１日、２０１４年度から、ホームページで掲載していただいております。","respondent":"中元広報広聴課長","answer":"車いす利用者向けの道案内動画の再生回数ですが、現在、３ルート設定してございまして、それぞれ大井町駅からのルートですが、３ルート合わせまして２,６４５回の再生回数です。","voiceIndex":14,"id":"exchange-006"},{"speaker":"つる委員","kind":"確認","question":"２,６４５回ということで確認させていただきました。次に、２,６４５回というのが、この間、２年の中で多いか少ないかというところもあろうかと思いますが、その辺の検証というのはする必要もないかと思うのですけれども、その上で、そのページにいくまでに何ページ、ページをめくらないといけないか教えてください。","respondent":"中元広報広聴課長","answer":"２ページとなります。","voiceIndex":16,"id":"exchange-007"},{"speaker":"つる委員","kind":"質問・要望","question":"そういう意味では、せっかくいい取組みなのだけれども、そこに至るところ、ホームページ上でバリアがあってはよろしくないのではないかというところで、やはりアクセシビリティーをしっかりと上げていくというところでは、今後、２０２０東京オリンピック・パラリンピック大会などを含めて、思い切ってホームページのトップページに持ってくるような配置など。","respondent":"中元広報広聴課長","answer":"今後、トップページのほうで工夫をしていければと思ってあります。","voiceIndex":18,"id":"exchange-008"},{"speaker":"つる委員","kind":"質問・要望","question":"そういう意味では、品川区内も一生懸命、今やられているわけですが、ただ１点言えることは、ハード面では一つ一つバリアフリーになっているのだけれども、点と点がしっかり結ばれていないという課題が逆に言うとあるということで、もう一歩、先に進めるというところでは、そうした充実したバリアフリーのところをしっかりと結びつけていくという動線の確保がやはり重要なのかというところで。","respondent":"中元広報広聴課長","answer":"今後につきましては、地域におけるバリアフリー化の動きとの整合性も必要かと思ってありますので、その辺のところで、車いすの方が通れるルートというものが、ハード的なものが整っているところの進展状況を注視しつつ、ニーズに応じまして対応してまいりたいと考えております。","voiceIndex":20,"id":"exchange-009"},{"speaker":"つる委員","kind":"質問","question":"次にいきたいと思います。品川音頭リニューアル経費であります。これは、総務委員会において陳情が出て、先ほど説明の中であった「八潮」という名称を入れるということで、全会一致で採択されたものでありますけれども、まずそもそも品川音頭の由来を教えてください。","respondent":"中元広報広聴課長","answer":"品川音頭の由来ですが、昭和５３年に品川音頭がつくられてございまして、その歌詞は公募されているところです。公募の中から区民の方の歌詞が選ばれまして、そちらを、プロの石本美由起先生が補作詞を行われ、また名誉区民である服部良一さんが作曲して、でき上がったものです。","voiceIndex":22,"id":"exchange-010"},{"speaker":"つる委員","kind":"確認","question":"歳入のところの質疑でも、シティプロモーションとか、そういった観点の質問の中で、品川区の誇りだとか郷土愛、愛着だとかを、しっかりと醸成させていく必要性もあるというご答弁がありましたけれど、２００８年の本会議での区長のご答弁の中でも、やはり品川音頭については、「疎遠になりかけた人と人とのきずなを再構築して。","respondent":"中元広報広聴課長","answer":"周知方法につきましては、まだこれからのところですので、現在、まだ陳情が採択されたということですので、今後、区民の方への周知方法は、様々なＰＲを検討してまいりたいと思います。","voiceIndex":24,"id":"exchange-011"},{"speaker":"つる委員","kind":"提案","question":"やはり今回、イメージアップ運動経費という中に位置づけられていて、オリンピック・パラリンピック推進特別委員会でも文化プログラムの視点で提案したのですが、例えば新しくリニューアルするに当たって、制定の４０周年は２０１８年９月１日だと思うのですが、今回、区制７０周年の周知事業が９月ぐらいまでやるということが１つある中で、例えばリニューアルに合わせて。","respondent":"中元広報広聴課長","answer":"初めに、すみません。先ほど採択と申しましたが、総務委員会での審議等のことです。今の大変大きなイベントのご提案は参考とさせていただきまして、周知方法につきましても今後、検討させていただきたいと思います。","voiceIndex":26,"id":"exchange-012"},{"speaker":"つる委員","kind":"提案","question":"ぜひ、品川音頭、学校などでもしっかりやられていたり、体育大会とか、そういったところでもやっていますけれど、やはり１つの契機というのですか、これからの７０年とか、そういう意味でも、八潮が今回加わるということでは、これは「八潮」の言葉で、一回、総務委員会でお聞きしたときに、わかりませんということだったのですが、改めて総務課長に調べていただいて私も確認したら、当時の資料を見ると。","respondent":"提坂戸籍住民課長","answer":"今後、戸籍住民課の組織改正も控えておりますけれども、その上で、どういったサービス、ワンストップサービスということもありますけれども、いかにして業務を広げていくことができるかということで、ほかの課とも連携して検討してまいりたいと考えております。","voiceIndex":28,"id":"exchange-013"},{"speaker":"つる委員","kind":"質問","question":"時間の関係で、ちょっと漠然とした聞き方だったのですが、いわゆる手続で、ここをどうする、どうしたらいいというのはやっていると思うのですけれども、いわゆる各所管にかかわる、今やっていただいているところにかかわる相談ということで、今後、検討いただければということで、また別の機会で質問したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"２１１ページの大井町サービスコーナー業務委託を伺いたいと思います。しかし今回は、時給１,０００円で、繁忙期には２時間とか３時間の短時間勤務の方となれば、やはり抵抗があると思います。プライバシーを知ることができる業務を、短時間パートに、本人確認、手続、個人情報の保護を求めるとは、仕事の責任や役割に対して時給１,０００円とは、これが適切だと思うのかどうか伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"本年の４月１日から、大井町サービスコーナーについて、一部業務委託を導入する予定です。","voiceIndex":34,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"私が伺ったのは、庁舎の実施について、その実施の条件とは何かと伺いましたので、この点も伺いたいと思います。損害賠償と言いますが、流出した情報を持つ本人に何を補償するのか、情報の流出を止めることができるのか、伺いたいと思います。先ほども伺いましたが、こういった重要な仕事の待遇が時給１,０００円。こうした責任に見合う待遇だと思うのかどうか、この点も伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"庁舎における民間委託の導入についても、大井町サービスコーナーの民間委託が実際にこれから始まるわけですので、運用状況を見極めながら検討していきたいと考えておりますけれども、あくまでも実施条件ということで、窓口における受付事務、あと形式的なご本人確認とか。","voiceIndex":36,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"私が伺ったのは、流出した情報を持つ本人に何を補償するのか、損害賠償と言っているわけですから、その点を伺いたいと思います。それで、損害賠償で、情報が流出することを止めることができるのか、この点を質問しましたのでご答弁を伺いたいと思います。個人情報漏えいという重大事態であっても、なぜ契約解除ができないのか、逆に言うとどういう事態であれば契約解除ができるのか、伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"区と事業者の間で契約書を正式に取り交わすわけですけれども、その中の契約条項の中で、契約を解除するということの規定が明記されておりまして、その第１５条の中で「契約の締結または履行に当たり不正な行為をしたとき」と明記されておりますので、その辺の個人情報の流出が。","voiceIndex":38,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"質問とちょっと違うのですけれども、先ほども伺った点ですが、本人の情報が流出した場合は何を補償するのか、情報の流出を止めることができるのか、この点を伺いましたので、ご答弁を伺いたいと思います。今度は委託会社と区の職員に分ける２段階のサービスへの変更ですから、特に仕事が忙しくなる土曜日の繁忙期には、逆に区民に手間と時間をとらせることになると思います。","respondent":"提坂戸籍住民課長","answer":"情報流出というのはあってはならないことですけれど、万が一、情報流出があった場合に、事業者の中の業務責任者と区側のほうで連携をとって、即座に、被害に遭われたご本人の方と連絡をとって、被害を最小限に食いとめるように努めなければいけないことだと存じます。","voiceIndex":40,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"一度漏えいした情報を、一度流れると止めることができないというのが、今の社会の実態だと思います。サービス向上と言いますが、窓口業務について、実は一番多い対応というのは、どういった書類が必要かわからないけれども、書類が必要なのでとりに来ましたと、こうした業務が多いということを伺いました。そして、今回の業務委託だと、こうしたケースは誰が対応するのか伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"サービスコーナーの場合でも、まずその辺の聞き取りについては、審査とか、そういう類いのものではございませんので、一時的には事業者の方に行っていただいて、その辺で判断に苦しむ場合は、区の職員のほうに引き継いでもらって、区の職員がよく聞き取りを行って。","voiceIndex":42,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"現在の窓口は、職員が、これまでの仕事の経験も踏まえて丁寧に対応していると思います。窓口業務では、申請者が何を求めているかわからないときに、区職員にアドバイスを受けたり指示を仰ぐことができません。忙しいときほど、現在のワンストップサービスから担当者が代わる業務委託とは、かえって区民に手間と時間を与えるだけではないでしょうか、伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"それで、お客様を、より少しでも待たせないような形で、事業者のほうも工夫してもらいたいと思いますし、区のほうでも、どうすれば迅速性、かつ正確性を担保してサービスが提供できるかということを検討しまして、実行してまいりたいと考えております。","voiceIndex":44,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"こうした方々の仕事の役割や任務を思うと、あまりにも業務の中身が重過ぎると私は思います。こうした仕事を、時給１,０００円、繁忙期には２時間、３時間の短期の仕事にサービスの向上を求めるとは、仕事の責任と待遇が合わないと思います。契約書や仕様書の中に、こうした業務も窓口での対応を行うことが明記されているのでしょうか、伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"それ以外に個人情報の保護についても、きっちりと、禁止事項など、その辺を周知して、窓口に臨んでいただきたいと思います。失礼しました、それともう一点。","voiceIndex":46,"id":"exchange-021"},{"speaker":"中塚委員","kind":"確認","question":"親が子どもの住民票をとりに来る。こうした場合は、同一世帯でない場合は委任状が必要ですが、同一世帯かどうかの確認は、パソコンの画面で見る委託業者の役割です。土曜日など繁忙期にここでミスが起きると、区の職員が交付をする際の審査は、委託会社から申請書と印刷された住民票を照合するだけの審査のみで、本人確認もしません。これはやはり中止すべきだと思いますが、いかがでしょうか。","respondent":"提坂戸籍住民課長","answer":"大井町サービスコーナーで業務を行うのは、届け出事務は一切行っておりませんで、証明発行業務のみです。本庁舎において今後委託を予定しているのも、証明発行業務だけに限定する予定です。","voiceIndex":50,"id":"exchange-022"},{"speaker":"松永委員","kind":"質問","question":"こうしたことから、前年度予算では１,５３５万１,０００円で、本年度予算では９,７８９万円と、約６倍と増額になっておりますが、この設置される予定場所について伺いたいと思います。１カ所、取付けにかかる費用について、およそどのぐらいかかるのかもお願いします。","respondent":"仁平情報推進課長","answer":"Ｗｉ－Ｆｉのお尋ねです。来年度、平成２９年度の整備予定箇所ですけれども、まず総合庁舎、第二庁舎、議会棟、それと中小企業センター、そして中央公園が拡張されましたので、そちら向けのサービスも行います。","voiceIndex":53,"id":"exchange-023"},{"speaker":"松永委員","kind":"質問・要望","question":"庁舎内や中小企業センター、公園等、駅もありました。スポットに関して、ここはＷｉ－Ｆｉスポットだというようなステッカーや看板というのは、私もどこにあるのかあまりよくわからなかったのですけれども、それについてどういったところに設置されているのか、１カ所のスポット当たり、ステッカーを何枚張っているのかというのを、もしわかれば教えてください。","respondent":"仁平情報推進課長","answer":"次にビル内ですと、例えば本庁舎にフリーＷｉ－Ｆｉを入れたとしますと、片側ずつでおそらくアンテナ２カ所ぐらいを整備しないと電波が弱くなってしまうかと考えています。","voiceIndex":55,"id":"exchange-024"},{"speaker":"松永委員","kind":"質問・要望","question":"そこで、平成２９年度の予算の自治会館建設等補助について、もし今回、会館が設置される予定があるのか、含まれているのか、伺いたいと思います。耐震診断や耐震補強設計の補助を受けられた町会・自治会について、今回の平成２９年度予算ではどのぐらいあるのか、また今までどのぐらい受けられているのか、伺いたいと思います。","respondent":"伊崎地域活動課長","answer":"予算上の会館建設等補助の予定件数ですけれども、見込みとしましては、予算上は、新築１件、修繕７件、耐震診断５件、耐震補強設計８件、耐震改修８件ということで予算のほうは計上しています。","voiceIndex":57,"id":"exchange-025","title":"町会・自治会支援"},{"speaker":"松永委員","kind":"質問・要望","question":"先ほど質問すればよかったのですが、活動拠点の賃借補助についても、多分、要望があってつけられたのかと思うのですけれども、町会・自治会に対しては、そういうふうに要望があったところだけなのか、それともその対象にしているところ全てなのか、周知のほうはいかがでしょうか、伺います。","respondent":"伊崎地域活動課長","answer":"賃借料の補助につきましては、ご要望、お声は、会館の確保ということでいただいてきております。それで、もちろんご要望があったところだけではなく、制度設計をいたしまして、契約を交わして借りていらっしゃるところには補助していこうと考えているところです。","voiceIndex":59,"id":"exchange-026","title":"町会・自治会支援"},{"speaker":"筒井委員","kind":"質問・要望","question":"私からは、１７５ページ、シティプロモーション推進経費、２０１ページ、防災区民組織育成費です。シティプロモーションから伺います。区民によりわかりやすくするために、より実効性あるシティプロモーションのために、そうした各キャラクター、ロゴのうまい連携というものをすべきと考えておりますけれども、区のお考えはどのようなものになっているでしょうか、お知らせください。","respondent":"中島企画部副参事","answer":"っと驚く品川区の魅力を、ロゴマークを使って発信していきたいですので、今回、観光大使になりましたシナモロールとも相乗効果を十分期待できると思いますので、そちらについては観光部門とよく連携して展開を図って、区を挙げて魅力発信に努めてまいりたいと考えています。","voiceIndex":62,"id":"exchange-027"},{"speaker":"筒井委員","kind":"質問","question":"ということは、シナモロールが、例えば「わ！しながわ」のロゴマークを持つとか、そうした具体的な取組みというのは考えておられるのでしょうか。","respondent":"中島企画部副参事","answer":"観光部門のほうからも、既に「わ！しながわ」のロゴマークとシナモロールを合わせた、コラボレーションさせた提案も、著作権を持っているサンリオと相談しているという話も聞いておりますので、その辺のところについては今後具体的にお示しできればと思っています。","voiceIndex":64,"id":"exchange-028"},{"speaker":"筒井委員","kind":"質問","question":"ぜひよろしくお願いします。そして、あと品川区のホームページに、これが品川区の売りだ、これが品川区のアピールポイントだという、一覧性の高いページをつくるべきだと考えております。既存のページを活かすので、そこまで費用と労力がかからないと考えておりますけれども、そうした一覧性の高いページをつくるということについては区としてはいかがお考えでしょうか。","respondent":"中島企画部副参事","answer":"今後いろいろ具体的に活用してまいりたいと思いますが、その中に、住み続けたい理由ということで、交通のアクセスがいいでありますとか、便利で楽しいお買い物、あと色彩豊かな公園と憩いの水辺でありますとか、子育て・教育。","voiceIndex":66,"id":"exchange-029"},{"speaker":"筒井委員","kind":"質問・要望","question":"そうしたマンションがどんどん増えていきますけれども、そうした場合、区民消火隊の訓練が、ポンプ隊だけではなくて、マンション火災に十分対応した実践的訓練、そしてマンション住民が実践的訓練だということでメリットを感じるような訓練をやりたいところなのですけれども、そうしたマンション火災、災害に対応したアドバイスを、区としても行っていただきたいと考えているのですけれども、その点。","respondent":"古巻防災課長","answer":"こちら、消防のＯＢをマンションの防災アドバイザーとして任用いたしまして、マンションのほうへ、防災セミナーの実施でありますとか、マンションの、今、委員からもご指摘のありました、各種の訓練の指導でありますとかプランの作成、そういった全体の支援。","voiceIndex":68,"id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"高層マンションアドバイザー制度、ぜひとも進めていっていただいて、そしてまた、さらによりよく拡充していっていただきたいと考えております。そこで、やはり区が行政として、各マンションの自主防災組織同士の連携づくりのサポート、コーディネートを、ぜひともしていただきたいのですけれども、区としてはどのようにお考えでしょうか。","respondent":"古巻防災課長","answer":"ただいま、マンション同士の交流ですけれども、こちらは防災課の事業ということではないのですけれども、品川区のマンション管理組合の防災対策等検討交流会というものを実施しておりまして、その中で、防災課といたしまして、防災対策のアドバイスのサポートを行ったり。","voiceIndex":70,"id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひとも進めていっていただきたいと思います。そうした防災という点を基軸として、町会の加入の促進にもつながるかと思いますので、ぜひともその点、よろしくお願い申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-032"},{"speaker":"横山委員","kind":"質問・要望","question":"お願いいたします。１点目は、ホスピタリティハウスについてお伺いいたします。リオデジャネイロオリンピック視察報告書のホスピタリティハウスの部分から、幾つか確認させていただきたいと思います。我が国文化と産業の発祥地として、あまねく都民の心のふるさとであります品川区ですが、初めにお聞きしたいのは、ジャパンハウスの誘致の可能性について、区としてはどのようにお考えでしょうか。","respondent":"小川オリンピック・パラリンピック準備課長、古巻防災課長","answer":"３点目、品川ハウスの設置ですが、現在、区がイメージしているのは、まだ具体的な場所は未定ではありますが、やはりどこかの国あるいは企業ですとか、ホスピタリティハウスを誘致し、そこでは、リオでわかったことですが、大変。今後、現在、ターミナル駅では、帰宅困難者対策協議会、区が国道１５号線の徒歩帰宅者の支援対策協議会の運営をしておりますけれども、今後、大崎・五反田周辺での対策も進めていく予定とともに、事業者とともに訓練などを実施し。","voiceIndex":74,"id":"exchange-033"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１年前の予算特別委員会で質問させていただきまして、決算特別委員会でも改善策について改めて確認させていただきました。今後、休憩室で、着つけということで、やはりなかなか普段とは違うことですから、やはり抵抗があるということで、着つけ等、直し等に利用したいというご要望があったと聞いておりますけれども、こういったことをしていただけるのかどうかということです。","respondent":"久保田総務課長","answer":"今回、成人式が終わった後に、この運営をしていただいた育成会の方々と意見交換を行いまして、着つけのお話もありますし、一般の方もそうなのですけれども、例えば着物の形が崩れたので直したいとか、気分が悪くなったときに。","voiceIndex":78,"id":"exchange-034"},{"speaker":"あくつ委員","kind":"提案","question":"見たら、結構、ほかの２３区でも置いているところはたくさんあるのですけれども、普段からそういう練習をやったり、スリーオンスリーをやったり、そういうのを見ることによってやりたい子どもたちも増えてくるということで、ぜひ公園へのバスケットゴールの設置、そういう声が届いているのかどうか、そういったことをご検討いただけるのかどうか、お伺いしたいと思います。","respondent":"中島企画部副参事、溝口公園課長、池田スポーツ推進課長","answer":"最後に、次回の開催地につきましては、今後様々な観点から検討してまいりたいと考えています。ただ、一方でスポーツ振興という観点もありますので、今後も区内公園整備に合わせて、どういったところで設置できるのか。今、公園課長が申し上げましたように、今後、場所があればということで検討するところですけれども、ただ実際に今。","voiceIndex":80,"id":"exchange-035"},{"speaker":"あくつ委員","kind":"提案","question":"最後に２０１ページ、区民消火隊助成金で、先ごろ一般質問で松澤委員が質問された区民消火隊の総合大会、私も大賛成です。ですから、ここは何かモチベーションが必要だというのはすごく感じますので、ご検討いただきたいと思います。今のところ、東京でも８区ぐらいが今、その助成をしておりますので、ぜひそこのところをご検討いただきたいと思いますが、現状のところはいかがでしょうか。","respondent":"古巻防災課長","answer":"総合大会に関しましては、先ごろ一般質問でもお答えさせていただきましたけれども、一般区民で構成されております区民消火隊やミニポンプ隊に関しましては、今現在、まだ基本操作を習得する段階であるというところで、現状で地域防災訓練等で披露していただき。","voiceIndex":84,"id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私も区民消火隊に登録して練習、訓練しておりますけれども、やはり１つ目標があったほうが、消防団を見てもわかりますようにモチベーションが上がるということもありますので、身につけた技を、ぜひ後継に伝えていくということを含めると、総合大会といったものを活用するというのも１つの手法だと思いますので、ぜひご検討いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-037"},{"speaker":"田中委員","kind":"質問","question":"１６７ページ、１項総務管理費、１目一般管理費、男女共同参画センター運営費、１７３ページ、２目広報広聴費、ＣＡＴＶ事業、区提供番組制作費、関連して平和事業についても伺いますので、よろしくお願いします。１９７ページ、２項地域振興費、４目防災対策費。２０１６年の予算では、５５２万９,０００円でした。２０１７年度予算で減額してしまった理由をお聞かせください。","respondent":"島袋人権啓発課長","answer":"減額の理由ですが、第１６期の行動計画における委員のメンバーの減員が原因と考えられます。","voiceIndex":88,"id":"exchange-038"},{"speaker":"田中委員","kind":"質問","question":"人数が少なくなったということで了解しました。品川区では、虐待防止ネットワーク推進協議会が設置されていますが、計画評価と進捗状況をチェックする協議会ではないということを２０１６年の予算特別委員会での答弁で伺っています。あわせて、この計画に対して、現時点で結構ですので、品川区が計画達成されたと思われる項目があればお知らせください。","respondent":"島袋人権啓発課長","answer":"どういったことかと申し上げますと、まずは被害があった方から相談が来た場合、今現在ですと、法律相談のほうでも、すぐに警察への対応をご紹介しているということなので、相談された方が直に警察に行かれているといった状況があるように聞いております。","voiceIndex":92,"id":"exchange-039"},{"speaker":"田中委員","kind":"質問","question":"計画達成されたと思われる点なのですけれど、では、すぐに対応ができるようになったということでよろしいでしょうか。そういった仕組みも必要だと思います。品川区配偶者暴力対策基本計画の計画期間は２０１５年から２０１８年度で、計画の折り返しとなります。同計画には、２０１８年度に見直しとは掲載されていますが、見直しのスケジュールを、わかる範囲でお知らせください。","respondent":"島袋人権啓発課長","answer":"その事前調査とはどういうことかと申しますと、やはり第４次の計画の推進状況の検証、国や都、あるいは近隣地区の動向などを調べながらやっていきたいと思っているところです。","voiceIndex":94,"id":"exchange-040"},{"speaker":"田中委員","kind":"質問","question":"ＤＶ未然防止と早期発見というところで、１１月にＤＶ防止月間が設定されていますが、品川区ではＤＶ月間の事業予定は考えているのでしょうか。","respondent":"島袋人権啓発課長","answer":"別段、この月間を通して啓発するということではございませんで、区といたしましては、通年を通しまして、男女共同参画センターにおきましては、パネル展示、あるいは１２月に関しましては人権週間の中でも必ず掲示していますので、特に月間は決めておりませんが。","voiceIndex":96,"id":"exchange-041"},{"speaker":"田中委員","kind":"提案","question":"１つ提案です。これは２０１０年に、広告業界の直木賞と称されるＴＣＣ賞に選ばれたもので、ＤＶ支援などに取り組むＮＰＯが作成したものです。ちなみに、大田区でも、ＤＶ防止月間に合わせてこの写真パネルの展示会が行われたそうです。今年のＤＶ月間に、ぜひ品川区でも展示開催を検討してみてはいかがでしょうか。","respondent":"島袋人権啓発課長","answer":"ＤＶの理解者基礎講座の中では、加害者対応、先ほどもお話しされました、誰もが加害者になる、でもそういった意味の実感がないというところもありますので、まずはこの２月に職員向けに研修をさせていただきましたので、地道ではありますが。","voiceIndex":98,"id":"exchange-042"},{"speaker":"田中委員","kind":"質問","question":"前向きなご答弁をありがとうございました。次に、１７３ページ、広報広聴費、ＣＡＴＶ事業と平和事業について伺います。このＤＶＤは、多くの場面で有効に活用されてほしいと考えています。「子どもたちの戦争」のＤＶＤは、授業の活用にと、２０１６年に区立小・中学校全校に配布されたと伺いました。配布されたことは評価しますが、区としてはどのような活用を促されたのでしょうか、伺います。","respondent":"中元広報広聴課長","answer":"こちらは、区民の方に、戦争の記憶を風化させることを防ぐために、テーマごとにまとめさせていただいたものであり、また、中で子どもたちの授業でも活用できるものがありましたので、校長連絡会等で、私が出席させていただいて説明させていただき。","voiceIndex":100,"id":"exchange-043"},{"speaker":"田中委員","kind":"質問・要望","question":"作成したからには、どのように利用してほしいという目的があったと思います。ぜひ、ＤＶＤは区民の税金でつくられていますし、ＤＶＤを提供するだけではなく、区が活用の意図を持って積極的に平和事業に活かしていただきたいと思います。平和事業の観点からも、改めて区としての見解を伺います。","respondent":"久保田総務課長、村尾教育総合支援センター長","answer":"こうしたＤＶＤ、貴重な戦争の体験を伝えるというものですので、平和事業の中でも、私どもも広報広聴課等とも連携しながら活用していければと思ってあります。当然、国語科または社会科を含めて、または市民科等、各学校でそれぞれの機会に応じて、どのような形で取り組むか、これについてまた改めて各学校とも連携を図っていければと考えております。","voiceIndex":102,"id":"exchange-044"},{"speaker":"田中委員","kind":"提案","question":"戦争当時、宮前小学校から学童疎開していた方からお話を伺いましたが、当時の体験を語り継ぐことが今こそ重要で、いつでもそのような機会があれば呼んでほしいということをおっしゃっていました。平和事業の一環として多くの区民が身近な戦争の歴史を知る機会をつくることを提案したいと思います。区の見解を伺います。","respondent":"木村品川図書館長、久保田総務課長","answer":"貴重なご提案をいただきました。ご案内のとおり、図書館では上映会を行っておるところでございまして、その中でも、今のご提案を含めまして検討させていただきたいと考えています。今、ＤＶＤのご提案をいただきましたけれども、私ども、ＤＶＤ、このようなものを大事に活用していきたいという考えもあります。","voiceIndex":105,"id":"exchange-045"},{"speaker":"田中委員","kind":"質問","question":"ぜひよろしくお願いします。１９７ページ、２項地域振興費、４目防災対策費について伺います。防災会議費の中に地域防災計画改訂経費が計上されています。プレス発表６６ページによれば、修正内容として避難所運営が含まれていますが、修正内容と見直しに向けたスケジュールをお知らせください。","respondent":"古巻防災課長","answer":"その素案を１回目の防災会議に諮らせていただきまして、その後、東京都への事前の確認でありますとかパブリックコメントを実施した上で、最終的に年度末に防災会議で最終案を決定するというような形の流れで、進めていこうと考えているところです。","voiceIndex":108,"id":"exchange-046"},{"speaker":"田中委員","kind":"質問","question":"要配慮者と言われる人、つまり障害のある方、要介護者、妊産婦、ＬＧＢＴ、子どもたちに向けて配慮した計画にしようとはされているのでしょうか。防災計画に限りませんが、一般的にこのような計画は、健康な成人男性の発想で計画策定がされがちです。計画の改訂に向けては、様々な当事者が参加して議論に加わる仕組みの構築が必要だと考えます。このたび、どのように参加を図っていくのか、お考えを伺います。","respondent":"古巻防災課長","answer":"今ご質問いただいた点ですけれども、様々な視点をですと、避難所の対応でありますとか、避難生活のそういった支援ですとか、そういったところに関しましては、今まで様々な災害の中でクローズアップされてきた部分がありますので、そういった視点をなるべく取り入れて。","voiceIndex":110,"id":"exchange-047"},{"speaker":"田中委員","kind":"質問","question":"要配慮者への配慮というのは、いろいろな、各被災地で本当に問題になっているので、ぜひその当事者の声を聞くことを必ずお願いします。議論の場への参加だけではなく、実際の災害を想定したシミュレーションを、障害者福祉課や関連する所管課と連携して行うなど、具体的な取組みを導入して改訂に活かすことはできないでしょうか、見解を伺います。","respondent":"古巻防災課長","answer":"庁内のそういった素案の作成の段階におきまして、庁内で会議体をつくりまして十分な議論はしていくつもりでおりますので、そういった中で、今ご提案いただいたような点も含めまして様々な検討を加えていきたいと、また。","voiceIndex":112,"id":"exchange-048"},{"speaker":"田中委員","kind":"質問","question":"当事者の声を聞くということで、どのような場面で当事者の声を聞いていこうと考えていらっしゃるか、最後に伺いたいのですが。","respondent":"古巻防災課長","answer":"当事者の意見を伺うですと、防災課が主体というよりは、各所管を通しまして、そういった声が届くような形で会議体を進めていきたいと考えております。","voiceIndex":114,"id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"それで、品川区は、２０１２年７月策定の公共施設有効活用プランを発展的に継承するものとの位置づけですが、中身について伺いますけれども、有効活用プランにある新規施設抑制、新規施設の検討の際には既存施設の統合や複合化を含め検討。同時に進め方についても伺います。この前身となる有効活用プランのときはパブリックコメントは実施したのでしょうか、しなかったのでしょうか、伺います。","respondent":"柏原企画調整課長","answer":"それで、公共施設有効活用プランの際には、これは内部の計画というところもありまして、こちらのほうではパブリックコメントは実施はしてございません。","voiceIndex":118,"id":"exchange-050"},{"speaker":"安藤委員","kind":"質問","question":"それで伺いますが、コストの問題も問題にしていますけれども、毎年２５億円のコスト超過がこれから予想されるので、削減も必要だみたいなこともおっしゃっているのですが、品川区はこれだけ基金を積み立てて、健全財政も述べているのですが、毎年２５億円のコスト超過を予想としていますけれども、財源を確保できないという認識なのですか。それも伺いたいと思います。","respondent":"柏原企画調整課長","answer":"そういったことからしますと、このコスト、こういった経費をどうやって抑えていくのか。過去３０年と比べても、２５.９億円のコスト増が見込まれるです。ここを抑えるというのが１つポイントだというのは、お示しさせていただいたです。","voiceIndex":120,"id":"exchange-051"},{"speaker":"安藤委員","kind":"質問","question":"すぐ足りる、足りないというわけではない。コストを削減していく。長寿命化を主眼に据えた計画にこそすべきだと思いますけれども、伺いますが、長寿命化を進めることで更新コストが減らせて、維持管理コストはもちろん増えてしまう面はあると思いますが、トータルで更新コストを減らせるわけですから、私は経費は大幅に減らせるという認識なのですが、区もそういう認識でよろしいのでしょうか。","respondent":"柏原企画調整課長","answer":"こういった、やらせていただいているという段階で、これはパブリックコメントに準じた形での行動とこちらは認識しています。それから長寿命化のお話がございました。","voiceIndex":122,"id":"exchange-052"},{"speaker":"安藤委員","kind":"質問・要望","question":"骨子ということなのですが、今後、パブリックコメントを必ず行っていただくよう要望したいと思います。これによりまして更新コストを減らせるわけですから、長い目で見れば大幅に経費は削減、抑制することができます。だから、こちらを中心にしっかりと進めていただきたいと思います。品川区は施設不足問題をどう解決していこうとしているのか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"長寿命化ということをこちらの計画にも謳わせていただいて、それをした上で、建物というのは限界が来ますので、そこに合わせての更新ということをお示しさせていただいたですので、長寿命化だけで物事が解決するとは認識してございません。","voiceIndex":124,"id":"exchange-053"},{"speaker":"安藤委員","kind":"質問・要望","question":"確実に施設不足が進んでいくわけです。ここに対しての問題をどう考えているかというのを伺ったので、もう一度お伺いしたいと思います。そうだと思います。３０年、４０年を見据えた１０年間計画です。今から３０年、４０年後のことを考えて、削減するということを決めてしまってはいけないと思いますので、そうした施設の削減、統合化などを今から決めないように求めますけれども、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"繰り返しの部分はありますけれども、こちらは、今後のそういった行政需要、それから人口の動きといったところを踏まえて計画をつくって進めていこうという計画ですので、この計画をお読みいただいた中で、区の考えがおわかりいただけるのではないかと思ってあります。","voiceIndex":126,"id":"exchange-054"},{"speaker":"渡部委員","kind":"質問","question":"１６１ページ、２０５ページの辺で、いよいよクレジットカードを導入して税金を払えるというところで、ここの中でのお話と、１８１ページの自治会活動賠償責任保険加入助成のところで伺ってまいります。発生するのであれば、どれぐらいになるのか教えてください。だ何だというのは置いておいて、どのような形でいくのか、ちょっとそこまで教えてください。","respondent":"黒田税務課長","answer":"ただ、先行自治体に伺いますと、年間収入額の１％程度がクレジットで収納されているというような実績も伺っておりますので、そういったところから、これから算定してまいりたいと考えています。","voiceIndex":129,"id":"exchange-055"},{"speaker":"渡部委員","kind":"質問","question":"ただ、クレジットになると、前に課長に伺ったところ、特別徴収みたいに１回登録してというわけではなくて、毎月毎月、引き落としの作業もしていかなければならないようなところも伺ったのですが、その辺の細かい仕組みですとか、どのタイミングで、例えば口座引き落としを依頼していたのであれば、切っていただいて、クレジットに切り替わるなども、ある程度、周知いただけたらうれしいと思うのですが。","respondent":"黒田税務課長","answer":"これが平成３０年１月スタートということで、これからシステム改修等の詰めも行ってまいりますので、間に合う時期に、広報等で、クレジット納付の開始ということはお知らせしていきたいと思いますが、委員からご指摘がありましたとおり。","voiceIndex":131,"id":"exchange-056"},{"speaker":"渡部委員","kind":"質問・要望","question":"そうですね。ですので、クレジットカードが始まりますというところでの何か質問等があった場合は、丁寧な対応をこれからもしていっていただきたいと思いますので、これは、では要望にして、この質問は終わらせていただきます。楽しみにしています。１８１ページです、自治会活動賠償責任保険の加入助成ということで、本年度から新たにスタートいたします。","respondent":"伊崎地域活動課長","answer":"こういったことから、町会の活動支援を強化するということで、今回、来年度から保険を改め、ふれあい保険はやめまして、改めて今回計上させていただきました自治会活動賠償責任保険、こちらは既存のパッケージの保険ですが、こちらに加入をしていただこうということになりました。","voiceIndex":133,"id":"exchange-057"},{"speaker":"渡部委員","kind":"質問","question":"すごく、今までのふれあい保険のほうで、危険なことというものに対する認識というのも違ったのですが、交通安全も危険なのだ、夜警も危険なのだ、それこそ資源回収等していただいているのも危険なのだと思っていたのですが、その辺が全てケアされるということで、ただ、今その３つを事例に出しましたけれど、逆に申しますと、今までケアされていなかったような町会行事も、ほぼほぼと言っていいのでしょうか。","respondent":"伊崎地域活動課長","answer":"受け取る交付金といいますか、支給額のほうにつきましても多少変更がございまして、賠償責任につきましては２億円から５億円にアップ、それから死亡・後遺障害につきましても３００万円から４００万円にアップということで、こういったところが保険として拡充されております。","voiceIndex":135,"id":"exchange-058"},{"speaker":"渡部委員","kind":"質問・要望","question":"その辺も多分、今まで独自で入っていらっしゃるようなところというのは、興味があるというよりも、聞いていってどうするべきなのかと悩みどころだと思うのですが、その辺というのはもうしっかりと、この保険に入ったから大丈夫なのですと、ある程度言っていけるのでしょうか。","respondent":"伊崎地域活動課長","answer":"ですので、詳細も含めまして、４月の町会・自治会長会議の中できちんとご説明を差し上げ、また個別の案件につきましても、地域センターをはじめとしてご相談を承っていこうと考えております。","voiceIndex":137,"id":"exchange-059","title":"町会・自治会支援"},{"speaker":"渡部委員","kind":"意見","question":"そういうところにも、あえて、やはり品川区は様々な活動支援を町会でもしていただいていますから、その支援だけではなく、何か起こったときにも、この保険で手当てができるのです、しっかりと活動してくださいというような１つの手段にもなり得ると思いますので、丁寧なご説明をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":139,"id":"exchange-060"},{"speaker":"木村委員","kind":"質問・要望","question":"１６７ページの上から３行目、しながわ平和の花壇事業、そして１７１ページの水と緑の市町村との交流事業、同じページのしながわ発見出会い事業からの質問です。しながわ平和の花壇や平和の誓い像を設置し、また区内の中学校、新たに５校に、平和を象徴する花、カンナなどを植樹する事業が行われております。この平和宣言、平和を守ると、もう一度、力強いお言葉をいただきたいと思います。","respondent":"久保田総務課長","answer":"これからも、こうした事業を通して、恒久平和確立の精神を広く区民に訴えていきたいと考えております。","voiceIndex":141,"id":"exchange-061"},{"speaker":"木村委員","kind":"質問","question":"品川区からまたそういう力強い発信をお願いしたいと思います。次に１７１ページの上から３行目ですけれども、山北町との交流事業、７８９万円余、そして４行下、同じく早川町、１,５３１万円余から質問をいたします。なぜこのように大きく、予算の違いがどこにあるのかお聞かせください。","respondent":"伊崎地域活動課長","answer":"早川町につきましては、交流バスツアーということで、バスツアーを企画して、多くの区民の方に広くご利用していただこうということで、ツアー経費が主なものとなっている、そういったところが大きな予算の違いとなっております。","voiceIndex":143,"id":"exchange-062"},{"speaker":"木村委員","kind":"質問","question":"水と緑に象徴される自然環境の豊かな市町村との交流事業を通じて、健全でうるおいのある区民生活の実現を図るためにとあります。自然に触れる機会の少ない区民に、少しでも緑に触れていただくための事業だと思いますけれども、山北町、それから早川町ともに、年間何人ぐらいの利用者があるのか、また交流人口は増えているのでしょうか、ここ数年のデータがあれば教えてください。","respondent":"伊崎地域活動課長","answer":"交流の実績ですけれども、平成２７年度につきましては、山北町が４,２００人で早川町が２,６９０人でございまして、ここ数年、特に大きな動きはございません。","voiceIndex":145,"id":"exchange-063"},{"speaker":"木村委員","kind":"質問","question":"１人でも多くの皆さんに知っていただくために、どのような周知をしているのでしょうか、お聞かせください。","respondent":"伊崎地域活動課長","answer":"一方、山北町の皆様におかれましても、品川区に、いろいろなイベントのときにおいでいただきまして、山北町の物産などのご紹介をいただくなど、まちのＰＲに努めていただいているところです。","voiceIndex":147,"id":"exchange-064"},{"speaker":"木村委員","kind":"質問","question":"そうですね。次の、中ほどから少し下にありますけれども、坂井市交流ツアー、２０５万円余ですけれども、今回、坂井市と初めての交流ですけれども、交流を始める基準というのは何かあるのでしょうか。そして、全国の市町村から申込みというか、交流をしたいというような申込みがあるのかどうか、お聞かせください。","respondent":"伊崎地域活動課長","answer":"今年で３年目となりますけれども、その一環としまして、品川区の皆さんに坂井市の魅力を知ってもらうということで、こういったツアーを企画したものです。","voiceIndex":149,"id":"exchange-065"},{"speaker":"木村委員","kind":"意見","question":"その１行下にありますけれども、またこれはちょっと違う事業ですけれども、しながわ発見出会い事業というものがありますけれども、これを見ると、何となくお見合いのような事業だと思っていたのですけれども、そうではないということでありますから、これの内容をお示しください。","respondent":"伊崎地域活動課長","answer":"しながわ発見出会い事業ですけれども、この事業の目的としましては、品川区にかかわりのある若者、特に２０代、３０代を中心にしまして、従来の学校や職場を超えた地域のつながりの場、あと出会いの機会を提供するということで。","voiceIndex":151,"id":"exchange-066"},{"speaker":"塚本委員","kind":"質問・要望","question":"私からは、１６５ページの大学との協働の推進、それから１９９ページの防災体制整備費、大体この辺で防災対策全般みたいな話になるかと思いますが、質問させていただきたいと思います。初めに大学との協働の推進なのですけれども、今年から始める事業ということで、プレス発表もされております。","respondent":"久保田総務課長","answer":"そうしたものを区政の中でいろいろと活かしながら区政を進めていきたいという思いがございまして、こういう中で両者が期待しながら連携を進めているというものです。協議会を立ち上げて、さらに今度は大学間の連携も進めていきたいということで、事業を進めていく予定です。","voiceIndex":154,"id":"exchange-067"},{"speaker":"塚本委員","kind":"意見","question":"大変に期待したい事業だと考えていますけれども、このプレス発表の中で、事業予算として幾つかありますけれども、地域社会貢献活動支援補助金というところで１００万円の予算ということになっております。これがどういった目的、どういった活動に充てられるというものなのか、ご説明をいただければと思います。","respondent":"久保田総務課長","answer":"主な内容等につきましては、しながわ大学連携推進協議会主体のプロジェクトを実施する際の経費や、また各大学において社会貢献活動を実施するときの経費に充てていただきたいということで、この補助金を創設したものです。","voiceIndex":156,"id":"exchange-068"},{"speaker":"塚本委員","kind":"質問・要望","question":"こういった事業の継続性がひとつ大事かと思っていまして、学生たちは一年一年で変わっていってしまうし、そうすると、また新しい人になっていくわけですけれども、事業の内容としては、品川区的に、政策課題はいろいろ１年単位で解決するという単年度のものではなくて、継続してトレースしながら解決していく、あるいは発展させていくというようなことが。","respondent":"久保田総務課長","answer":"それに加えまして、今回立ち上げるにあたりましては、各大学のほうから、やはり大学の特色を活かした活動がしたいという意見がございまして、どういうことかといいますと、やはり学生を参加させるような活動をやっていくのが。","voiceIndex":158,"id":"exchange-069"},{"speaker":"塚本委員","kind":"質問","question":"わかりました。もう一点なのですけれども、こういった形で品川区との連携の中で勉強された学生が、卒業後も、こういった活動をその後、非常にいろいろな、それで得た経験というか知見というか、そういったものを活かす場というのでしょうか、そういった学生たちが、さらに卒業後も活躍または活動できるような点についての、何か現時点での考えというか、そういうところがあるのかどうか。","respondent":"久保田総務課長","answer":"それで、品川区への卒業生等の貢献につきましても、これから協議会の中、また学生のディスカッションの中で検討していきたいと考えています。","voiceIndex":160,"id":"exchange-070"},{"speaker":"塚本委員","kind":"質問・要望","question":"続きまして、１９９ページ、防災体制整備費のほうなのですけれども、昨年、熊本地震が起こりまして、その後のいろいろな災害の復旧対策というところで、品川区としても、たしか現地に行かれて、教訓や、また品川区の防災対策への参考というようなところで、調査というか視察というか、なされているかと思いますが、そこで得た教訓や、今後品川区に活かすべき防災対策といったことについて。","respondent":"古巻防災課長","answer":"受援といったような課題もありますけれども、避難関係につきましては、避難所の運営でありますとか避難所外への避難、それから要配慮者への対応やペットの避難といったようなものが課題として浮き彫りになったのかと考えています。","voiceIndex":162,"id":"exchange-071"},{"speaker":"塚本委員","kind":"提案","question":"道路をしっかり、確保というか安全を保って、物資が通れるような、ハード面のインフラ整備というのもあるのですけれども、もう一方で、きちんと避難物資などが避難所に、必要なものが必要なときに届くような、ソフト的なインフラというところでの整備の大切さというところも訴えさせていただきましたけれども、その後昨年の１２月２０日に。","respondent":"古巻防災課長","answer":"ＩＣＴを活用した、そういった情報の共有でありますとか、やりとりといったところの部分のことかと思いますけれども、具体的にまだ区としてというのは、統一した見解というのは出せていない部分がありますけれども、様々な重要性があると認識して、研究を進めているところです。","voiceIndex":164,"id":"exchange-072"},{"speaker":"塚本委員","kind":"質問・要望","question":"ぜひ、この辺のところの検討をしっかりと進めていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":166,"id":"exchange-073"},{"speaker":"西本委員","kind":"提案","question":"高くないですか。設置の目的は何でしょうかとお聞きします。学校施設を貸していただいておりますけれども、用具の破損があった場合に対応はどうなされているでしょうか。そこら辺の使用者に対しての確認もしくは認識をどのようにされているのかお聞きします。第２回定例会でも一般質問でいたしました、避難所シミュレーションゲームの導入を再度ご検討願いたいと考えていますが、お考えをお聞きします。","respondent":"提坂戸籍住民課長、仁平情報推進課長、池田スポーツ推進課長、古巻防災課長","answer":"それで、民間の様々な経験、専門的な能力、おもてなし、その辺も活用させていただいて、お客様に証明書を間違いなくお渡しすることと。それと今後、平成２９年度となりますけれども、議会関係のタブレット使用の展開やデジタルサイネージの導入、それと、先ほど申し上げましたけれども。学校施設開放における備品類のことですけれども、学校の備品については、使用者側に、最後に原状回復して返すこととなっておりますので。","voiceIndex":168,"id":"exchange-074"},{"speaker":"西本委員","kind":"質問・要望","question":"今の答弁ですと、では職員は劣っているということになるのですか。そういうことも含めて考えていただきたいと思いますが、その件に関しての答弁をお願いいたします。それから地域スポーツの件ですが、使用者が、できれば損賠保険などというのを必ず入っていただくような形をとっていただきたいと思います。初期の避難所がどういう運営をしなければならないのか。幾つか答弁をお願いいたします。","respondent":"提坂戸籍住民課長、仁平情報推進課長、池田スポーツ推進課長","answer":"職員は個々、窓口業務の重要性を十分認識しておりまして、研修も受けて、能力向上に努めているところです。それと、アンテナの位置まではどうしてもケーブル工事が必要になってまいりますし電源工事も必要になってくるということで、この辺の経費を積み上げますと。保険の加入につきましては、スポレク推進委員会、地域スポーツクラブ等で周知していきたいと思います。","voiceIndex":173,"id":"exchange-075"},{"speaker":"渡辺委員","kind":"質問","question":"先週末、ちょうど障害者スポーツを見る機会が多くありまして、その中で、区が主催行事だったパラリンピックを契機とした障害者スポーツの講演ですか、戸越体育館で車椅子バスケットボールの催しに参加することができて、ものすごく、何でしょう、刺激を受けたというか、とにかくすごくいい感想です。今後の活動でもぜひ取り入れられたいと。今後に活かすべきかと思ったので、この２点をまず伺います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"ご指摘いただきました３月４日のパラリンピック啓発講演会ですが、戸越体育館を会場に、初めての試みではありますが、アリーナを半面に分けまして、１面を講演会の会場、１面を体験会の会場という形でやらせていただきました。","voiceIndex":178,"id":"exchange-076"},{"speaker":"渡辺委員","kind":"質問","question":"それで、リオの視察の話も先ほどありました。大分、整ってきたのだと。そういう意味で、今、もちろん東京都が中心でありますが、品川区も独自に開催周知を進めている効果、この点を伺えればと思います。２つ目は、先ほどの事例のように、障害者スポーツをはじめとしてバリアフリーの加速など福祉政策の加速ができる。そして防災まちづくり。どんな効果、大きな目標、施策目標を改めて教えてください。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そうした面で、ソフトの面でも、障害者スポーツを軸とした、子どもたちを中心に夢を与える事業ですとか、子どもから高齢者まで全体で、オリンピックを契機に全体が盛り上がって、品川区全体が活気づき、さらに元気になって品川区の魅力を発信するという機会になればということで。","voiceIndex":180,"id":"exchange-077"},{"speaker":"渡辺委員","kind":"質問","question":"プレス発表と各事業のところで伺います。というのは、大人数ですと、どうしても一方的な情報発信、受けとめで終わってしまう。施策の目的というのを１つ伺います。建物への、壁画もそうですし、もっと言えばプロジェクションマッピングみたいなことができるのかどうかも含めて、ぜひ、これから壁画ＰＲ、庁舎が第１弾であれば、ホップ・ステップ・ジャンプ、やったらどうかという思いで伺います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"は庁舎の壁画から３カ所、展開していきたいと考えています。","voiceIndex":182,"id":"exchange-078"},{"speaker":"のだて委員","kind":"確認","question":"私からは、５７７ページの災害復旧特別会計について伺います。この特別会計は、条例に「災害時における救助、復旧、復興をスムーズに行い、経理を明確にするために設置する」とあります。特別会計がなければ災害対応ができないわけではないということを確認させてください。","respondent":"秋山財政課長","answer":"災害復旧基金をつくったときにご説明を差し上げましたけれども、この基金がなければできないということではないという私の答弁は間違いございません。","voiceIndex":185,"id":"exchange-079"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、なぜこれが必要なのかわかりませんけれども、今でも災害対応はできるということだと思います。そのもとでやっていく、そして会計を明確にしていくということも言っておりますけれども、明確にする理由は何なのでしょうか。しなければいけないものなのでしょうか、伺います。","respondent":"秋山財政課長","answer":"要するに、今回で言えば災害の復旧という特定の事業に対して、特定の歳入、基金繰入金をもって、一般の会計、歳入・歳出と区分して、わかりやすく経理をする必要があると考えたので、今回、特別会計を設置したです。","voiceIndex":187,"id":"exchange-080"},{"speaker":"のだて委員","kind":"質問","question":"なぜ、わかりやすくしなければならないかということをお聞きしているので、ご答弁願います。","respondent":"秋山財政課長","answer":"それに対して区が何ができるのかというところを明確にするというところ。それから、委員会のときにご説明させていただいたのは、震災直後の一、二カ月の間に必要な財政的な準備をするのだというご説明を一番最初にしています。","voiceIndex":189,"id":"exchange-081"},{"speaker":"のだて委員","kind":"質問","question":"何ができるのか明確にするためだということですけれども、それは一般会計でやっていっても、何ができるのか明確にすることはできると思います。タイムラグもあるというお話もありましたけれども、このタイムラグの期間というのはどのぐらいになるのでしょうか。予備費など、現在の仕組みでも、タイムラグの間で対応できるのではないかと思うのですが、いかがでしょうか。","respondent":"秋山財政課長","answer":"タイムラグの話ですけれども、これは１つは自治体まで届くタイムラグというものもありますし、例えば予算を使うにしても、議会での補正予算の議決等々をいただくという期間も含めて、概ね一、二カ月と想定はしているものです。","voiceIndex":191,"id":"exchange-082"},{"speaker":"のだて委員","kind":"質問","question":"その一、二カ月の間で、補正予算、予備費など現在の仕組みで、それよりも早く執行することはできないのかということをお聞きしたので、伺いたいと思います。何ができるのか明確にというところでは、計画をつくったりしていく中で、区が何ができるかということは検討できると思うのですけれども、この特別会計でなくてもできるのではないかと思いますが、いかがでしょうか。","respondent":"秋山財政課長","answer":"予備費は、計上しているのは３億円程度ですので、それ以上の予備費を積むということは考えておりませんので、その範囲の中でしかできないということになります。","voiceIndex":193,"id":"exchange-083"},{"speaker":"のだて委員","kind":"質問","question":"予算という具体的なものを示したということですけれども、別に計画の中で具体的にしていくことも可能だと思います。予備費は例で挙げておりますけれども、ほかの現在の仕組みで１５億円の対応というのはできないのでしょうか。","respondent":"秋山財政課長","answer":"最初にお話を申し上げたとおり、この特別会計がなければできないものではないとお話ししましたので、答えとしては、できるということになりますが、今までご説明させていただいたような理由から特別会計を設置させていただいたです。","voiceIndex":195,"id":"exchange-084"},{"speaker":"のだて委員","kind":"質問","question":"特別会計がなくても対応は可能だということだと思います。次に、どこまで特別会計でやるのかという問題です。復興というのは、長期的なまちづくりにも関係してくるものであり、性急な執行はすべきではないと思いますし、委員会審議でも「特別会計の当初予算には、どんな復興が行われるのか想定できないため復興は入れない」という説明でした。復興まで条文に入れたのはなぜなのか、理由を伺います。","respondent":"秋山財政課長","answer":"条例上に「復興」の文字が使われているですけれども、これは委員会でもご説明をさせていただきましたが、災害の復旧や復興という文言に対して明確な定義というのは、今、日本ではございません。災害救助に関しては、災害救助法という中に定義があります。","voiceIndex":197,"id":"exchange-085"},{"speaker":"のだて委員","kind":"質問","question":"定義が曖昧ということですけれども、辞書を引くと、復旧は、壊れたり傷んだりしたものをもとの状態にすること。復興は、一旦衰えたものが、再びもとの盛んな状態に返ることとありますけれども、これとは違うということなのか、伺いたいと思います。あわせて、同じ認識でなくても、ある程度、分けているからこそ、今回、当初予算でも復旧までになっていると思いますけれども、区の認識もあわせて伺います。","respondent":"秋山財政課長","answer":"したがいまして、条例の中に復興が入っているからといって、復興までフリーハンドで区が何か使えるという説明をした覚えもありませんし、そういうことはできないと考えているものです。","voiceIndex":199,"id":"exchange-086"},{"speaker":"のだて委員","kind":"質問","question":"今の説明だと、時間の区切りが曖昧だということで、復旧・復興を分けることができないということでしょうか。例えば復興のための調査であれば、復興になるかもしれないというお話もありましたけれども、それは運用上の問題で、復旧のための調査とすれば、復興を入れる必要はなかったのではないかと思いますが、いかがでしょうか。","respondent":"秋山財政課長","answer":"繰り返しの答弁にはなりますが、復興というのが明確に、何々の事業は復興であるというのがきっちり決まっているわけではございませんし、決められるものでもないという状況の中で、どういうものにお金を使うのかという条例のつくりですから、救助、復旧、復興、そうはいっても。","voiceIndex":201,"id":"exchange-087"},{"speaker":"のだて委員","kind":"質問","question":"範囲を狭めたと言っておりますけれども、復興まで使えるということは、相当範囲が広いと思います。復興にも使えるということだと思います。私が懸念しているのは、復興の名のもとに再開発が行われて、もといた住民が追い出されてしまうのではないかということです。こういった面からも、特別会計を設置し復興にまで充てていくことはやめるべきだと思いますが、いかがでしょうか。","respondent":"秋山財政課長","answer":"それ以降の復興については、もちろんそれ以降に、予算執行のために議決をいただくわけですから、復興について何かフリーハンドで使えるようだというご説明をされているようですけれども、それは正確ではないと申し添えておきます。","voiceIndex":203,"id":"exchange-088"},{"speaker":"のだて委員","kind":"質問","question":"そうであれば、やはり復興とあるということは、そういった長期的復興にも使っていけるということになってきてしまうのではと思います。条文上は、復興としか書いていません。この基金をつくって、新たな貯め込みをしていくということになっていくという懸念もあります。こうした仕組みづくりはやめるべきだと思いますけれども、いかがでしょうか。","respondent":"秋山財政課長","answer":"一般会計からも、今、災害復旧特別会計をつくる前までも、一般会計から復興に予算を使うわけですから、おっしゃられるような、復興だという名目で特別会計から無尽蔵に資金が出ていくというような話は正確ではないと考えているものです。","voiceIndex":205,"id":"exchange-089"},{"speaker":"のだて委員","kind":"質問・要望","question":"復興については、長期的なまちづくりの関係もありますし、しっかりと吟味し、住民の声も、そして議会の審議も聞き入れて進めていくことを要望しておきます。最後に、復旧に対応することも大切ですが、被害を未然に防ぐ予防策も必要だと思いますので、積極的に進めてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":207,"id":"exchange-090"},{"speaker":"いながわ委員","kind":"質問","question":"実際、Ｗｉ－Ｆｉスポット事業に関しては、こうして予算立てをされて載ってくるので、すごく理解できるのですけれども、観光の視点で考えたときのＷｉ－Ｆｉスポットの設置を、どういう形で庁内で話し合いや連携をとられているかというのがなかなか見えてこないので、オリンピック・パラリンピック推進特別委員会でも区民委員会でも私は質問させていただいているのですが、実際、しているという話なのですが。","respondent":"仁平情報推進課長、鈴木文化観光課長、黒田税務課長","answer":"１点目の文化センターへの整備の考え方ですけれども、一応、今年度の中には予定は入れていないのですが、あくまでも予定ですけれども、来年度。具体的には、平成２８年度、今年度につきましても、予定をしていなかった不具合等で、換気扇の交換であったり。ご当地ナンバーの予算の経費の内訳ですが、予算として１０５万３,０００円計上させていただいておりまして、内訳といたしまして。","voiceIndex":209,"id":"exchange-091"},{"speaker":"いながわ委員","kind":"質問・要望","question":"Ｗｉ－Ｆｉに関しては連携をとって粛々と進めていただきたいと思います。それで、あとご当地のナンバープレートなのですけれど、デザインはこれから募集するとここに書いてあるのですが、そこはぜひ品川のシティプロモーションと連携した形で、全く違うデザインをしてもしようがないと思いますので、しっかり連携をとってやっていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":213,"id":"exchange-092"},{"speaker":"石田（秀）委員","kind":"質問","question":"もう一度、防災を、私が言いたいのは自助の部分をしっかり区のほうでも伝えてほしいと思っています。公助はもう、備蓄をいろいろして、避難所もどうだとやってくれるのはいいのですけれど、国はもう主要幹線道路をまず確保するために、３日間は勘弁してくれと公に言っているわけです。次の日はどうするんだ。この辺を強硬に言うべきだと思うのですけれど、そこら辺の自助の部分の考え方を教えてください。","respondent":"古巻防災課長","answer":"それから避難の仕方といったところで、ご自身の身をご自分で守るといったような考え方。そのような基本的な備えの内容を、今後きちんと伝えられるように進めていきたいと考えております。","voiceIndex":215,"id":"exchange-093"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そこに例えば少し助成があっても構わないけれども、自助の部分に対しての備えを必ずしてくれということを、もっと強く言っていただきたい。私は、ちょっと減っているのではないのかと思っているのだけれども、この辺の、もし今、区民斎場の部分については、減っている要因もわかっていらっしゃれば教えていただきたいし、どういうふうにしていこうと思われているのかというのをお聞きしたいと思います。","respondent":"提坂戸籍住民課長、鈴木文化観光課長","answer":"事情といたしましては、式を行わない、斎場のほうで直葬を行うという方が増えているということで、ただ、これから、こういう言い方もあれですけれど、高齢者の方が亡くなっていく件数というのが増えていきますので。その改修の程度につきましては、現状、古いものを保存しておりますが、実際に来館者の方に中をお使いいただけるような状態ではなくて、柱や土台のほうがもう大分傷んできておりますので。","voiceIndex":217,"id":"exchange-094"},{"speaker":"石田（秀）委員","kind":"質問","question":"区民斎場なのですけれど、２２５件の決算だったと。それで、今年、また減ってきて、予算としては、３００万円から２７０万円にしてきた。勝島の、これからいろいろ人も増えてくる。こういうことも含めて、水辺の活用の憩いの場として、私は、せっかくオリンピックが来るのであれば、活用して、そういうものをつくっていくべきだと思っているのですが、どうお思いでしょうかというのが１つ。","respondent":"提坂戸籍住民課長、鈴木文化観光課長","answer":"所管といたしましては、区民斎場、あと臨海斎場もそうなのですが、災害時に必要な施設ということで考えておりますので、ちょっと水辺の活用というのは、所管としては考えていないというのが実情です。ただし、とりあえずは、平成２９年度につきましては、茶室の緊急的な対応ということで予算を計上させていただきました。","voiceIndex":220,"id":"exchange-095"},{"speaker":"石田（秀）委員","kind":"意見","question":"どんどん火葬していこう。そのぐらいはあれとしても、活用する。これが、悪い方向のレガシーになってしまうのは良くないわけだけれど、こういうことをきっかけに前へ向かって、種をまいたのも花を咲かせていくみたいな、そういうことに歴史館などは非常に活用できるだろうし、なぎさ会館もそういう意味では活用できると私は思っているので、そこら辺はもう一度お考えをお聞かせください。","respondent":"柏原企画調整課長、鈴木文化観光課長","answer":"片や、やはり斎場にしても一定の用途がある、使っている方がいるというところ。それから災害の関係での使用の関係がある。そういったところを踏まえると、今すぐ何かできるかというと、なかなか難しい面もあろうかと思います。それと、観光のスポットということでも、今、検討していますので、できるだけ有効な活用を目指して、今後のあり方についても考えていきたいと考えています。","voiceIndex":223,"id":"exchange-096"},{"speaker":"こんの委員","kind":"提案","question":"生活安全推進事業ですけれども、区の防犯対策を、さらなる対策の強化を求めてお聞きしたいと思います。あわせてお聞きしたいと思います。ですので、更新されるこの機会にあたって、やはり設置の状況の改善や、あるいは設置場所の拡充、こうしたことを総合的に考えていくことが大事であると思いますが、こうしたことのお考えについて確認させていただきたいと思います。","respondent":"濱田生活安全担当課長、古巻防災課長","answer":"ただ、ふれあいポリス、委員が各警察署に２名ということはおっしゃいましたが、調査した結果、実際に品川区４署で２署しかまだおりません。大井署に２名、大崎署に１名。それで、運用開始は昨年の９月から行っているということです。今年度、平成２８年度、そういった調査を行いまして、子局の再配置や機器の更新等を含めて、今現在、なるべく聞きづらい地域が出ないような形での取組みも進めていきたいとは考えているところです。","voiceIndex":227,"id":"exchange-097"},{"speaker":"こんの委員","kind":"質問・要望","question":"防災行政無線のほうですけれども、今お考えをお聞きしました。具体的に１つ要望なのですが、実は大井町駅の西口のバスターミナルのところは配置がないのです。なので、駅そのものにないというのは、やはり必要な場所にこれから再配置をするのに、そうしたことも検討していただいたほうがいいのかと思いますけれども、いかがでしょうか。","respondent":"濱田生活安全担当課長、古巻防災課長","answer":"よって、私のほうから今後、連絡をとって、様々な行事等、一緒に連携して行っていきたいと思います。といってもおそらく、１００％どこでも明確に聞こえるというような形をとるのも難しいのも、また確かだと思いますので、先ほどご発言がありましたとおり、代替手段の対応についても、十分にここは検討していきたいと考えております。","voiceIndex":230,"id":"exchange-098"},{"speaker":"こんの委員","kind":"質問・要望","question":"少しだけ時間がありますので、要望だけします。ですが、確認というよりも要望で終わりたいと思いますが、いわゆる防災資器材の購入、町会の方たちが、この街かど消火栓を購入したい、自由ですが、その購入にあたっては、東京都の地域の底力再生事業助成金というのも活用できますので、ご案内をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":233,"id":"exchange-099"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それで、第４回定例会の一般質問で指定管理者制度と債務負担行為についてお尋ねしました。ご答弁をいただいたのですが、なかなかちょっと理解ができない部分もありまして、また確認させていただきたいと思います。総務省のほうに確認したところ、立場はこの通知の立場であると、５年後の現在もそういうお答えでした。総務省の見解との違いについても含めてお答えください、よろしくお願いします。","respondent":"秋山財政課長","answer":"５年間の金額を固定するというのは合理的だとは考えられませんで、例えば指定管理者の経営努力により委託料が低額でもできるということであれば、それは見直して減額すべきであるという形をとっておりますので。","voiceIndex":236,"id":"exchange-100"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"つまり、５年間の先を見据えた事業の５年分のことというのは、指定管理を指定する際の選考のときにわかるのではないかという点からも、先ほどお話ししましたが、協定ということの根拠と、もう一つ、５年間固定してしまうということが必ずしもその理由にはならないと思うのですが、いかがでしょうか。","respondent":"秋山財政課長","answer":"そうすると、限度額を超えてしまうということもありますので、当初の５年間の協定書において定め、詳細については年度協定によるという、委託料の請求の支払いに関する手続を規定して、毎年の年度協定において委託料の額を決定するということによれば。","voiceIndex":238,"id":"exchange-101"},{"speaker":"高橋（し）委員","kind":"質問","question":"ですから、協定でいいという根拠はどこにあるか。いいと思われているということはわかりました。その段階で債務負担行為が確定的になるわけでありますから、単年度協定であったとしても、委託料が伴う数年にわたる債務負担行為を、行政処分をする以上、債務負担行為が必要となってくると考えるのですが、そのあたりについてはいかがでしょうか。","respondent":"秋山財政課長","answer":"その請求の支払いに関する手続を規定しているので、年度協定で委託料の額を決定すれば、それは毎年の支払いの事実と同じように委託料として支払うことができるということで、債務負担行為、年度を超えた契約ではないということで考えております。","voiceIndex":240,"id":"exchange-102"},{"speaker":"高橋（し）委員","kind":"質問","question":"私も勉強不足で今のところあれなのですけれども、年度を超えて云々というお話があったのですが、指定管理者を指定するときに、プロポーザルなり、いろいろなことをしますけれど、そのときに、そこの事業者、指定管理の相手方は、５年間を見据えてこれだけの金額でということは言わないのですか。その金額がわかれば、債務負担行為の中で出してこれるのではないでしょうか。","respondent":"秋山財政課長","answer":"ご指摘の都道府県の例であるとか政令指定都市の例でも、半数程度がそういう形でとっているということからでも、特にそれが問題があるとは考えていないところです。","voiceIndex":242,"id":"exchange-103"},{"speaker":"伊藤委員","kind":"提案","question":"私は、５７７ページの災害復旧特別会計に関連して、それから１９７ページの防災会議費に関連して質問します。災害復旧特別会計のほうですけれど、これは平成７年に阪神・淡路大震災がありました。その後、総務委員長として神戸市にお伺いさせていただいて、財政が非常に厳しいという話を聞いて、その後、平成９年か、そのぐらいに、私は議会でこのことを提案させていただいた記憶があるのです。","respondent":"秋山財政課長","answer":"ただ、それ以降、阪神・淡路大震災を含めて、東日本大震災、それから特に直近では熊本の災害がございまして、そこで実際に国からの資金投入にはタイムラグがあるということ、それから、いざ発災というときに財政の稼働ができるような状況にしておいたほうが。","voiceIndex":246,"id":"exchange-104"},{"speaker":"伊藤委員","kind":"意見","question":"今おっしゃったように、様々なタイムラグがあるし、それから国も必ず、来ることはわかっているのだけれども、どうしてもやはり二カ月、三カ月かかるし、それから品川区の様々な予算の執行について、やはり議会の議決が必要なのだから、神戸市の時点からこうであるべきだということを前に言っていたので、実現したことはよかったのだけれども、何というか、もっと早くできたはずだと思うのです。","respondent":"中山企画部長","answer":"区としては健全財政で、例えばかなりインフラの部分がかかるということで、公共施設の整備基金であるとか、そういうものは充当可能であろうというのがありましたけれども、先ほどのご質疑でもありました、財政課長がお答えしたように。","voiceIndex":248,"id":"exchange-105"},{"speaker":"伊藤委員","kind":"質問・要望","question":"この話は議会の同意も要らない話です。それから、ダイレクトに品川区が情報を提供するようになっても、例えば品川区内の被害状況、災害の状況、それから安否の確認、避難所の案内、所在確認等々、様々なことが要求されてくると思うのだけれども、そういう情報提供の仕組みと内容についてどうお考えなのでしょうか、お聞かせください。","respondent":"古巻防災課長","answer":"災害時の情報の伝達、お知らせをするということの大切さに関しましては、区も同様の考えを持っておりまして、様々な手段を用いまして、防災行政無線然りですし、また先ほども申し上げたような、防災行政無線に代わる代替の手段、それからメールの活用といったことを、様々な手段。","voiceIndex":250,"id":"exchange-106"},{"speaker":"伊藤委員","kind":"質問","question":"だから、それをどう効率的に伝えていくかということは、スマートフォンや携帯などを使わない手はないですよね。パソコンもそうだけれども。これだけ情報機器が発展する中で、特に初動の情報提供の仕組みというのは、今、ざっくりとお答えいただいたのだけれども、もう少し細かいお考えはないのでしょうか。あわせてお答えください。お願いします。","respondent":"古巻防災課長","answer":"それに基づいた正しい情報を発信していくということになろうかと思いますけれども、そういう意味で言いますと、災害情報の管理システムといったようなもの、システムの機能強化を図るということも、来年、平成２９年度の予算の中で考えておりますので、そういった中で。","voiceIndex":252,"id":"exchange-107"},{"speaker":"伊藤委員","kind":"意見","question":"そのとおりです。それで、今、課長の話の中に出てきたフェイスブック、それからツイッター、ＬＩＮＥといったものは、平成２４年度につくった地域防災計画がありますけれど、このときはまだあまりなかったものでありますけれど、今、相当普及していますよね。だから、こういうＳＮＳの活用についても新たな段階に入ってきたと思うのですが、品川区のお考えをお聞かせください。お願いいたします。","respondent":"古巻防災課長","answer":"具体的にどういうふうに活用ができるか、情報なので、ＳＮＳによって間違った情報が伝わっていくというようなこともまた反面でございましたので、そういったところ、十分に正しい情報がきちんと伝わるような仕組みというものは、ＳＮＳを使うということも含めまして。","voiceIndex":254,"id":"exchange-108"},{"speaker":"伊藤委員","kind":"質問","question":"避難所のことは、今までいろいろな災害があった中で必ず言われてきたことですよね。だから、今のお話はわかるのだけれども、もっと言うと、地域の力とおっしゃるけれども、もしかすると地域の方々も疲弊するかもしれないわけではないですか。それから先に進みますと、ヘリポートがしながわ中央公園にできましたけれど、ヘリコプターの活用についてはどうお考えなのでしょうか。それだけお答えください。","respondent":"古巻防災課長","answer":"ヘリコプターの活用につきましては、臨時ヘリポート、中央公園を含めまして６カ所だったかと思いますけれども、指定しておりますが、物資等の輸送に関しましては、メインは陸上になろうかと思いますけれども、補完する手段として、また陸上がなかなかうまく使えない場合。","voiceIndex":256,"id":"exchange-109"},{"speaker":"石田（し）委員","kind":"提案","question":"ふれあい掲示板ですが、今いろいろと物がデジタル化されている中で、例えばこういった掲示板等も、デジタルサイネージも別のところですが導入され、技術革新もあるといった中で、こういった、いわゆるふれあい掲示板等もデジタル化について考えていってもいいのかと思いますが、その辺の考えをお伺いしたいのと、以前、第３回定例会でも提案いたしましたが。","respondent":"仁平情報推進課長、中元広報広聴課長、伊崎地域活動課長、古巻防災課長","answer":"それと東京都のほうでもカタログサイトを協働して運営したいということで、ここに品川区も参加していきますので。今後、委員からのご指摘もございましたので、年度更新作業等をする際などに、各課にてリンク切れなどの確認をするように。建替えにあたりましては、古いものを、新しい形のガラス、引き戸つきのものに変えていくというところを考えておりまして、デジタルサイネージ化。","voiceIndex":259,"id":"exchange-110"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"海外では、経済活性化の観点からも多くのデータが使われています。その辺は要望で終わります。熊本でも実際に通信事業者が、いわゆる好意で、社会貢献の一つとして無料で設置したわけであって、自助という話もありましたけれど、もちろん自助でやっていただくのは第一義的な部分がありますが、例えば、では家が倒壊してどうしても取れないときにどうするのですか。自助ではできないではないですか。","respondent":"古巻防災課長","answer":"おっしゃっていることは、よく理解はできます。事業者より提供の申し出ということがある、情報として熊本ではそういうことがあったですので、そのあたり事業者がどういうふうな対応ができるのかということは、十分に情報収集していきたいと思います。","voiceIndex":264,"id":"exchange-111"},{"speaker":"石田（し）委員","kind":"提案","question":"その両面を含めて、ぜひご検討をお願いしたいと思います。時間が少しあるので提案だけさせていただきたいと思います。新妻委員からも一般質問等でも出ていましたが、婚姻届の複写式のものをぜひ作成していただきたいと思います。今、若い人たちは、そういったものも非常に積極的に取り組んでいると思います。要望で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":266,"id":"exchange-112"},{"speaker":"南委員","kind":"質問","question":"２１１ページの個人番号カード経費について質問します。マイナンバー制度が本格実施されて１年が過ぎました。発行件数は一昨日の歳入の質疑で４万７４１件と言っておりましたけれども、改めてそれでいいのかどうか伺います。","respondent":"提坂戸籍住民課長","answer":"先日ご答弁申し上げたとおり、４万７４１件で間違いございません。","voiceIndex":268,"id":"exchange-113"},{"speaker":"南委員","kind":"質問","question":"としますと、カード発行は３８万区民の１０.６％、１割程度でしかありません。多くの区民がプライバシー保護への不安を持っていること、そして必要を感じていない。こういうふうに言えるのではないかと思います。改めて伺いますが、個人番号カードの目的は何でしょうか。","respondent":"提坂戸籍住民課長","answer":"マイナンバーカードの目的ですけれども、行政の手続において特定の個人を識別するための番号ということで利用させていただいて、行政手続を簡素化して区民の利便性向上を目指したものと考えます。","voiceIndex":270,"id":"exchange-114"},{"speaker":"南委員","kind":"質問","question":"個人番号を付番することにより、社会保障・税制度の効率性・透明性を高めるということですよね。効率性とは誰にとっての効率性なのでしょうか。私は、行政にとっての効率性であり、国民、区民ではないと思うのですけれども、この点についてはいかがですか。","respondent":"提坂戸籍住民課長","answer":"自分の情報がどういう形で利用されているのか、システム的にやりとりされた自分の個人情報をパソコンで確認できる。そういうことで、個人情報の保護が図られると考えています。それで国民のお一人お一人の利便性が向上すると考えます。","voiceIndex":272,"id":"exchange-115"},{"speaker":"南委員","kind":"確認","question":"１年に１回あるかないかの自分の様々な情報を取得する、そういう機会の点と、マイナポータルでとれるということですけれども、こういうマイナンバー制度が導入されることによって、使われ方についても不確信があって、そういうところでパソコンで確認できるというふうになってきているのではないかと私は思いますので、やはり区民や国民にとってメリットがあるとは言えないと思います。","respondent":"提坂戸籍住民課長","answer":"先ほど委員が示された数字には間違いございません。平成２７年度の決算で申し上げますと、２億１,４００万円余となっています。これは個人番号カードを普及するために必要な経費と考えています。","voiceIndex":274,"id":"exchange-116"},{"speaker":"南委員","kind":"質問","question":"それで、特別徴収は従業員の給与から住民税額を天引きして、翌月の１０日までに従業員の所在地の自治体に納付をするということになるわけですが、加えてマイナンバーの取扱いも加わって、事務負担も経費も増える、こういう状況ではないのでしょうか。今までもやってきたわけですから、思えないのですけれども、改めて、できないのかどうか伺います。","respondent":"提坂戸籍住民課長、黒田税務課長","answer":"３年間の品川区の経費ですけれど、先ほどの平成２７年度の決算、２億１,０００万円余を含めて、ほぼ３億円余となる見込みです。その点で、平成２８年度課税実績で４万１,５００余の事業所に短期間に税額決定通知が届きませんと、６月の給与から天引きできないという事情もありますので、マイナンバーが記載されていると、いわゆる特殊郵便になりますから。","voiceIndex":276,"id":"exchange-117"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひ、２３区共同で要望して、書かなくてもいいように。総務省のこの指導というのは、やはり間違っていると思います。そういう点で、ぜひしっかりと要請して、そういう実績をつくっていただきたい。こういうふうに総務省の要望をはね返していただきたいと思います。事務量が増えることはもちろんですし、また発送費用がぐんと増える。改めてこの点について区の見解を伺っておきたいと思います。","respondent":"黒田税務課長","answer":"マイナンバーの記載の問題につきましては、今年度、マイナンバーが活用される初年度ということで、国税庁のほうでも、確定申告ですとか会社の書類に、マイナンバーが、本来記載義務がありますが、なくても受け付けるというような対応をとっているという状況もありまして。","voiceIndex":279,"id":"exchange-118"},{"speaker":"南委員","kind":"質問・要望","question":"２月２３日現在、２３区の中で４区は記載しないことを明らかにしています。やはりこういう状況でありますので、住民・区民の皆さんの、やはり個人情報を保護するという毅然とした立場に、自治体としてもしっかり立っていただいて、記載は中止を求めていただきたいということを強くお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":281,"id":"exchange-119"},{"speaker":"若林委員","kind":"提案","question":"２０８ページの戸籍事務費では、先ほども石田しんご委員から改めて提案というかエールがありましたけれども、今般の新妻委員の第１回定例会の一般質問で、品川区のオリジナル婚姻届のご提案、質問をさせていただきまして、地域振興部長からは、これは再質問のご答弁ですけれども「記念になるもの等を具体的に検討していきたい」。こういう２つの課題といいますか、工夫・取組みが必要だと思います。","respondent":"提坂戸籍住民課長、黒崎防災安全担当課長、柏原企画調整課長","answer":"オリジナル婚姻届のお尋ねですけれど、新年度に入りまして検討は進めていきますが、まだ具体的なスケジュールは決まっておりません。私から、災害予防の実施責任者、訓練の部分についてご説明します。片や、今進めております施設の総合計画の部分、こういったところの基本的な考え方等々に照らしながら、施設の今の需要の状態であったり。","voiceIndex":283,"id":"exchange-120"},{"speaker":"若林委員","kind":"提案","question":"婚姻届については、一般質問で新妻委員のほうでご紹介したような、立川市を例に出しておりまして、今の課長のご答弁のものと、それから、いわゆる台紙を使って、それが手元に記念に残るというところの提案・主張をしていますので、ぜひそれについてもしっかり検討していただきたいということで、改めて、重ねての要望とします。","respondent":"黒崎防災安全担当課長","answer":"こちらは、法の規定に基づきまして、区の防災計画の中に盛り込まれている訓練ですので、区が主体となって関係機関と連携して行う訓練ということになっております。","voiceIndex":287,"id":"exchange-121"},{"speaker":"松澤委員","kind":"質問","question":"何点かお聞きしておきたいと思います。１点目が５７７ページの災害復旧特別会計。これは、今までの議論の中で復興仮設住宅みたいなものはつくらない、使わないというようなお考えだったと思うのですが、これでいいのかどうか、お聞きしたいと思います。","respondent":"古巻防災課長","answer":"災害復旧特別会計の内訳のお尋ねですけれども、こちら、当初予算に盛り込ませていただいているものは、資料のとおりですけれども、避難所の運営等の災害救助費と、それから家屋解体、廃棄物の処理等、災害復旧に係る部分ということで、幾つか項目がありますけれども。","voiceIndex":290,"id":"exchange-122"},{"speaker":"松澤委員","kind":"質問","question":"そうしますと、１５億円積んで、これは今年度使わないということで、来期にまた積み増しをしていくのかと思いますけれども、基金は資金の固定化につながるということで、あまり増やさないほうがいいのではないかと思っているのですけれども、これはどれぐらい積むつもりなのでしょうか。これは大変難しい問題ですけれども、お答えいただければと思います。","respondent":"秋山財政課長","answer":"その積み増しにつきましては、いろいろな事情等、決算の状況等を考えながら考えておりますけれども、今のところ１５億円で当面はいきたいと考えております。","voiceIndex":292,"id":"exchange-123"},{"speaker":"松澤委員","kind":"質問","question":"わかりました。次にいきたいと思います。総務費の２項地域振興費、１目地域活動費、１８１ページです、自治会活動賠償責任保険加入助成、２,１６４万円。午前中にも委員から話がありましたけれども、これは今まで、ふれあい保険というものが、どこの会社で行っていて、今度新しく自治会活動賠償責任保険に加入されたのはどこの会社なのか。これは同じ会社なのかということをお聞きしたいと思います。","respondent":"伊崎地域活動課長","answer":"ふれあい保険ですが、富士火災という保険会社でございまして、今度新たに契約いたしますのが、三井住友海上火災保険です。","voiceIndex":294,"id":"exchange-124"},{"speaker":"松澤委員","kind":"質問","question":"富士火災のほうでは、このような形の保険はなかったので、こちらに変わったということだろうと理解いたしますけれども、午前中の話の中でも、ふれあい保険に入っていたけれども、区に問い合わせたら、こういうのは入れないというので、町会で新たにその行事に保険をかけたなどというのもありますよね。その理由についてお聞きしたいと思います。","respondent":"伊崎地域活動課長","answer":"今年度の４月に、町会および自治会の活動活性化の推進に関する条例を区として施行いたしまして、やはり地域コミュニティの核である町会・自治会の活動の支援を強化していこうという方針を出しております。","voiceIndex":296,"id":"exchange-125"},{"speaker":"松澤委員","kind":"質問","question":"１つには、空き家対策との兼ね合いの中で、空き家がこういう形に使われればいいと思っているわけですけれども、４５０万円の予算がついたということは、ある程度、今年度、こういうことで助成を受けたいのだという町会があるということでいいのでしょうか。それとも、ないけれども見込みでつけたのですということなのですか。その辺のことをお聞きしたいと思います。","respondent":"伊崎地域活動課長","answer":"今現在こちらが把握していますけれども、５件ほどの賃貸借でのご要望があると聞いております。","voiceIndex":298,"id":"exchange-126"},{"speaker":"松澤委員","kind":"質問","question":"その５件の中で、空き家があって、当然空き家があるから借りるのですけれども、そうではなくて、空き家があって困っているという中で、それを借りるのだというのはあったでしょうか。そこだけお聞きしたいと思います。","respondent":"伊崎地域活動課長","answer":"こちらで把握している限りでは、空き家をというお話はございません。","voiceIndex":300,"id":"exchange-127"},{"speaker":"松澤委員","kind":"質問","question":"わかりました。これも地域美化事業ということで、各町会、各地域ですか、年に２回ぐらい決めて地域清掃をしているのですけれども、これは大変いい施策だと思っているのです。地域の町会の方、あるいは子ども会も含んで子どもたちも清掃しているという町会もあるのですけれど、これに対する区のかかわり、地域センターがかかわっていると思うのですけれど、その辺のことをお聞きしたいと思います。","respondent":"伊崎地域活動課長","answer":"地域美化活動につきましては、それぞれの１３地区ごとにさまざまご活動いただいておりますけれども、直接的には地域センターがかかわって進めているところです。","voiceIndex":302,"id":"exchange-128"},{"speaker":"松澤委員","kind":"質問","question":"この施策は、私は、予算的には大した予算ではないのです。おそらく１町会２万円ぐらいですか。そこにいっぱいあったというような報告をしながらやるものですから、大変いい施策だと思っているのですけれど、やはりこれは年に２回ではなくて、もう少し拡大できればいいと思っていますので、その辺の予算措置を講じていただければとお願いしておきたいと思いますが、いかがでしょうか。","respondent":"伊崎地域活動課長","answer":"こちらは、各１３連合町会の計画に対して補助しておりますので、またお声を聞きながら検討していきたいと考えます。","voiceIndex":304,"id":"exchange-129"},{"speaker":"松澤委員","kind":"質問・要望","question":"わかりました。では次にいきます。１９９ページ、街頭消火器の増設。今年度は５００万８,０００円、昨年は３６９万４,０００円。これは毎年毎年、消火器を増設しています。これは、どんどん増設していただきたい。初期消火で火災を防ぐには一番いいと思っているのですけれど、毎年増設していますけれど、どのような計画性を持って増設しているのか、その計画についてお知らせいただきたいと思います。","respondent":"古巻防災課長","answer":"街頭消火器の増設ですけれども、こちらは平成２４年度より年次計画をもって増設しているものでございまして、火災危険度ランクの高い地域、概ね火災危険度ランク４・５の地域を中心に街頭消火器の増設をしているということで、平成３０年度までの年次計画となっています。","voiceIndex":306,"id":"exchange-130"},{"speaker":"松澤委員","kind":"質問・要望","question":"これはどんどん増やしていただきたいと同時に、そこに格納箱等補修費用ということで、今年が２７２万円、昨年が１７２万円。これは随分大きな金額だと思うのですけれど、これだけ毎年毎年、消火器の格納庫が壊れているのでしょうか。内容的にはどういう形で壊れているのかについてもお聞きしたいと思います。","respondent":"古巻防災課長","answer":"それから破損等が合わせて３９本ということで、毎年大体４０本ぐらいの破損と、それから使用が２０本から３０本ぐらいということで推移しています。","voiceIndex":308,"id":"exchange-131"},{"speaker":"松澤委員","kind":"質問","question":"やはり消火器というのは大変重要なものですから、よろしくお願いします。もう一つ、実は、しながわ中央公園が拡幅整備されました。これが１月２９日です。大変よくできているのですけれども、この広場ができたおかげで、そこに逃げ込む避難の人口というものは増えたのでしょうか。あるいは避難人口というのはカウントしていないですというのでしょうか。その辺をお聞きしたいと思います。","respondent":"古巻防災課長","answer":"ただ、一時避難ができる場所として、中央公園の多目的広場を含めた拡張部分につきましては、そういう形で、増えたという意味で言うと、一時避難できる人数は増えているというお答えになろうかと思います。","voiceIndex":310,"id":"exchange-132"},{"speaker":"松澤委員","kind":"質問","question":"あそこはヘリコプターが降りるわけですから、あそこへ人が避難してしまってはヘリコプターが降りられないということで、そういう意味では、あそこの広場は、いざ震災のとき、人が来てもここには入れませんという形をとらなくてはいけないと思っているのですけれど、あの広場、避難民が来て占拠されてしまっては何の役にも立たないということ。その辺の計画性というものはしっかり担保されているのでしょうか。","respondent":"古巻防災課長","answer":"これは、上段部分、下段部分、合わせて４,０００人という数で、場所としては、想定エリアに含めておりますけれども、当然、被災の時系列の中で、避難者がいるケース、それからいないケースを含めていろいろありますので、混乱のないように。","voiceIndex":312,"id":"exchange-133"},{"speaker":"松澤委員","kind":"質問・要望","question":"その点だけはしっかりと計画をつくっておいていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":314,"id":"exchange-134","title":"町会・自治会支援"},{"speaker":"藤原委員","kind":"質問・要望","question":"１９５ページ、総合体育館の便所なのですけれども、冬の時期に、あの体育館の便所の便座に座ると、ひやっとするもので、私は要望していましたけれども、課長、どういうふうになりましたか、教えてください。それと、機運醸成の事業なので、事前告知が大切だと思うのですけれども、事前の区の事業の情報発信の考え方について、広報広聴課からお伺いしたいと思います。いい視察でした。「わ！答弁ください。","respondent":"池田スポーツ推進課長、小川オリンピック・パラリンピック準備課長、中元広報広聴課長、鈴木文化観光課長、伊崎地域活動課長、河内協働・国際担当課長、濱田生活安全担当課長、島袋人権啓発課長、黒田税務課長","answer":"区民の方から、暖房機能のついた便座でというご要望がございましたので、そちらのほうの工事も行う予定になっておるところです。今年度の実績を踏まえ、平成３０年度につきましては、２年前のフェスタ。事前にわかっている大きなイベントにつきましては、パブリシティということで、プレスリリースも事前に情報を主管課からいただきまして。区としましては、この歴史館本来の機能に加えて、ご指摘のありましたような、区民の方や来訪者に対しての説明等、観光の視点も含めまして。","voiceIndex":316,"id":"exchange-135"},{"speaker":"藤原委員","kind":"質問・要望","question":"生活安全担当課長、すごく数字的に効果が表われているわけですので、私は心から、もうずっと品川区にいていただきたい。しかし、いろいろなご事情があると思います。学芸員は重要だと。ただ、オリンピック・パラリンピック準備課に関しては、一般質問の答弁では２人増えるということで、なぜ、こちらはやってくださったのに、もう一つはやってくださらないのでしょうか。今後の見解を教えてください。","respondent":"濱田生活安全担当課長、小川オリンピック・パラリンピック準備課長、米田人事課長","answer":"刑法犯認知件数は確かに減少いたしました。ただ、これはもちろん、私１人だけの力ではございません。今、部長を筆頭にいい雰囲気だというご指摘ですけれども、そういった風土を大切にしていきながら、人が変わったとしても。歴史館にぜひこれから取り組んでみたいというようなことでの職員としての異動等の希望というのもあると聞いておりますので、その辺を絡めた上で。","voiceIndex":326,"id":"exchange-136"},{"speaker":"藤原委員","kind":"質問・要望","question":"よくわかります。だけれども、やはり現地に行った、現場を見た、経験・体験をしたということが、２０２０年のオリンピックに活きてくるのです。だから、もう一度答弁をいただきたいのと、あともう一つ不安があるのです。２０２０年に向かってやっていくのだと。気持ちの問題でいいですから、よろしくお願いします。これはストレートな質問ですけれど、まさかだと思いますけれど、婚活の復活ではないですよね。","respondent":"小川オリンピック・パラリンピック準備課長、安藤文化スポーツ振興部長、伊崎地域活動課長","answer":"委員ご指摘のとおり、リオの視察に行かせていただいたメンバーの責任として、これにつきましては、２０２０大会に確実に活かせるような形を考えてあります。ただ、組織が変わっても、今回の区長の施政方針のごとく、筆頭にオリンピック・パラリンピック、そして観光というのを、我々の部が持っています。","voiceIndex":330,"id":"exchange-137"},{"speaker":"大倉委員","kind":"質問・要望","question":"初めに防災対策で、避難者カードについて伺いたいと思います。その原因と対応について教えていただきたいと思います。以前、質問の中であったのか覚えていませんが、たしか禁止しているというところですが、どういった経緯で禁止になっているのか確認させていただきたいのと、どのぐらい品川区でそういった出張があるのか、交通機関も何を利用していることが多いのか、あわせてお知らせください。","respondent":"古巻防災課長、仁平情報推進課長、米田人事課長","answer":"私からは避難者カードのご質問に対してお答えします。私のほうから大井町駅西口のＷｉ－Ｆｉについてお答えします。１０日間ほど故障で停止してしまいまして、誠に申し訳ございませんでした。庁内でも年に２回ほど献血運動等が行われ、それに付随してドナー登録の推奨等も行われていると記憶していますが。","voiceIndex":336,"id":"exchange-138"},{"speaker":"大倉委員","kind":"質問・要望","question":"今後また、アンテナの故障という部分では起こり得ることなのかというのを知りたかったので、教えてください。まだ、導入してそんなに経っていないので、そういうことが起こり得るのか確認させてください。民間企業でこうした利用はもう既に進んでいると思いますが、職員に支給という部分では、ポイントを使える状況があると思うのですが、その辺の考え方について教えていただきたいと思います。","respondent":"古巻防災課長、仁平情報推進課長、米田人事課長、中元広報広聴課長","answer":"Ｗｉ－Ｆｉのアンテナの件ですけれども、平成２７年７月からサービスを開始していると思いますので、確かに期間的に。旅費の関係ですけれども、原則としては合理的かつ経済的ということで、現在、特に経済的というようなことについては重視しながら。ただ、Google側の課題で、検索したときにGoogle側として、そこが残ってしまっているという状況です。","voiceIndex":340,"id":"exchange-139"},{"speaker":"大倉委員","kind":"質問","question":"そうした部分では、しっかりと各学校、データ化もその後、ある一定期間を置けばデータ化して把握していくのだろうと思いますが、そういった意味では統一されたものにしたほうが管理しやすいというかデータ化しやすい、迅速に対応できるという部分では、工夫が必要だと思いますが、いかがでしょうか。消さなくてはいけなかったのかという部分があるので、その辺の考え方を教えてください。","respondent":"古巻防災課長、中元広報広聴課長、米田人事課長","answer":"今後、避難者の内容を把握することは重要な課題であるとも捉えておりますので、そのあたりを含めまして、避難者の把握を進める際に。ホームページの件ですが、Google側のシステム仕様の制約もありますので、今後の課題とさせていただきたいと存じます。先ほども申し上げましたが、合理性だったり経済性だったりというようなことで、合理性もあるというご指摘でしたので、今やっている現システムと比べて。","voiceIndex":345,"id":"exchange-140"},{"speaker":"大倉委員","kind":"質問・要望","question":"避難者カードなのですが、またその際に統一化して、管理をしっかりしていって工夫してくださる、検討していただけるということで、もう一個お願いなのですが、妊婦、乳幼児、障害、ペットなど、外国表記の記載というのもないので、外国の方が避難してきたり、外国の方は読めないという部分で対応がされなければいけないと考えていますし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":349,"id":"exchange-141"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１６７ページの人権啓発、ＬＧＢＴ関連で質問をいたします。結果がパンフレットでできています。少数者の生きづらさに気づき、公平に接することを意識したいものです」と書かれているのですが、まず、この人権を考えるパンフレットが何部つくられて、どのように活用されたのか教えていただきたいのと、結果を受けて、今後の具体化はどのようになるのか、予算化はどうされるのかをお伺いします。","respondent":"島袋人権啓発課長","answer":"こちらは１万部、作成させていただきまして、現在、私たちの職員の様々な研修で配らせていただくのと同時に、先日は、特別区と都の人権関係の課長の連絡会がございまして、こちらの紹介をすることができましたので、２３区、東京都のほうにも。","voiceIndex":351,"id":"exchange-142"},{"speaker":"飯沼委員","kind":"質問・要望","question":"「性的マイノリティの人権。「性のあり方はさまざまです。このことを知ってほしい」ということが書かれているのと、「苦しんでいる人がいます」ということで、人に打ち明けられない事例、様々な困難に直面している事例などが書かれています。それで、同じ内容を、ぜひホームページにも載せていただきたい。そして、性的マイノリティに特化した講演会をぜひ開いていただきたいのですが、いかがでしょうか。","respondent":"島袋人権啓発課長","answer":"次年度以降は、品川区版として同じようにつくらせていただくのが大丈夫かどうか確認しておりまして、つくっていきたい方向で、もしくは東京都からも、各区からの要望があると聞いておりますので、かなりの部数をいただけるのではないかと思っているところで、交渉する予定です。","voiceIndex":355,"id":"exchange-143"},{"speaker":"飯沼委員","kind":"質問・要望","question":"子どもでも、あと高齢者の方でも手にとって見たくなるような中身に、ぜひ工夫していただいて、区民の目に触れるところに、本当にたくさん置いてほしいと思います。それで、これまでの要望事項の進捗状況も教えていただきたいのですが、学校のほうで先日、図書館にぜひＬＧＢＴ等の図書を置いてほしい。研修の受講者が増えているのかどうか、今後の課題について教えてください。","respondent":"村尾教育総合支援センター長、島袋人権啓発課長","answer":"ＬＧＢＴに関するご質問です。ＬＧＢＴに関する図書ですけれども、数校の学校には、もう図書室のほうに配置しているということで、今後このような形で、教員を含め、様々な形での啓発については進めていくものだと考えております。１２月には「さまざまな人権を考える」という職員研修をさせていただきました。今後もいろいろな意味でステップアップをした研修をしてまいりたいと考えています。","voiceIndex":357,"id":"exchange-144"},{"speaker":"たけうち委員","kind":"提案","question":"その際に、低所得者はもちろん、もとよりなのですが、こうした助成が拡充されることで、今度は、助成対象にならない、比較的所得が高い方になるのですが、そういう方たちでもお子さんが多い方などは、所得が低い方で助成の対象になる方に比べても負担感は大きいのではないかということで、そういう方たちへのきめ細かい支援も検討はどうでしょうかということで提案させていただきました。","respondent":"廣田子ども家庭支援課長","answer":"今後、奨学金をどうしていくかという見直しの中で、こういう子どもが多い世帯をどうしていくかについては、また検討のテーブルの中で、みんなニュートラルに乗せた上で、区としての方向性はこれから考えようと思ってあります。","voiceIndex":361,"id":"exchange-145"},{"speaker":"たけうち委員","kind":"提案","question":"それで、伺ったところでは、今、こうした授乳やトイレなど、そういうプライバシー確保のためのパーティションというのですか、段ボール等のパーティションは１００セット、備蓄は既にされていると聞いておりますが、それについての確認と、あわせて、備蓄はされているのですけれど、どういったものになっていて、それで、それを実際に組み立てて。","respondent":"古巻防災課長","answer":"これは、各避難所に、それほど多くは配備できないかと思いますけれども、パーティションとして使えるものとして考えています。特に訓練については、現在確かに行っていないです。","voiceIndex":363,"id":"exchange-146"},{"speaker":"たけうち委員","kind":"提案","question":"今、東京都のほうでもいろいろな動きがありまして、私ども都議会のほうで提案させていただいて、『東京防災』というのが１回、黄色いやつが出て、かなり好評だったのですが、これの女性版ということで、女性の視点からの、いわゆる『東京防災』というのが、今度、新年度予算で約３億円計上されて発行されていくと伺っておりますが、まだできていないので、どういう内容になるかわからないのですが。","respondent":"古巻防災課長","answer":"それから『東京防災』の女性版ということですが、これはまだ確かにできていないものなので、どういったものができ上がってくるかということは注視していきたいと思いますし、女性の視点等を含めまして、避難所運営における様々な配慮については。","voiceIndex":365,"id":"exchange-147"},{"speaker":"たけうち委員","kind":"確認","question":"その１００セットは、今のお話だと福祉避難所用ですか。それがまだできていないということであれば、ぜひそれも早目にお願いしたいと思いますが。それで、それができない理由としては、おそらく非常に、学校の倉庫に入れるとするとかさばってしまうのではないかと思うのですが、それが原因なのか、どうなのかということも確認したいと思います。","respondent":"古巻防災課長","answer":"備蓄倉庫、今、懸命に場所の確保には努めておりますけれども、やはり優先して備蓄すべきものということでは、食料品でありますとか飲料水といった、最低限７２時間の命の確保をするための必要なものを中心に、今、備蓄を進めているところですので。","voiceIndex":367,"id":"exchange-148"},{"speaker":"たけうち委員","kind":"質問・要望","question":"ですので、例えば、さっきおっしゃったように３日間とかはなくても大丈夫なのです。やはり長期になってきたときにプライバシーが確保されなければいけないという中で、そういうところと協定しておいて対応してもらえるような、そういう仕組みなども検討できないのかと思うので、お答えいただきたいと思います。","respondent":"古巻防災課長","answer":"実際に協定等に関しましては、畳の提供について畳の事業者と協定をしていたりなどということもありますので、可能性については探っていくようには考えていきたいとは思いますけれども、実際に必要なものの優先順位をつけながら。","voiceIndex":369,"id":"exchange-149"},{"speaker":"たけうち委員","kind":"質問","question":"ぜひ積極的に対応してもらいたいと思います。次の質問ですが、福祉避難所関係で、これは、周知は今されているのかどうか。いわゆる福祉避難所自体が指定されているけれども、中の対応がまだできていないので、なかなか周知ができていないのではないかと思うのですが、その辺は今どうなっていますでしょうか。","respondent":"古巻防災課長","answer":"周知という意味でありますと、１３カ所、福祉避難所、それから１８カ所だったかと思いますけれども二次避難所を指定しておりますけれども、地域防災計画の中で一覧表をつくりまして、それに関しては公表しているという状況です。","voiceIndex":371,"id":"exchange-150"},{"speaker":"たけうち委員","kind":"質問・要望","question":"なぜこういう質問をするかといいますと、ある障害者のお子さんがいらっしゃる親御さんが、やはり福祉避難所が気になって、多分、福祉部局に要求したと思うのです。そうしたら、品川区はありませんと言われたというのです。そういう中で、その辺がなかなかまだこれからなのかと思うので、これを早急に進めていただかないといけないのかと思うので、その辺について前向きなご答弁をいただきたいのですが。","respondent":"古巻防災課長","answer":"ご指摘いただきましたとおり、要配慮者への対応ということでは、今年度、個別計画の作成支援も行っておりますし、二次避難所の開設訓練といったところも手をつけ始めたところですので、今後とも福祉部門との連携というのはきちんと図って対応していきたいと思います。","voiceIndex":373,"id":"exchange-151"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ですから、金額的には安かったのですけれど、今度、区で新しくやっていただく保険が、こういうものに対して対象になっていくのかどうか、そこら辺をちょっと確認させてください。これは地域活動課と商業・ものづくり課が連携してやっている事業ということで、区民委員会の資料ももらっていますが、これに対して基本的に目的と事業の展開を確認させていただきたいと思います。","respondent":"伊崎地域活動課長、河内協働・国際担当課長","answer":"自治会活動賠償責任保険ですけれども、保険の支払いの対象となる事象は事故でございまして、こちらに明記されておりますが、食中毒等の細菌性食中毒、ウイルス性食中毒は含まないということで明記されております。経過ですが、平成２０年より開始いたしました当事業ですが、以降、毎年開催されております。本年２月の開催でちょうど９回目ということになります。","voiceIndex":376,"id":"exchange-152"},{"speaker":"鈴木（真）委員","kind":"質問","question":"それぞれわかりました。地区委員会の活動に対しての保険というのは当然利かないと思うのですけれど、その対象がどうなっているのか、そこら辺を教えてください。私もいろいろな団体と話したせいかもしれないのですけれど、うまくいき始めたというのは、区としていろいろな指導をしていらっしゃるのか、それとも協働ということで、各団体同士でうまく話し合いがされているのか、その点で教えてください。","respondent":"伊崎地域活動課長、河内協働・国際担当課長","answer":"こちらの保険は、自治会活動の賠償責任保険ですので、地区委員会単独の事業には対象とはなりません。ただ、町会・自治会が共催などで一緒にやっている事業でしたら、自治会活動ということで対象となると考えております。とはいいながらも、運営いたします各団体のほうの成熟度も上がってきておりますとともに、当初は、団体の存在や取組みを知ってもらうというところが本当に一生懸命やっている主軸だったのですが、大分。","voiceIndex":379,"id":"exchange-153"},{"speaker":"鈴木（真）委員","kind":"確認","question":"品川第二ですとみかん狩りなど、いろいろなところに行っているのですけれど、その辺の、万が一、本当に事故があってはいけないのだけど、何かあったときというのはどういう対象になっているのか、その辺を確認させてください。それから補助制度が、たしか年数が３年ぐらいだと思ったのですが、今後の展開について、また教えてください。","respondent":"伊崎地域活動課長、河内協働・国際担当課長","answer":"地区委員会の事業ですが、先ほど申し上げましたように、町会・自治会あるいは連合会との共催という形で行われている場合は対象となりますので、一つ一つ確認は今できないのですけれども。そうしたところから、現在また３年の継続年数で進めているところですが、団体の状況や社会状況を踏まえましてブラッシュアップをかけてまいりたいと考えております。","voiceIndex":382,"id":"exchange-154"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ボランティアを受援の中でどういうふうに捉えていくか。品川区だと、もし一般のボランティアの方が来た場合、社会福祉協議会が入ってくるのかと思うのですけれど、その辺が、本によると、ホームページにもその辺も謳っておくような体制、それから受援計画も先に出しておくべきだというのがあるのですが、そこら辺のお考えを教えてください。","respondent":"池田スポーツ推進課長、古巻防災課長","answer":"しながわ体操についてですけれども、現在の進め方としましては、日体大と昨年６月にスポーツ振興に関する協定を締結いたしまして、その後に日体大がつくりました体操について品川区で活用してはどうかというような話がありました。これは大きな課題ということで捉えておりまして、平成２９年度の地域防災計画の改訂・検討の中で、十分検討して形をつくっていきたいと考えております。","voiceIndex":385,"id":"exchange-155"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"しながわ体操は、今お話に出ましたけれど、ラジオ体操との絡みがどうなってくるのかというのがちょっと気になっています。朝のラジオ体操、夏休みなどにやっていますけれど、そこにもどういうふうに関連させるのかというのが、これから検討していただきたいと思います。これは、感染症等を考えると、もう少し増やしたほうがいいのではないかと思いますので、それは要望にしますので、お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":388,"id":"exchange-156"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1058#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":133164,"voices":389}},{"id":"h29-20170310-3","meetingId":"h29-c-budget","date":"2017年3月10日","dateIso":"2017-03-10","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時２３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を142件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問","question":"私からは、２２７ページ、高齢者の趣味・健康づくり事業の中の高齢者輪投げ大会、２４１ページ、心身障害者福祉会館運営費の中の高次脳機能障害相談、修繕工事費等のことをお伺いしたいと思います。２４１ページ、心身障害者福祉会館運営費の中の高次脳機能障害についてご質問します。それから、高次脳機能障害相談ということで、平成２９年度３７０万５,０００円という予算がついております。","respondent":"中山障害者福祉課長","answer":"心身障害者福祉会館の工事についてです。来年度は足場工事ということで、外壁ですとか屋上の囲いのフェンス、あと食堂の換気口といった工事を予定しております。このほか、非構造部材については今年度調査をしまして、来年度工事を実施するといった内容になってあります。","voiceIndex":4,"id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"人数は１,５００人から１,６００人ということで、わかりました。そういったことを含めて、今度これからパブリックコメント等ありますけれども、地域の方からとめないでくれという要望がありますので、ぜひとも進めていただきたいと考えています。この件について、そういったクレームや情報を区としては把握しているのかどうか、お知らせいただきたいと思います。","respondent":"中山障害者福祉課長","answer":"実際に心身障害者福祉会館にいらっしゃる視覚障害者の方で、ちょっと困ったよというような声は、こちらにも数例届いているところです。","voiceIndex":6,"id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。それとあと、修繕工事に関連しまして、心身障害者福祉会館は大分老朽化しているということなのですけれども、建替えなどは今現在考えていないのか、これから先そういうこともあり得るのかをお知らせいただきたいと思います。","respondent":"中山障害者福祉課長","answer":"ですので、使い勝手がいいように中の部屋の工夫とかいったものも考えながら、手を入れていきながら使っていきたいと考えています。","voiceIndex":8,"id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問","question":"２２７ページの高齢者の趣味・健康づくり事業の高齢者輪投げ大会のことをお伺いしたいと思います。それで、毎年これはやっていると思うのですけれども、２０１５年度品川区主催の高齢者輪投げ大会が４４チーム、約３００人が参加をしたということで、２０１６年度の６回目の参加チーム数と参加人数をお知らせいただければと思います。","respondent":"松山高齢者地域支援課長","answer":"高齢者輪投げ大会の平成２８年度の参加チーム数と参加者数のお尋ねです。参加チームは４４チーム、参加人数は２８２人です。","voiceIndex":10,"id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そうすると、年々増えているような感じがいたしますけれども、これをやるのは大体これぐらいの人数がマックスなのかということだと思います。平成２９年度予算ですと４１万円ということで、この４１万円は品川区が主催する輪投げ大会の予算ということでよろしいのでしょうか、教えてください。","respondent":"松山高齢者地域支援課長","answer":"予算についてですけれども、こちらは区が主催する高齢者輪投げ大会のみの予算ということで、品川区高齢者クラブ連合会とは別になっております。","voiceIndex":12,"id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"わかりました。それで、地域、高齢者クラブの団体の皆さんも、本当に気軽に皆さんやっているという中で、この参加人数がマックスという中で言うと、今度啓発活動として、高齢者クラブに対してもっとこの啓発活動を区として進めていくのかどうか、教えていただきたいと思います。","respondent":"松山高齢者地域支援課長","answer":"この大会の運営につきましては、品川区高齢者クラブ連合会が全て事前準備から当日の運営まで、委託をしておりますので、また高齢者クラブと相談しながら啓発活動を行ってまいりたいと考えています。","voiceIndex":14,"id":"exchange-006"},{"speaker":"つる委員","kind":"質問","question":"よろしくお願いします。２４４ページ児童福祉費と、２４５ページ産後家事育児支援、産後ドゥーラ等について伺っていきたいと思います。児童福祉費についてですが、待機児童解消に関連して、保育士の確保などについてお尋ねしていきたいと考えています。そうした中で、まずその保育士の確保に際しての状況と、それから、今回そうした中で何人の保育士が確保できたのか、教えてください。","respondent":"佐藤保育課長","answer":"区内の認可園に係る保育士の確保の状況ですが、人数の具体的なところは把握していないところですが、近隣区で発生しております保育士の確保ができなくて開設が困難になっているという状況は、今のところ品川区ではありません。","voiceIndex":17,"id":"exchange-007"},{"speaker":"つる委員","kind":"質問・要望","question":"人数については、細かいところはまた別途いろいろ確認はしていきたいと思うのですが、ただ、全体としては無事に確保できて開園できているということで、それが一番何よりかと思います。３カ年度ですから単純計算で１万２,０００人になります。それから、年間にさまざまな理由で離職される方は都内で全体の８.４％で３,５００人ぐらいいらっしゃいます。","respondent":"大澤待機児童対策担当課長、佐藤保育課長","answer":"乳幼児人口のピークは平成３３年以降と見込んでおりますが、保育需要に関しましてはずっと後の、平成５２年までは増え続けると考えております。保育園の採算ですが、事業者からは２５年たつと採算がとれると聞いております。採算の面ですが、事業者から聞き取り等しているところによりますと大体５年から１０年ぐらいで採算をとって、事業者としては今後２５年間は品川区内で保育園の施設の運営が可能だと計算していると聞いております。","voiceIndex":19,"id":"exchange-008"},{"speaker":"つる委員","kind":"質問","question":"そのように踏み切った理由というのが、アンケートをとったら、３割ぐらいの施設で保育士不足で開園できなかったというところがあったという課題がある中で、そうした取組みに踏み切ったということですが、そうしたところ、数十人の保育士の確保が見込めていると言われておりまして、その結果、三、四倍の保育の枠が拡大できるというところでは、こうした保育士の子どもの最優先ないし優先入所について。","respondent":"佐藤保育課長","answer":"通知の趣旨については、委員ご指摘のとおり、保育士自身の子どもが保育所に通えないことから、職場復帰できないというところだと考えています。品川区内の場合、先ほどご答弁申し上げたとおり、私立保育園については保育士を確保できずに開設できない事例は今のところありません。","voiceIndex":22,"id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"これは、品川区もこの対応方針の中にも示されている近隣の連携保育園については、昨年しっかりと整備されていたかと思うのですが、この土曜日の共同保育については、近いところで私も調べられる範囲では、船橋市が同じ同一事業者の中で、そうした連携を募集や呼びかけも含めてやっているというのは確認しているのですが、この土曜日の共同保育について、品川区の見解を教えてください。","respondent":"佐藤保育課長","answer":"船橋市の実施の状況も確認をしておりますが、品川区の状況ですと、公立園は土曜日は大体２０％ぐらいの児童が通われているのですが、例えば連携してやった場合、園児になじみのない保育士による保育や、アレルギーや特別な支援が必要な子どもへのきめ細かい対応と。","voiceIndex":24,"id":"exchange-010"},{"speaker":"つる委員","kind":"質問・要望","question":"保育従事職員宿舎借上支援事業についても確認をしたいと思うのですが、これは小規模の事業者、例えば１２名定員であれば４名ぐらいの保育士という体制かとは思うのですが、そうした中で欠勤対策として、園を固定しないフリー保育士という職員を置いて、もしその日出勤の保育士が急な病気だとか、自分自身のお子さんのインフルエンザだとか。","respondent":"佐藤保育課長","answer":"フリー保育士の関係ですが、まずフリー保育士というのは複数の園で従事する保育士のことなのかなと考えております。現在の宿舎借上げの制度の枠組みでは、一応常勤という枠組みがありますので、現在の国等の補助金の制度の中では厳しいというところを認識しております。","voiceIndex":26,"id":"exchange-011"},{"speaker":"つる委員","kind":"質問・要望","question":"さまざまな工夫の仕方だと思うのですが、聞いている中では杉並区では、ほかの区と重複しなければ認めますという見解も伺っているところでありますので、そうしたところをぜひ参考にしていただいて、まずは今、フリー保育士という形で言いましたが、各事業者で言い方がばらばらかと思うのですが、そうした対応をされている事業者があるかどうかということとか。","respondent":"高山子ども育成課長","answer":"最後に制度の改正につきましては、今年度１０時間を上限といたしましたが、来年度につきましては２０時間ということで、上限枠の拡大を考えております。と申しますのは、利用者の利用時間数が多かったというところが、今回の改定の理由です。","voiceIndex":28,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"福祉避難所は１３カ所ですが、この７施設に限定されているのはどうしてかということと、これらはどこの二次避難所、福祉避難所が対象なのか、伺いたいと思います。大きな震災が地方であるたびに、障害がある方も自分たちはどうなるのかと不安の声が私のところにも寄せられますけれども、障害がある方の避難生活について、どのような声や課題があるのか、伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"それで、備蓄の量の基準ですが、こちらの施設の利用者、そして職員の３日分に加えまして、こちらに来ることを想定されている収容想定人数の３日分ということで考えているところです。障害のある方は、やはり避難所生活に対する不安というのは声をいただいているところです。","voiceIndex":31,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"開設に当たって、この施設の利用者や、また地域の方々とも丁寧に話し合って、それぞれの福祉避難所の開設訓練や、開設や運営の計画をしっかりとつくっていくことを求めたいと思いますけれども、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"その中でもいろいろと課題として出てきたことがありますので、一つ一つ積み重ねながら、また地域の町会にもここの場所がどういう避難所かということもご了解いただきながら、福祉避難所あるいは二次避難所としての機能が果たせるよう、進めてまいりたいと考えております。","voiceIndex":33,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"訓練の実施が行われたのは何施設あるのか、今後の見通しも含めて伺いたいと思います。同時に、障害がある方の避難生活について、あらかじめ自宅だったり学校避難所だったり福祉避難所だったり、さまざまな場所で障害がある方の避難生活を支える個別の計画をしっかり持っておくことが必要だと思いますけれども、現状は何人分ぐらい作成が進んでいるのか、現状を伺いたいと思います。","respondent":"中山障害者福祉課長、古巻防災課長","answer":"この二次避難所１３カ所のうち、訓練の実績ということですが、まず今回試しに第１回ということで心身障害者福祉会館で実施したところです。学校避難所におきます障害者を含めた要配慮者への対応ですけれども、現在、避難所のマニュアルを整備していますけれども、そういった要配慮者への記載につきましては、全部で３５カ所で記載があるということで把握をしております。","voiceIndex":35,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"伺いたいのは、例えば、日常の障害者サービスをつくる場合は、本人だったり家族だったり施設の利用者ともよく話し合ってサービスを決めるということですけれども、まずこれでよいのかという点を確認させていただきたいのと、だからこそ、災害時の対応もあらかじめ動きや支援をしっかり決めることがとても大事ではないかと思うのですけれども、この点も伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"ですので、個別の支援計画、災害時の個別の支援計画というのもそういった視点で作成することが望ましいというのは確かではありますが、現在のところまだそこまで手が回っていない状況であります。","voiceIndex":38,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区も備蓄や事前協定の中で、こうしたトレーラーハウスの活用を検討していただきたいと思いますが、いかがでしょうか。地域のつながりや地域のヘルパー、またヘルパーを引退された方でもやはりまだお元気な方もいらっしゃいますから、そうした方も含めて、一人一人の支援計画作成を品川区は主体的にしっかりと進めていただきたいと思うのですけれども、この点を改めて伺いたいと思います。","respondent":"古巻防災課長、中山障害者福祉課長","answer":"区ではひとまず現行の対策をベースにしまして検討を進めるという中で、いただいた情報については参考とさせていただきたいと考えます。そういった中では、障害者団体の方とも連携しながら、まずどういった心配があるか、どのような体制がとれるか、あるいは改めて自分の家の再点検といったようなことも一緒に考えてもらいながら、体制を組んでいきたいと考えております。","voiceIndex":40,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"大学との連携は、現在も協定を結んでいることは承知しているのですけれども、大学の構内やロビーといったところにも福祉避難所としての機能を持たせて、また学生の協力も得て進めていくということ、こうした視点で検討ができないかと思うのですけれども、改めてこの点は伺いたいと思います。こうした支援ガイドを品川区でも作成していただきたいと思いますけれども、いかがでしょうか。","respondent":"古巻防災課長、中山障害者福祉課長","answer":"どういった形でというのは、先ほども申し上げましたけれども、今後先方の考え方ということもあるかと思いますので、その辺整理しながら、対策については今後検討を進めてまいりたいと思います。そうしたものが必要だろうということは認識しています。今、品川区でも合理的配慮を進めるために、まちの皆さんに向けて、そうした差別解消に向けたガイドブックをつくっております。","voiceIndex":43,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ進めていただきたいと思うのです。少しだけ紹介したいのですけれども、この調布市の支援ガイドは、例えば視覚障害がある方については肩やひじにつかまってもらい、少し前を歩く、手やひじをつかまない、引っ張らない、背中を押さないということが書いてあります。それぞれの特性に合わせてこうした支援ガイドを品川区でも進めていただきたいと思いますので、要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-019"},{"speaker":"松永委員","kind":"質問","question":"２２３ページの紙おむつ支給について、６,７００万円と前年度と同額であり、２３１ページの入院中の紙おむつ代助成事業では、１,１５７万３,０００円から６７６万円と約５００万円減となっておりますが、このそれぞれの平成２８年度の成果について伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"必要な方にきちんと配布できるようにということで、平成２４年度から現況調査というのを行っておりまして、その調査は毎年行い、配布をしています。それから、入院中の紙おむつのほうですけれども、昨年度から開始をいたしました。","voiceIndex":48,"id":"exchange-020"},{"speaker":"松永委員","kind":"意見","question":"この２２３ページのほうの紙おむつ支給では現物支給という形で、２３１ページの入院中の紙おむつ代ということで、現金支給という形がとられていると思いますが、それぞれの紙おむつがどのようなルートで利用者の方に届けられているのか、手渡されているのか、ちょっと流れについてそれぞれお願いいたします。","respondent":"永尾高齢者福祉課長","answer":"それで、入院中の紙おむつですけれども、３０日以上の入院に対して支給いたしますので、その領収書と申請書を社会福祉協議会のほうにお持ちいただいて、それで助成金を払うということなのですけれども。","voiceIndex":50,"id":"exchange-021"},{"speaker":"松永委員","kind":"確認","question":"この入院中の紙おむつに関しては３０日以上ですね。もし紙おむつが余った場合に、その紙おむつはどのような取扱いになっているのかちょっと伺いたいと思うのですが、実は私も聞いた話なので本当かどうかわからないので、ここでお聞きしたいと思うのですけれども、戻された紙おむつが、また事業者に新品のまま戻ってくると。そういった余るということはあるのかどうかも伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"入院中の紙おむつ代の助成につきましては、退院してからの申請となっております。配給のほうのおむつが余った場合ということですけれども、現状の仕組みの中では、業者のほうに戻されるということはなかなか考えらえない状況になっております。","voiceIndex":52,"id":"exchange-022"},{"speaker":"松永委員","kind":"確認","question":"２４５ページの子ども食堂開設希望者等支援について伺います。こども食堂ネットワークというホームページを確認したところ、３カ所掲載されておりました。その３カ所について、品川区では連携をとられているのかをお伺いいたします。今後進めていく事業は品川区独自の子ども食堂ということになるのか、それとも今現在ある子ども食堂と同じような形になるのか、それについてちょっと伺いたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"子ども食堂のあり方なのですけれども、区として子ども食堂を実施するのではなく、地域の子ども食堂の活動を支援するというのがこの事業の趣旨となっています。","voiceIndex":54,"id":"exchange-023"},{"speaker":"松永委員","kind":"質問・要望","question":"ネットワークづくりということでよろしいですか。最後に、２４５ページの児童相談所移管推進経費について伺います、東京都内の人口は約１,３００万人で、児童相談所が１１カ所ということでありますけれども、法改正が行われまして特別区でも児童相談所が設置できるようになりました。平成２９年度予算では約９９８万２,０００円ということになっておりますが、その内容について、最後に伺いたいと思います。","respondent":"高山子ども育成課長","answer":"品川児童相談所等との連携の状況ですが、日常的なケースの共有の会議などは月１回持っておりますし、今後移管に向けて意見交換などを十分してまいりたいと考えております。","voiceIndex":56,"id":"exchange-024"},{"speaker":"筒井委員","kind":"質問・要望","question":"よろしくお願いします。私からは２５５ページの保育園運営費で、保育園の入所基準などについてお聞きしたいと思います。委員長の許可を得て、品川区の保育園のご案内の提示をします。例えば補足説明の充実や、もっとすっきり読めるように再編集したり、フローチャートをつけたり、カラー刷りにしたり、そうした工夫をしていただきたいのですけれども、その点の区のご見解はいかがでしょうか。","respondent":"佐藤保育課長","answer":"窓口のほうで各入園相談係の担当がきめ細かく丁寧にご説明をしているところではありますが、今後もより見やすいような形の冊子に変更するなど検討をしていきたいと思います。","voiceIndex":59,"id":"exchange-025"},{"speaker":"筒井委員","kind":"質問","question":"ですから、区民の納得感、そして品川区の、このイタチごっこ状態からの脱却、不合理な転入の歯どめを考えなくてはいけない。この２つを解決するためには、区内在住年数をより重視すべきだと考えております。2)階層の低い者。ほかにもさまざま品川区民の区内在住年数を重視する方策はあると思いますけれども、こういったことについて品川区はどうお考えでしょうか、お知らせください。","respondent":"佐藤保育課長","answer":"その中で一定階層というところで幅を持たせている対応はしているところです。委員ご提案の階層をとりますと、事務処理がさらに増えること、それから、保護者の方へのご説明も複雑になるなど、ある程度課題があるところです。","voiceIndex":61,"id":"exchange-026"},{"speaker":"筒井委員","kind":"質問・要望","question":"この基準というのは各自治体で決めることができますので、近隣の２３区でほかにやっていないから品川区はやらなくていいということにはならないので、やはり品川区、ここは先行モデルとして区内在住年数を重視するという基準を設けてもよろしいのかなと考えております。そうした啓発も忘れずにぜひ行っていただきたいのですけれども、その点いかがでしょうか。","respondent":"佐藤保育課長","answer":"品川区では、在宅子育て支援の面でも事業を展開しておりますので、今後もそれらの周知に努めてまいります。","voiceIndex":63,"id":"exchange-027"},{"speaker":"横山委員","kind":"質問・要望","question":"私からは、２４５ページの児童相談所移管推進経費についてをお伺いいたします。本会議において、我が会派の鈴木真澄委員の代表質問でも、前向きなご答弁をいただいたところであります。光は皆様の中にあるのだと感じた瞬間でした。こうした現状を受けとめ、品川区としてできることを一歩ずつ進めていただきたいと考えますが、最初に一言、児童相談所移管推進への区の思いをお聞かせください。","respondent":"高山子ども育成課長","answer":"児童相談所設置に向けてのということで、濱野区長を中心に、今回の児童福祉法の法改正までこぎつけたということで、品川区としましては引き続き早期の設置に向けて努力を進めてまいりたいと思います。","voiceIndex":66,"id":"exchange-028"},{"speaker":"横山委員","kind":"提案","question":"こちらは都に確認をしていただきたいのですけれども、児童福祉士の都の研修ですが、毎年２０人の受け入れを、来年度は３５人へと拡大する予定です。区としては研修人数を増やしていただくというのは大変ありがたいことではありますが、実際に研修を受け入れる現場の声を大切にしていただきたいと要望いたします。品川区からも派遣をお考えでしょうか。区からのバックアップをあわせて要望いたします。","respondent":"高山子ども育成課長","answer":"先日、相模原市の児童相談所設置にかかわりました当時の担当課長の方のお話を伺った際に、やはり派遣されている職員のメンタルケアということで、当時のその担当課長も足しげく派遣先のほうに足を向けまして、派遣されている職員を励ましたというようなお話も伺っておりますので。","voiceIndex":68,"id":"exchange-029"},{"speaker":"横山委員","kind":"提案","question":"体制のほうは確認できましたので、準備をぜひそのように進めていただいて、都のほうにも積極的に提案をしていただければと思います。私、先月大阪府茨木市の女子会に参加してまいりました。子育て支援の地域コミュニティをどう育てていくか。そうしたことを、品川区で今後コミュニティ的にもつくっていければと思うのですけれども、区としてどのように支援していただけるのか、お考えをお聞かせください。","respondent":"高山子ども育成課長","answer":"目指すところは、品川区で持ち合わせておりますさまざまな資源、それから地域の皆様、保護者の方々、主任児童委員の方々、民生児童委員の方々、そして町会・自治会をはじめとするさまざまな地域の方々が子育て支援にかかわっていただくことで。","voiceIndex":70,"id":"exchange-030"},{"speaker":"横山委員","kind":"質問・要望","question":"引き続きそちらのコミュニティの支援のほうもぜひお願いをいたします。品川区児童相談員、主任児童委員の宿泊研修が３年前に実施されていますが、平成２８年度の実施の参加人数と研修内容、それを来年度どのように活かしていくとお考えでしょうか。２月１６日の最新の区長会と部課長会でのモデル３区、荒川区、世田谷区、江戸川区の現状と、情報のフィードバック方法を確認させてください。","respondent":"高山子ども育成課長","answer":"具体的には用地の確保、そして設計におおむね２年、そして建設に２年ということで、５年程度の期間を見込むところではありますが、これにつきましては可能な限り前倒しができるように、１年でも半年でも早くこのスケジュールが進むように。","voiceIndex":72,"id":"exchange-031"},{"speaker":"あくつ委員","kind":"確認","question":"今回、認知症ケアパスを第１号被保険者の全世帯にお配りになるというところで、まず入り口となる認知症カフェの記載がちょっと少なかったということでお伺いをしましたところ、ご答弁の途中までは、まだ事業を始めていないから登録をしていないので載せられなかったというご答弁がありましたけれども、では、登録をこれからされるということで。","respondent":"永尾高齢者福祉課長","answer":"登録をいたしましたら、ケアパスのほうに掲載をしていきたいと考えております。ケアパスにつきましては、４月１日付でホームページにアップさせる予定になっております。","voiceIndex":75,"id":"exchange-032"},{"speaker":"あくつ委員","kind":"質問・要望","question":"障害者の人権はどこにあるのでしょうか。このような内容でした。これはすごく難しい問題だと思うのですけれども、施設での異性による介護というのはどう考えられているのか、これは障害者部門にもお伺いをしたいと思います。そして、高齢者部門にも伺いたいのですが、このような現状に対して果たして仕方がないで済ませていいのか、統一した対応を求めたいと思うのですが、いかがでしょうか。","respondent":"中山障害者福祉課長、永尾高齢者福祉課長","answer":"すなわち、女性に対しては女性職員が、男性に対しては男性職員がということで対応させていただいています。ショートステイの場合も、できるだけ女性と男性の両方の介護職が夜勤に入って対応するというのが基本になっております。それで、あとはこのご本人様への対応というところもちょっと問題があるかなというような感触もありましたので、施設側のほうにはできるだけ同性介護をするということと。","voiceIndex":77,"id":"exchange-033"},{"speaker":"あくつ委員","kind":"質問・要望","question":"すごく難しい問題です。予防としては品川区もこの手帳保持者への調整指数を明確に入れていただきたいということです。これは要望なのですけれども、できれば面談というか、地域によっては、わざわざ区役所に来なくても、その方のお宅の近くの地域センターで面談をするといった対応をとっているところもあるようですけれども、そういった考え方についてどう思われるか、ご見解を伺いたいと思います。","respondent":"佐藤保育課長","answer":"今後見直していきたいと思います。相談の件に関しても、申請している方々に十分配慮して対応していきたいと思います。","voiceIndex":80,"id":"exchange-034"},{"speaker":"あくつ委員","kind":"提案","question":"続きまして、２４５ページの子どもの未来応援事業というところで、平成２８年第３回定例会の一般質問で幾つかご提案させていただきました。善意の受け皿となるネットワークということで、区民や企業からの寄附の受け皿、子ども食堂の開設や学習支援など、ボランティアの相談窓口として、個人や団体をマッチングするネットワークの仕組みが必要ですということで求めました。","respondent":"廣田子ども家庭支援課長","answer":"ただし、今回の子どもの未来応援プロジェクトの検討委員会については内部の検討ということになっておりますので、この中で平成２９年度に実施するべきもの、平成２９年度から引き続きさらに深めていくものといったところで、課題の洗い出しをしていますが。","voiceIndex":82,"id":"exchange-035"},{"speaker":"あくつ委員","kind":"質問","question":"最後に２３７ページ、障害者の芸術活動支援事業、障害者福祉課と教育委員会にも若干お伺いをしたいと思います。そこで質疑の時間をいただきましたので、アートディレクターの方に、障害者の芸術活動を熱心に推進する品川区について、今後進むべき方向性はという質問をさせていただきました時に、こんなすばらしいアール・ブリュット展を行政主催で開催できているのに、子どもたちが誰も見に来ていないと。","respondent":"中山障害者福祉課長、村尾教育総合支援センター長","answer":"これからやはりこういった芸術活動を通じて、相互に理解をし合うということはとても大事なことかと考えていますので、私もＰＲのほうを教育委員会にもぜひさせていただければと考えています。まさにその一つがインクルーシブ教育ですけれども、今回のアール・ブリュット展につきましても、今後すぐに区のカリキュラムの中に入れるというのはなかなか難しいとは思うのですが、まずは児童・生徒だけではなく保護者も含めて。","voiceIndex":84,"id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今年は大崎夢さん橋も含めてアール・ブリュット展をやるというふうに、プレスにも出ております。既に学校に声をかけているというお話も伺いましたし、逆に今回は休み、前回は休みに開催できなかったので、今回大崎のほうでできるということですので、ぜひ多くの子どもたちに来ていただき、これをインクルーシブ教育、真のインクルーシブ社会の実現に向けて活用していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-037"},{"speaker":"吉田委員","kind":"質問","question":"最初は２２０ページ社会福祉費総務費だと思いますが、現行の障害福祉計画の計画期間、２０１５年から２０１７年と認識しております。２０１７年は次の計画策定の年と思いますが、その費用がどこに計上されているのか、ちょっと探せなかったので教えてください。計画策定の議論をどの程度想定して、どれくらいの費用になっているのか、まず伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"計画の策定に当たってなのですが、大もとの品川区障害者計画のほうは継続ということになります。ですので、この考え方を継承しつつ、過去２年間の実績、それから今年度の数値予測を立てながら、実質的な数値目標を立てていくことになると考えております。","voiceIndex":90,"id":"exchange-038"},{"speaker":"吉田委員","kind":"質問","question":"２０１５年８月にヒアリングをした際には、まだ施行後すぐということでこの２つの協議会の性格をどのようにするかこれから検討ということで伺いました。厚生委員会の議事録を読みますと、検討された結果、地域自立支援協議会がそのまま障害者差別解消支援地域協議会の性格を持っているのかなと理解しているのですが、それでよろしいか伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"品川区では今自立支援協議会のメンバーに就労の方ですとかあるいは権利擁護ということで弁護士にも入っていただいておりますので、この中で差別解消の地域の協議会の役目も果たしていきたいと考えております。","voiceIndex":92,"id":"exchange-039"},{"speaker":"吉田委員","kind":"確認","question":"厚生委員会の議事録を確認したのですけれども、２０１６年度は地域自立支援協議会を年３回ぐらい開く予定ということでしたが、現段階で実績はどうなっておりますでしょうか。それから、専門部会を設置されているのですが、その開催状況も伺いたいと思います。品川区のホームページで検索したのですけれども、うまく当たらなかったのですが、公開されていないのか、その辺についてもお聞かせください。","respondent":"中山障害者福祉課長","answer":"あくまで相談支援センターのほうは相談から出てきた中身についてより具体的に説明をする立場にありますし、法人の代表というのはサービスの担い手ということで入っていただいているので、そういった仕切りをさせていただいているところです。","voiceIndex":94,"id":"exchange-040"},{"speaker":"吉田委員","kind":"質問・要望","question":"さっき議事録の公開のことで、議事録が公開されているかどうか後で教えていただきたいのですが、私たち常に当事者の参加を求めておりますが、会議だけの参加では議論が難しい点もあるのかなというのは理解しております。さきほどの議事録の公開のところだけ教えてください。","respondent":"中山障害者福祉課長","answer":"答弁漏れがあり、失礼いたしました。議事録については、現在公開をしていない状況です。","voiceIndex":96,"id":"exchange-041"},{"speaker":"吉田委員","kind":"質問・要望","question":"ページは後なのですけれども、先に障害者福祉費の生活支援サービスにおける移動支援事業について伺います。事業開始当時は当然人数を把握して行ったはずと思うのですが、開始の翌年度に減額というのは、予算立ての時期を考えると、どこまでの実績を評価しての減額なのか、こういう評価をするのはせめて１年間の実績を見ることが必要ではないかと考えるのですがいかがでしょうか。","respondent":"中山障害者福祉課長","answer":"ただ、もちろんこれは支給の決定といいますか移動支援の必要数を勘案して行っているものですので、足りなければ足りないなりにまた予算措置のお願いはしていくような形をとっているところです。","voiceIndex":98,"id":"exchange-042"},{"speaker":"吉田委員","kind":"質問","question":"まだ１年経過しない中での実績で判断せざるを得ない、ある程度はそれは理解するのですけれども、そういうことなのでしょうかということを後でもう一回教えてください。総時間数しか伺えなかったので、身体介護ありとなしで支給決定総時間数に対する実利用時間数に違いはあるのかないのか、その辺も、細かいところはわからなかったらざっとで結構ですので、教えてください。","respondent":"中山障害者福祉課長","answer":"ただ、そういった事例もありますが、できるだけ親御さんと離れてほかの人の支援を受けながら外出していくような環境を整えていきたいと考えております。","voiceIndex":100,"id":"exchange-043"},{"speaker":"吉田委員","kind":"質問","question":"ニーズはあることはわかっておりますので、ぜひ使いやすいように今後さまざま検討していただけたらと思います。品川・生活者ネットワークには利用する人からのお声もいただくのですけれども、事業者の声で、例えば身体介護なしだと報酬単価が低く、また、この事業を使いたい方のニーズの多くは送り迎えのどちらかなのです。品川区でもそういう措置を考えていらっしゃるかどうか教えてください。","respondent":"中山障害者福祉課長","answer":"移動支援というのはどうしても行ってそこで支援をして帰ってということはあるのですが、時間が短ければ短いほど往復の時間がかかってしまい、支援の結果お金にならないところがあるというのは事実だと思いますので、その辺はちょっと研究課題とさせていただければと考えています。","voiceIndex":102,"id":"exchange-044"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういうふうに考えていてよろしいかということも確認させてください。最初に依頼があったときにはコーディネーターの方がその方のお宅まで伺って様子を確認するということを聞いております。２回目以降はどうなのでしょうか。状況は随分違いますよね。どの辺にあるかや、高さはどれくらいか、どういった構造なのかなども確認する必要があり、３０分というのはどうなのかなと言っておられました。","respondent":"大串福祉計画課長、中山障害者福祉課長","answer":"その辺につきましては、コーディネーターが当然間に入ってという形になりますけれども、相談をしていただいた方、また地域支援員の方、こういったところにつなぎながら課題の解決に努めていきたいと考えています。庁内の療育支援ネットワークの中では周知をしているところなのですが、学校にかかわる移動支援、通学等支援については、例えば保護者の介護状態ですとか疾病の状態、こういうことがあって初めて認めているものですので。","voiceIndex":104,"id":"exchange-045"},{"speaker":"吉田委員","kind":"提案","question":"移動支援のほうはわかりました。機会がありましたら、提案などさせていただきたいと思います。それからもう一件、腰を痛めて動けないから毎日少しずつ家事に入ってほしいという依頼があって、その一部に入ってもらえないかという依頼です。このような事例を区として把握していらっしゃるのでしょうか。こういうときにどういうふうに考えるのか、現段階でのお考えを教えてください。","respondent":"大串福祉計画課長","answer":"そうした中で、今挙げていただいたような事例、こういったものが積み上がっていく段階において、こういったコーディネート、これもスムーズにいくものと考えております。今後ともそういった形でコーディネート業務をやっていきたいと考えています。","voiceIndex":107,"id":"exchange-046"},{"speaker":"石田（ち）委員","kind":"確認","question":"介護保険の介護給付費等準備基金について伺いたいと思います。先日も質問をされていたのですけれども、改めて伺いたいと思います。第６期は１７億８,０００万円から１１億５,０００万円を取り崩して６億３,０００万円残るという計画でよかったかまず確認と、平成２７年と平成２８年の取り崩し額と、平成２８年末での残高。それから平成２９年の取り崩し額と残高の見込みを伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"平成２９年度につきましては、こちらにつきましても取り崩し額は今のところ予算上は２億４,２７８万２,０００円となっております。当初予算書上の残高の見込みというのが１５億３,３１４万８,０００円となっているところです。","voiceIndex":110,"id":"exchange-047"},{"speaker":"石田（ち）委員","kind":"質問","question":"この平成２７年の取り崩し額が、昨年の質問の際に聞いたときには５,３１１万６,０００円を取り崩したと答弁されているのですけれども、今２,０００万円ということなのですが、この違いは何か伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"この基金の年度末の残高というのが出納閉鎖期間中の４月・５月分の給付分が含まれてあります。それで今の時期ですと４月・５月の給付額がまだ確定しておりませんので、見込み額で取り崩し額を決定しています。その金額が５,３００万円余と申し上げたということです。","voiceIndex":112,"id":"exchange-048"},{"speaker":"石田（ち）委員","kind":"質問","question":"これは当初の計画が変わったということなのでしょうか。なぜこれだけ違うものになるのか。１７億８,０００万円から少なくとも２,０００万円と６,５７０万円が取り崩されているということですので、ここでまだ１７億円残っているということの説明を伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"区のケアマネジメント自体は変更しているところではないので、相談はきちんとやっているところでサービスは行き届いていると考えておりますが、主な原因としては報酬の改定が予想よりも多かったというところになっています。","voiceIndex":114,"id":"exchange-049"},{"speaker":"石田（ち）委員","kind":"質問","question":"第５期のときも、当初の計画は１８億円余から１０億円取り崩して８億円が残るという計画でしたけれども、第５期の最後の年、平成２６年の５月末では１９億円が残っているという状況でした。この基金は６５歳以上の人の保険料です。そして、今回は介護保険制度の改悪で要支援１・２の方がサービスから外れています。使っていくべきだと思うのですけれども、いかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"そういうことも考えながら、第７期介護保険事業計画の策定が平成２９年度になりますので、その辺の兼ね合いと皆様にお支払いいただく保険料の金額の兼ね合いを見ながら検討していきたいと考えております。","voiceIndex":116,"id":"exchange-050"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですので、こうした現状を見れば、さらにこの余っているお金の活用をしてほしいと私たちは思います。しかも毎回計画と違います。こういった計画の中でこれだけ余らせるということが、品川区の本当の計画になってきているのでしょうか。そこをまず伺いたいと思います。そして、こうした状況では、介護労働者も集まらないと。改めて現場の実態を調査するアンケートなどを行うべきではないでしょうか。","respondent":"永尾高齢者福祉課長","answer":"今まではそういうことをしなくても専門的なサービスをどのような人にも給付しておりましたが、やはりその方の状態によってサービスをきちんと仕分けていかないと、これから２０２５年を乗り切れないということが最大の課題になっておりますので。","voiceIndex":118,"id":"exchange-051"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"アンケートの実施も伺ったのですけれども、やはり現場の実態と区の認識はずれていると思うのですね。ぜひそこを調査をしていただきたいと思います。それから特養ホームの、先月２月が締め切りだったと思うのですけれども、状況を伺いたいと思います。申請者総数、あと審査対象者数と介護度別の人数を教えてください。","respondent":"永尾高齢者福祉課長","answer":"アンケートにつきましては、匿名のアンケートというよりは直接区役所のほうに事業者の皆さん、事業所連絡会等でもご意見をいただいていますので、その中できちんと把握をしていきたいと考えております。","voiceIndex":120,"id":"exchange-052"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"要介護１・２の方が申し込みの対象から外れた上でもこれだけのお申し込みがあるということで、これからまたさらに南品川４丁目にも民間ですけれども特養ホームができます。そしてさらに障害者施設なども合築といいますか一緒の敷地で進めていくということを強く要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":122,"id":"exchange-053"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は２４５ページのしながわネウボラネットワーク経費と２５１ページの病児保育について質問いたします。税金を納めるあるいは納めることになるような人口、若年層が著減する、ほとんどいなくなってしまうということは、国家が立ち行かなくなるという、非常に日本が衰退していくという危機と考えますが、区のご見解はいかがでしょうか。","respondent":"柏原企画調整課長","answer":"品川区におきましては、区のほうでも人口推計をしておりますけれども、当面のところ１０年といったスパンの間では人口が増えるとしておりますけれども。","voiceIndex":124,"id":"exchange-054"},{"speaker":"鈴木（博）委員","kind":"質問","question":"アベノミクスの新３本の矢の新第２の矢は夢をつむぐ子育て支援、希望出生率を１.８に引き上げるというような目標を国家として掲げております。欧州ではフランスやフィンランドなど子育て施策を強力に行うことにより、合計特殊出生率を１.２から１.８まで上げた国もあります。このような経験は学ぶべきものがあります。病児病後児保育に対する区の認識はいかがでしょうか。","respondent":"佐藤保育課長","answer":"区としては病気のときはご家庭で見ていただくというのが基本ですが、保護者の就労支援という面でニーズが高まっているという認識はありますし、品川区子ども・子育て計画上もそのようになっております。","voiceIndex":126,"id":"exchange-055"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"我が会派の松澤委員が長年病児保育の充実を求めてきた要望の一部が実現したものとして高く評価しております。平成２６年度の決算特別委員会で私が求めた病児保育のキャンセルを利用者として取り扱うように再度要望したいと思いますが、区のご見解はいかがでしょうか。病児保育を就労支援だけではなく子育て支援として位置づけるというこの考え方に対しては、区のご見解はいかがでしょうか。","respondent":"佐藤保育課長","answer":"子育てに悩んでいるお母さんが多数いるというのも保育園から聞いております。総合的な子育て支援の検討が今後より必要になってきているという認識です。","voiceIndex":128,"id":"exchange-056"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"病児保育は定員を増やすだけではなくて、施設を増やすことを目指していただきたいと思います。病児保育は身近に点在し、いつでも必要なときに利用できる存在であるからこそ安心であり、セーフティーネットとして頼れる子育て支援の施設になると思います。ぜひそのような申し出があった場合は、区としても前向きに対応してほしいと要望したいと思いますが、区のお考え、立場はいかがでしょうか。","respondent":"佐藤保育課長","answer":"来年度、品川区子ども・子育て計画５年間の中間年を迎えることもありまして、各事業の実績等の点検を行う予定です。この中で病児保育についても委員の皆様にいろいろなご審議をいただく予定です。","voiceIndex":130,"id":"exchange-057"},{"speaker":"鈴木（博）委員","kind":"質問","question":"前向きなご答弁、非常にありがたく、心強いと思います。次に、しながわネウボラネットワークについて質問いたします。２０１６年から本格的にスタートしたしながわネウボラネットワークの事業内容の説明と、現在の相談件数の実績についてご説明をお願いします。新しく始まったしながわネウボラネットワークの事業と、品川区が従来きめ細かく行ってきた子育て支援のさまざまな施策の関係はどうなのか。","respondent":"高山子ども育成課長","answer":"主な事業の中身としましては、相談事業ということで３つの保健センターで実施しております妊産婦の面接、そして児童センター５つで行っております子育てネウボラ相談事業といった２つの相談事業、そして産後家事・育児支援事業。","voiceIndex":132,"id":"exchange-058"},{"speaker":"鈴木（博）委員","kind":"質問","question":"それに関して、国のほうでは子育て世代包括支援センターの構想というのはありますが、これと品川区のネウボラの関係はどうなのかということを伺いたいのと、現在のしながわネウボラネットワークは５カ所のみですが、他の児童センターでも相談事業は行われています。","respondent":"高山子ども育成課長","answer":"１点目の子育て世代の包括支援センターとの関係ですが、こちらのほうでは妊娠期から子育て期にわたる総合的な相談や支援をワンストップで実施する、そういったものを総称するもので、国の関係者の説明を伺う限りは、必ずしもこの１つの建物で行うものをいうわけではなくて。","voiceIndex":134,"id":"exchange-059"},{"speaker":"木村委員","kind":"質問・要望","question":"２２７ページの下から８行目、高齢者の趣味・健康づくり事業。２２９ページ、上から６行目、介護予防・シニア活動拠点運営費からの質問です。ずばりお聞きいたしますが、「輝く笑顔住み続けたいまち」になるには、高齢者や障害者が元気に住み続けていくために、区としてはどのような努力が必要と思うでしょうか。区民には何を求めますか、お答えください。","respondent":"大串福祉計画課長","answer":"さまざまな施策の展開が必要になってきているというところはありますけれども、例えばバリアフリーあるいは優しいまちづくり、こういった住み続ける上での基盤の整備、あるいは施設の整備であるとかサービス、こういったものの充実、あるいは最後にありましたけれども。","voiceIndex":138,"id":"exchange-060"},{"speaker":"木村委員","kind":"質問・要望","question":"バリアフリーとかそういういろいろな面におきまして、高齢者そして障害者の皆さんが健康で過ごせる、笑顔で過ごせる品川づくりをお願いしたいと思います。下から３行目のいきいき健康マージャン２０５万円余からですけれども、先日私の一般質問でもお伺いをいたしましたいきいき健康マージャンからです。もう一歩踏み込んで前向きなお言葉をお聞かせをいただきたいと思います。","respondent":"松山高齢者地域支援課長","answer":"共催者である日本健康マージャン協会と協議を進めまして、今後この人気の高い健康マージャンの場所の提供を１カ所でも多くという委員のご要望に従いまして協議を進めてまいりました。","voiceIndex":140,"id":"exchange-061"},{"speaker":"木村委員","kind":"質問","question":"少し前向きでありましたけれども、この養成期間というか習得期間ですね、大体どのぐらいかかる予定ですか。お聞かせください。","respondent":"松山高齢者地域支援課長","answer":"それはただ単にスキルだけを教えるわけではなくて、いらっしゃる高齢者への対応ですね、マージャンの場合は本当に体を使うというよりも、まずは座って頭脳プレーということなので、かなり身体機能が低下した方も、かなりご高齢の方もご参加いただいております。","voiceIndex":142,"id":"exchange-062"},{"speaker":"木村委員","kind":"意見","question":"よろしくお願いをしたいと思います。次に２２７ページの下から８行目、高齢者の趣味・健康づくり事業の中の６行下のいきいきカラオケ広場２万円からですけれども、予算が２万円ですけれども、どうすれば年間通してカラオケ事業が２万円でできるのか、ご見解をお聞かせください。","respondent":"松山高齢者地域支援課長","answer":"カラオケ店舗としましては、会場の提供を少し安く利用できるような形で実績報告もいただいております。したがいまして、この２万円というのは登録カードの用紙ですとか通知分になっております。","voiceIndex":144,"id":"exchange-063"},{"speaker":"木村委員","kind":"質問","question":"２２９ページの上から６行目、介護予防・シニア活動拠点運営費、１億８２４万円余からですけれども、５つの大きな事業が行われています。いきいきラボ関ケ原、山中いきいき広場はボランティアで運営されていることをお聞きをいたしました。どのようなボランティアグループが運営をされているのでしょうか。","respondent":"松山高齢者地域支援課長","answer":"一方、山中いきいき広場につきましては、こちらは平成１２年に山中小学校の空き教室を活用しまして介護予防事業の実施場所としたものでありまして、山中小学校の近隣のシニア世代、あるいは高齢者の方々が集まりまして。","voiceIndex":148,"id":"exchange-064"},{"speaker":"木村委員","kind":"質問・要望","question":"いきいきラボ関ケ原は、シニアの健康維持、向上、そして生きがい、仲間づくりのための活動拠点ですけれども、この拠点を活かすため、多様化するニーズに対応できるフレキシブルな組織づくりという視点から、地域の有志に運営を委託し、何か楽しい体験ができる新しい場をつくるとともに、参加者や参加希望者から、また新たなグループが生まれるような広がりのある活動を目指しているそうでありますけれども。","respondent":"松山高齢者地域支援課長","answer":"委員おっしゃるとおり、こちらの関ケ原ラボですけれども、２３０名の方がボランティアとしてご登録いただいておりまして、その方々は特にＩＴスキルをお持ちの方々がいらっしゃいますので、区のパソコン教室ですとかタブレット教室。","voiceIndex":150,"id":"exchange-065"},{"speaker":"木村委員","kind":"意見","question":"このように時間を有効に活用し、健康を維持しコミュニケーションを図る楽しい時間を過ごすことは行政として願ってもないことだと思いますけれども、最後にこの行政としてのお考えをお聞かせください。","respondent":"松山高齢者地域支援課長","answer":"将来に向けまして、高齢化の進行により高齢者の身体機能が低下する方も要支援の方も増えるというのが予想される中、介護予防につながる自主的な活動の場というものの整備というのは必要だと考えています。","voiceIndex":152,"id":"exchange-066"},{"speaker":"塚本委員","kind":"質問・要望","question":"私からは、最初に５５２ページの居宅介護サービス等諸経費について、在宅介護についてということと、あと２４７ページからの保育従事職員宿舎借上支援事業について伺いたいと思います。こういったいわゆる職員が医療行為ができないというところで、インシュリン注射も含めてこういったショートステイ等が受け入れられないといった事例、どのような状況にあるか現状を聞かせていただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"インシュリンを打たなくても服薬でも対応できるという方については、そういうご説明をしながらなるべく受け入れるような体制を取っているところです。","voiceIndex":155,"id":"exchange-067"},{"speaker":"塚本委員","kind":"質問・要望","question":"やはり法律がどうしてもこの場合引っかかってくるわけですけれども、今、まず服薬とか別の形で何とかクリアできるということであればということであったので、この辺の周知はもれなくしていただきたいと思いますので、これは要望としてお願いしたいのですが、法律の医療行為に対する壁というものが今後どのような形で展開していくのか。","respondent":"永尾高齢者福祉課長","answer":"今、施設側のほうもなるべく受け入れられるような体制というところでは、２カ所のケアセンター南大井と、あとこれからできあがる上大崎の特養で受け入れられるような体制でありますので。","voiceIndex":157,"id":"exchange-068"},{"speaker":"塚本委員","kind":"意見","question":"これからこういったニーズがどんどん増えてくる可能性は極めて大きいと思いますので、よろしく対応のほうをお願いしたいと思います。次に、２４７ページ、保育従事者宿舎借上支援事業についてなのですけれども、今この事業は、いわゆる事業者が部屋を借り上げて、事業者と貸主との契約というところでこの事業の助成というのが前提となっております。","respondent":"佐藤保育課長","answer":"委員ご指摘の事例というのは、なかなか私どもではまだ把握をしておりませんが、補助事業の制度スキーム、趣旨として、法人が借り上げている住宅が対象になると考えております。","voiceIndex":159,"id":"exchange-069"},{"speaker":"塚本委員","kind":"質問・要望","question":"その法人が借り上げなければだめだよねという、だけれども本当にそれで受けられない方がいらっしゃるとなると、先ほど、つる委員からもありましたが、保育士の不足という問題が非常に言われている中で、今、区民住宅に住まわれている方が今度保育士になろうかというようなことを思ったりしたときに補助を受けられないのだということで。","respondent":"佐藤保育課長","answer":"区営住宅、区民住宅に関してはまた別の議論といいますか、施設整備費等もまた別にかかっている面もありますので、もし区営住宅等にお住まいの方に対する直接の補助になりますと、また別の枠組みで、別の制度になるかなと考えております。","voiceIndex":161,"id":"exchange-070"},{"speaker":"塚本委員","kind":"意見","question":"区営住宅になるとさすがにさまざまな意味で家賃が低く抑えられておりますので、これがこの助成の対象になるかと考えるとどうかなと私自身は思ったりもしますので、ちょっとまたさまざまな検討も必要かなと思いますけれども、保育士不足に対する一つの解消法としてこういったことも一考しなくてはいけない部分ではないかなという思いもありますので、どうか検討のほうをよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":163,"id":"exchange-071"},{"speaker":"石田（秀）委員","kind":"質問","question":"私は、まず２２５ページ、特養などの施設関係のところから入りたいと思います。その中で品川区は介護福祉専門学校を持っています。これは学校をつくろうという英断があったわけで、施設の人員というか定員に対する職員数、これは結構守られていると思うのだけれども、そこについてはこの介護福祉専門学校があったからこういう対応ができたとお思いなのか、そこら辺のところをまずお聞きをしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"学校の貸付金の制度なども独自につくっておりまして、３年間は品川区の施設に入らなければいけないということになっておりますので、そういう意味では施設の職員の人材確保という面で寄与しているかなと考えています。","voiceIndex":165,"id":"exchange-072"},{"speaker":"石田（秀）委員","kind":"質問","question":"仕事の内容を全体で把握して、これは資格がなくても対応できるのではないか、これは外国人の方でなくても資格のない方を採用して、その仕事を軽減して、例えばさまざまなローテーションの中でそういう方をどんどん活用していって対応できるような形にしていこうというのも少しずつ始まり出したけれども、なかなかこれもうまくいっていないと我々も聞いているのだけれども。","respondent":"永尾高齢者福祉課長","answer":"それで、介護士の仕事の軽減ということですけれども、こちらにつきましては外国人の採用であろうが日本人の採用であろうが、やはり臨時職員というか、長時間働けない方の活用というのはとても大事だと思っておりまして。","voiceIndex":167,"id":"exchange-073"},{"speaker":"石田（秀）委員","kind":"質問","question":"外国人の場合だと、仕事の内容にその日の記録を残さなければいけない。それはどうしてかというと、生活福祉などは例えば住宅型有料老人ホームは松戸とか草加とかそういうところにあっ旋をしてというのがあるではないですか。そういうのもこれから高齢者の特養などはそういうあっ旋をできるような提携を結んでいくという考えがあると思うのだけれどもその辺の考え方を教えてください。","respondent":"永尾高齢者福祉課長","answer":"それで、地方の特養の関係になりますけれども、現在地方のほうは空きが結構あるかなという認識を持っております。","voiceIndex":169,"id":"exchange-074"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だけれども、２割ぐらい希望される方がいた時に、空き情報などをとってどうぞこういう、もちろん今言ったように住民票の問題もあったりするので、それはきちんと確認をとってやらなくてはならないというのはもちろんわかっておりますけれども、あっ旋ができるということをやはり区からもしっかり相談があったらこういうところがありますよという案内を、有料老人ホームなどは完全にそういうところがあるので。","respondent":"柏原企画調整課長","answer":"そういったところで、その活用について今まさに所管部門と検討しているといったところでございまして、恐らく民営民設の事業者が入るということになれば、一定程度のご提案をいただきながらということになろうかと思います。","voiceIndex":171,"id":"exchange-075"},{"speaker":"石田（秀）委員","kind":"提案","question":"もちろん民設民営で提案をしていただくということだと思います。その中で、私が思っているのは、ここにはやはり区のほうでプロポーザルというと今言ったように保育園、これは多分認可になるのだろうけれども、認可ぐらいの規模ということは必ずプロポーザル提案があって、これはやってください、それ以外にはどういうふうにする、という条件を、民設民営だと出していくわけですよ。","respondent":"柏原企画調整課長","answer":"今委員のほうから保育に対する学校といいますか、養成する施設ということであろうかと思います。今現在施設の構成であるとかそういうところはまさに検討しているといったところでございまして、区としてどういった行政ニーズに対応していくのかというところがあります。","voiceIndex":173,"id":"exchange-076"},{"speaker":"石田（秀）委員","kind":"提案","question":"今そういう状況にある中で、もちろん今おっしゃったようにみやこ荘のときの話なんかも漏れ伝わって伺っているわけでありますけれども、行政としてそういう提案をしてご理解をいただく努力をして、そういう需要に対する対応をしていくというのはやはりこれは、もちろん地域のご意見もあるけれども、行政判断としてそういうことをしていくということも、私は一つの行政の役割だと思っているので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":175,"id":"exchange-077"},{"speaker":"西本委員","kind":"質問・要望","question":"その考えはこれからも変わらないのかということで確認をしたいと思います。何度もこれもお話をさせていただいているのですが、なぜ民営化をするのですか。その中での税の使い方をどうしていくのですかと質問したと思います。もうやめませんかということです。非常にノウハウの継承が必要でありますので、新規採用をしていただきたいということをお願いしておりますけれども、その状況はどうでしょうか。","respondent":"佐藤保育課長、吉田保育施設調整担当課長、高山子ども育成課長、米田人事課長","answer":"１点目ですが、病児保育の関係ですが、先ほどご答弁差し上げたとおり、区としては病気のときはご家庭で見ていただくというのが基本ですが。１点は、民間活力の活用ということで私立保育園においては特色のある保育等の実施によって保護者の信頼を得るなど着実な実績があるということと。児童センターは言うまでもなく地域の子育て支援の拠点ということで、これまでも多くの役割を担ってまいりました。これまでと変わりません。","voiceIndex":177,"id":"exchange-078"},{"speaker":"西本委員","kind":"質問・要望","question":"やはり親子の絆をつくっていくためには、どういう施策が必要なのかということを十分に考えてこれから事業を展開していただきたいと思います。その歴史をしっかりと受けとめて、では品川区の保育というのはどういう保育になってしまうのですかと、それを非常に私は残念に思っております。もうそろそろいいのではないでしょうか。お役は終わったのではないでしょうかということです。","respondent":"吉田保育施設調整担当課長","answer":"区の基本方針としましては、区立保育園を当面５園程度、１年あたり１園ずつ民営化いたします。区立保育園は区立幼稚園とともに、乳児教育の中核となることから相当数は区立のままで残します。","voiceIndex":182,"id":"exchange-079"},{"speaker":"のだて委員","kind":"質問","question":"私からは２４５ページのひとり親家庭支援事業と、２６７ページの生活保護費に関連して伺います。現在、生活保護費では子どもが１８歳を過ぎると生活保護から切られてしまい、一人分の扶助が受けられなくなってしまいます。そうなったときに、特にひとり親家庭は大変です。本来勉学に専念すべき大学生などの学生の生活保護が切られ、アルバイトをしなければならない状況を区はどう認識しているのか伺います。","respondent":"伊東生活福祉課長、廣田子ども家庭支援課長","answer":"今委員ご指摘のとおり、１８歳を過ぎますと、いわゆる世帯分離という形で生活保護からはずれるということは、そういうことになってあります。ひとり親世帯につきましては、区の奨学金で対応してございませんで、東京都の制度の母子父子福祉資金のほうの貸し付けを行っています。","voiceIndex":185,"id":"exchange-080"},{"speaker":"のだて委員","kind":"質問・要望","question":"この間生活保護が平成２５年度から引き下げられてきましたけれども、やはりこういったところも全体的に今やはり生活保護を受けている方から聞くと、生活していくのもなかなか大変だという声が寄せられますので、国ではその基準、見直しの検討も行っていくということですので、基準の引き上げを求めていただきたいと思いますが、いかがでしょうか。","respondent":"伊東生活福祉課長","answer":"それに毎年毎年、物価動向や社会動向等を勘案してそれぞれの基準改定は行っておるところです。前回の大きな変更というのは５年ごとの見直しという中でやられたものですので、それが昨年、平成２８年４月の段階で終わっております。","voiceIndex":188,"id":"exchange-081"},{"speaker":"のだて委員","kind":"質問・要望","question":"生活保護の基準については国で検討しているということでしたけれども、ぜひ品川区からも基準の引き上げ、そして１８歳で一律に切らないような柔軟な対応を求めていただきたいと思います。この国の制度から漏れてしまう方への区独自の給付型奨学金等、ひとり親家庭では保証人を立てられない方もいます。保証人がいなくても借りられる奨学金を創設していただきたいと思いますが、いかがでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"ひとり親家庭に対する大学進学の支援につきましては、奨学金だけが支援とは考えておりませんで。","voiceIndex":190,"id":"exchange-082"},{"speaker":"のだて委員","kind":"質問・要望","question":"さまざまなところで支援をしていっていただきたいと思うのですけれども、文教委員会の説明ではひとり親家庭が品川区内には約３,０００世帯ぐらいいるのではないかというお話がありました。そうすると、生活保護を受けられる家庭もあるのかなと思いますので、その中で生活保護を実際に受けている母子家庭、１５０世帯ぐらいしかいませんので周知をお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":192,"id":"exchange-083"},{"speaker":"渡部委員","kind":"質問・要望","question":"この間何度か伺っていました。当然連絡はさまざまな関係機関にしなければならないけれども、この予算額を見ていますとプレイリーダーが大人数配置されるわけでもないだろうし、その場合、やはり仲間に少し助けを求めてなんていうのも必要になってくるのかなと思ったのですが、その辺の連携などの仕組みと関係性がちょっと見えづらかったというかわからないので教えていただければと思います。","respondent":"高山子ども育成課長","answer":"事故等の対応につきましては、子ども育成課が委託の主管ですので、私どもへの連絡ののち公園部門と調整の上で滞りなく処理してまいりたいと考えております。","voiceIndex":194,"id":"exchange-084"},{"speaker":"渡部委員","kind":"質問・要望","question":"例えばそういうのだってただ今までだったら捨てていたのかもしれないけれども、場合によってはプレイパークにそれを持っていくと実はたき火の材料になったりとか、子どもたちが自主的に考えて遊べる道具にもなったりするのかななんて思ったものですから、その辺のやりとり等もできるようにしていただけると、本当にそこの公園で自然発生した、自然発生というわけではないのでしょうけれども。","respondent":"高山子ども育成課長","answer":"しながわ区民公園内のプレイパークですけれども、既にオープンしております北浜公園内の北浜こども冒険ひろば、こちらのほうの年間利用者数が大体１万４,０００人というところで。","voiceIndex":196,"id":"exchange-085"},{"speaker":"あべ委員","kind":"質問・要望","question":"私からは保育園や保育に関して、ページ数で言えば２４４ページからということになると思うのですが、地域の方から実際遭遇した話を中心にお伺いをしていきたいと思います。品川区として早急な検討とその結論を求めますけれども、現在の状況はいかがでしょうか。この機会に兄弟児の存在を念頭に置いて各種施策の見直しを、保育や教育を含めて行っていただきたいと思いますが、いかがでしょうか。","respondent":"佐藤保育課長、中山障害者福祉課長","answer":"審査については、審査といいますか指数等の認定に関しては誤りは許されない仕事ですので、現在トリプルチェックを行うなど、誤りがないような対応はしているところではありますが。現在、仮移転先ということもあり、やはり場所の面、それから職員の確保というところで課題がありますので、今現在そうしたご兄弟をお預かりするような場を児童学園で設けることはできないのですが、平成３１年度に向けましては。","voiceIndex":201,"id":"exchange-086"},{"speaker":"あべ委員","kind":"質問・要望","question":"兄弟児のほうなのですけれども、オアシスルームでの対応ということですが、これを親御さんのほうで毎回予約をして入れるかどうかということに気を使うのではなくて、もう母子通園が決まったらそこで仕組みとしてそのときにはオアシスが使えるというようなところまで持っていっていただければなと思います。課長の複数体制を敷くなど、さらなる組織強化も必要ではないかと思いますが、いかがでしょうか。","respondent":"佐藤保育課長、中山障害者福祉課長、齋藤子ども未来部長","answer":"兄弟児の関係のオアシス等の利用に関しては、障害者福祉課と連携をさらに密にして保護者の方の負担、不満が出ないように最大限努力してまいります。今どういう方策があるかというのは具体的にはないところではありますけれども。今回課題解決に向けてさまざま対処できたのもそういった支援のおかげだと考えています。これからもミスのないように保育課一丸となって進めてまいります。","voiceIndex":204,"id":"exchange-087"},{"speaker":"こんの委員","kind":"確認","question":"福祉人材確保・定着事業ですけれども、先ほど石田秀男委員よりも介護人材の確保のお話が出ておりましたが、介護には施設介護と在宅介護がありますので、まずは確認も含めて、いわゆる施設介護の介護職員というところで、予算書に４つの事業が記載されておりますけれども、その４つの事業、人材確保・定着のための対策事業、どのように取り組まれてきたのか、取り組もうとされているのか。","respondent":"永尾高齢者福祉課長","answer":"平成２８年度から開始しているのが、介護ロボットの導入支援というところで、今、２カ所で介護ロボットを試行しております。導入によって介護の負担が少しでも軽減されればと考えております。","voiceIndex":210,"id":"exchange-088"},{"speaker":"こんの委員","kind":"質問","question":"働きやすいように介護ロボットを入れたりなんなりという負担軽減をするのですが、現場では、やはり１対１のやりとりの中なので、これは本当に何とかしてさしあげたいという思いから、社会的地位というところを上げていくための方策というのは何かないのかと考えるのですけれども、その点はどのようにお考えでしょうか。","respondent":"永尾高齢者福祉課長","answer":"やはりどうしても昔のイメージで、介護職イコールお手伝いさん的なイメージを、勘違いをされて持っていらっしゃる方が、特に昔の方は多いように見えておりますけれども、そうではなくて、本当にプロの技術があるというところを。","voiceIndex":212,"id":"exchange-089"},{"speaker":"こんの委員","kind":"質問・要望","question":"本当に今、課長がおっしゃられたような感覚でご利用されてしまっている方というのは現実にいて、だけど、現場では高いコミュニケーション能力が求められているのです。何かございましたら、ご答弁をお願いしたいと思います。次の質問に移らせていただきます。","respondent":"大串福祉計画課長、永尾高齢者福祉課長","answer":"こちらの調査を通じた形で、地域の中での高齢者の方々の状況を把握していただいて、その中で今後３年間、任期の中で相談業務等を行っていただくといった流れになっているところです。高齢者相談員の方が定期的に訪問している中で、いろいろな細かい状況が記録として区のほうに戻ってきますので、その報告書については、全てケースワーカーがそのコメントを見て、必要なものはすぐに支援に回すようにしています。","voiceIndex":214,"id":"exchange-090"},{"speaker":"こんの委員","kind":"確認","question":"民生委員の訪問によって、また、訪問したことによって明らかとなった内容について相談に伺うという作業のための実態調査だということがわかったのですが、事務事業概要の中に、昨年から始まりました緊急の対応で、ひとり暮らしの高齢者がもしかしたら中でというときに、緊急対応で鍵をあけられない、それをあけられる費用として出ているものがあったのですけれども。","respondent":"永尾高齢者福祉課長","answer":"そういうケースがあったときには、民生委員が直接そういうところに入るということをしないようにしておりまして、必ず警察と区役所のほうに連絡をするようにし、立ち会いのもと、中に入って確認をするというふうにしております。","voiceIndex":217,"id":"exchange-091"},{"speaker":"こんの委員","kind":"質問・要望","question":"次の質問で、最後に確認だけさせていただきたいのですが、これは文教委員会でも報告がありました。南ゆたか保育園、一本橋保育園、これが改築することによって、併設されている児童センターが改築のときには休業となるということなのですが、利用者の方々のために、利用する児童センターの代替施設、あるいは代替事業、こうしたものはお考えであるかどうか、その考えだけ確認させてください。","respondent":"高山子ども育成課長","answer":"南ゆたか保育園改築に伴う児童センターの一時閉館という点ですが、品川区内には２５館の児童センターがございまして、近隣の大原児童センター、冨士見台児童センター、伊藤児童センターなどの児童センターをご案内する中で、２年間ではありますが。","voiceIndex":219,"id":"exchange-092"},{"speaker":"渡辺委員","kind":"質問","question":"私は、２２３ページ、品川介護福祉専門学校、２３１ページ、高齢者外出習慣化事業の、２点伺います。学ぶだけの場所ではないという思いがあります。そういう意味で、この品川区介護福祉専門学校は、定員割れは定員割れですが、健闘しているのではないかという見方も聞いたりしたのですが、他学校と比較して健闘されているのではないかという見方をどう捉えているか、教えてください。","respondent":"永尾高齢者福祉課長、松山高齢者地域支援課長","answer":"品川介護福祉専門学校の入学生の状況ですけれども、今年度につきましては、現在、２２名なのですけれども、あと２名が受験の予定になっていると聞いておりますので、鋭意努力をしております。成果と課題につきましては、新しく増えた平塚橋ゆうゆうプラザをはじめ、シルバーセンター等の会場につきましては、終了後、その方々を同じ施設でほかの介護予防事業につなげることができるのですが、身近なお店につきましては。","voiceIndex":222,"id":"exchange-093"},{"speaker":"渡辺委員","kind":"質問","question":"直接話も伺って、大島だとか新島だとか、なるほどなと。そういう中で、信頼性と信用で勝負できるのではないかと。そういう中で、学校の中にもこの要素をうまく活かして、検討いただいたらどうかということを伺いたいと思います。ランチタイムであれば、１２時から１時を避ける。商店の拡充という点で、先ほど成果と課題というのを伺いましたが、この辺でどんな見解を持たれているのか、教えてください。","respondent":"永尾高齢者福祉課長、松山高齢者地域支援課長","answer":"やはり学生の確保というところで、区の交流のある地方都市との連携というのも上手に使っていくことが大事かなと考えていますので、所管のところと協力していただきながら。今、品川区商店街連合会と連携させていただいてこの事業を組み立てておりますので、その後、商店街連合会との協議のもと、どういった工夫ができるか話し合っていきたいと考えています。","voiceIndex":225,"id":"exchange-094"},{"speaker":"高橋（し）委員","kind":"質問","question":"初めに、学習指導要領の改訂が発表されています。これは指導方法ですので、さまざまな考え方があるかと思いますが、この点についてどのようにお考えでしょうか。その方々で人件費を割り返してみると、約１９０万円ぐらいです。これは先ほどからほかの委員の方々からもありましたが、処遇についてのさまざまな状況があるのかと思いますが、こういった社会福祉法人の例について、どのようにお考えでしょうか。","respondent":"佐藤保育課長","answer":"３点目なのですが、私立保育園の保育士の給与については、私立保育園ということで、各法人で人件費、事務費、事業費という予算額を決めて、その中で、法人等の中で議決を受けて支払っている関係ですので、そういった事情があるというところもあるかもしれませんが。","voiceIndex":229,"id":"exchange-095"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"最後に、特別支援教育、保育園のほうの話ですけれども、巡回相談ということで、これも保育士のお話ですが、巡回相談に来ていただいている方のアドバイス、ケアアドバイザーというのでしょうか、その方の指導で保育士としての特別支援のノウハウが非常に身について、お子さんたちの指導に大変役立っているということで、大変ありがたいということなのですが、この件について。","respondent":"佐藤保育課長","answer":"３点目の、特別支援保育事業に関しましては、申し訳ございません、予算書２５５ページの下から７行目の保健業務委託等というところに入っておりまして、予算としましては、６４４万９,０００円をお願いしているところです。増減は基本的にありません。","voiceIndex":231,"id":"exchange-096"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ですから、ここの就学前の巡回相談については、ぜひ拡充して力を入れていっていただきたいと思います。ですから、ぜひ研修は同じ日にシフトがずれるように午前中に１回、あるいは夕方に１回と、同じ内容でもいいので、そういう形で複数回の実施と、あるいは先ほど土曜日の勤務の関係もありますので、土曜日に研修会の機会をつくっていただければと思います。","respondent":"久保田危機管理室長","answer":"場所は南大井一丁目８番１号ということで、現在も延焼中で、消防が対応しております。状況についてですが、１名の方がけがをしているということで、けがの程度は不明であります。現在、防災課職員が状況確認のために現場に向かっております。","voiceIndex":233,"id":"exchange-097","title":"議員研修会の内容と所要時間"},{"speaker":"南委員","kind":"質問・要望","question":"火災発生は本当に気になるところですけれども、質問させていただきたいと思います。２５７ページの公設民営保育園運営業務委託に関連して質問します。区は、２０１５年１２月に、公設公営から公設民営あるいは民設民営へと保育園政策を変更することを明らかにしました。その５,０００万円の違いとは何か。人件費ではないかと思いますけれども、この点について質問します。","respondent":"吉田保育施設調整担当課長、佐藤保育課長","answer":"委員から、５,０００万円下がっているのは人件費かということでご質問いただいている件なのですけれども、民営のところにつきましては……。その後、私のほうで今年度の８月に文教委員会でご説明したとおり、今現在は公立、私立ともに１００名定員の保育園であれば、大体どちらも１億７,０００万円の運営費ですので、違いはないという状況です。","voiceIndex":237,"id":"exchange-098"},{"speaker":"南委員","kind":"質問・要望","question":"ここに来て、１億７,０００万円でそんなに違いはないなんて言わないでいただきたいと思います。この点について、認識を伺いたいと思います。それで、区立保育園に勤める保育士３５歳の方を例として見ると、２０歳から勤めてきたと考え、それが一般的だと思うのですけれども、勤続１５年になりますが、月額給与は２６万１,０００円、年収は５２１万円と聞いておりますけれども、これでいいのかどうか。","respondent":"佐藤保育課長、米田人事課長","answer":"２点目、保育士の給与が上がっていない件に関しましては、品川区といたしましては、処遇改善等、積極的に取り入れていまして、平成２７年度の実績でいえば、１人当たり３万８,０００円上がっているところも確認しておりますので。今お話のありました賃金の関係ですけれども、机上の計算にはなりますけれども、おおむねそのような形になろうかと存じます。","voiceIndex":240,"id":"exchange-099"},{"speaker":"南委員","kind":"確認","question":"先ほど一緒に聞けばよかったのですが、ついこの前、私どもの会派の安藤委員が第１回定例会で一般質問した際に、公務員保育士の離職率は６.４％だと答弁されています。この数字もこれでいいのですか。確認したいと思います。","respondent":"米田人事課長","answer":"ご質問に応じてこちらのほうで確認をしたところ、大体６.４％になるということで、ご答弁したものです。","voiceIndex":243,"id":"exchange-100"},{"speaker":"南委員","kind":"質問","question":"私立保育園の保育士の勤務年数はわずか４.７年です。これが実態です。そしてまた同時に、共産党の都議団の調査では、事業活動収入に占める人件費の支出割合を見ると、調査した社会福祉法人の４２％が、７０％から８０％台を人件費として支出しているという状況の中で、では、株式会社立の保育園ではどうかと見てみると、４０％から５０％しか人件費に使われていない、こういう実態が明らかにされています。","respondent":"佐藤保育課長","answer":"今年度から都の補助金も活用して、各法人の運営に関する家賃助成のほうも大幅に増えております。そういった形で家賃の補助が入る関係で、それ以外の園運営費が人件費に回って、また、保育士の給与の処遇改善が進められると考えております。","voiceIndex":245,"id":"exchange-101"},{"speaker":"南委員","kind":"質問・要望","question":"株式会社立は５５％から６５％とおっしゃいましたが、それは、数字のとり方が違うのではないかと私は思います。先ほど私が紹介したのは、株式会社立は、事業活動収入に占める人件費の支出、ここが４０％から５０％台が一番多いのです。とっているところが違うことを持ってきて、そんなに変わらないなどと言わないでいただきたいと思います。そういう認識を持っていないですか。改めてそこを伺います。","respondent":"齋藤子ども未来部長","answer":"かつ平均賃金の引き上げに加えて、来年度以降は主任保育士、副主任保育士と格づけに応じた処遇がされるよう、補助金も今度見込まれております。","voiceIndex":247,"id":"exchange-102"},{"speaker":"南委員","kind":"質問・要望","question":"保育内容についてのご認識を伺ったのですが、改めて伺いたいのですけれども、長く働き続けられない、低賃金という状況に置かれている、これが民設民営の保育士の実態だと思います。いかがですか。伺いたいと思います。それで、やはりそういう長く働き続けられる条件が必要であり、そして、そういうことをきちんと守っていただきたい、そのように思っておりますので、どうぞ答弁をお願いします。","respondent":"齋藤子ども未来部長","answer":"ぜひ認識を改めていただきたいと、このように考えております。","voiceIndex":249,"id":"exchange-103"},{"speaker":"中塚委員","kind":"質問・要望","question":"動議。今の部長の答弁で、「票にならないからそういうことを言っている」というのは不適切だと私は思いますので、発言の取消しを求めたいと思います。取り消しの方法などについては、理事会を開くのか、委員会なのか、その辺の手続きは正副委員長、理事会にお任せしますけれども、今のこの発言は委員会の発言として、不適切だと私は思いますので、発言の取消しをしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":252,"id":"exchange-104"},{"speaker":"伊藤委員","kind":"確認","question":"私から、２２１ページ、民生委員経費に関連して、それから２２６ページ、高齢福祉費に関連して質問します。ですから、こういう精神的、肉体的にも大変な苦労がかかっている民生委員の方々に対して、フォロー体制はどうなっているのかということの確認がまず１点です。だから、こういうことを活用して、民生委員の負担を軽減すべきと思うのですが、いかがでしょうか。","respondent":"大串福祉計画課長","answer":"民生委員の活動とあわせながら、こういった民間事業者あるいは緊急通報システムなどを活用しながら、区内の高齢者などの安否と安全・安心を確保していきたいと考えています。","voiceIndex":254,"id":"exchange-105"},{"speaker":"伊藤委員","kind":"質問","question":"そういうところをある程度カバーしていくことを考えていくと、例えば、民間事業者の方々に協力依頼をしていくとか、それから、ＩＴ機器といったらいいのか、今、さまざまな機器が、通信システムがあって、温度や湿度、電力使用などさまざまな数値の異常がわかれば、すぐに通報できるシステムが既にあるわけですから、だから、それをうまくコーディネートしていって、民生委員の方々の負担を減らしてあげて。","respondent":"大串福祉計画課長","answer":"そういったさまざまな形で区を挙げてフォロー、およびそういった地域の安心の確保、これに努めていきたいと考えています。","voiceIndex":256,"id":"exchange-106"},{"speaker":"伊藤委員","kind":"質問","question":"さまざまなものを活用して、ぜひ民生委員の方々の活動に資するような対応をよろしくお願いしておきます。それからあと、高齢者の運転支援のほうですけれども、これは皆様方ご承知のように、最近、事故が多く報道されるようになりました。だから、その間のつなぎとして、こういう民間の技術を活用した上で、高齢者の方々の安全運転を支援していく仕組みを研究してみたらいかがと思いますが、いかがでしょうか。","respondent":"松山高齢者地域支援課長","answer":"委員ご指摘の安全運転の仕組みというのは、高齢者の外出支援を考える上では大切なことだと考えています。","voiceIndex":258,"id":"exchange-107"},{"speaker":"伊藤委員","kind":"質問","question":"だから、そのようなものをいち早く品川区がキャッチし、研究した上で、もちろん特定の業者に対してここでどうこう言うわけではないのだけれども、ただ、内容がちょうど時宜にかなったわけです。今、研究とおっしゃったけれども、さまざまな学会やら報告会が相当数開かれているので、ぜひそういう会に参加してみてはいかがでしょうかということと、それから将来的な検討の方向性についてお聞かせください。","respondent":"松山高齢者地域支援課長","answer":"私ども高齢者地域支援課を含むほかの所管とも連携をとりながら、警察など関係機関の動向もありますので、そちらも注視しつつ一緒に勉強してまいりたいと考えております。","voiceIndex":260,"id":"exchange-108"},{"speaker":"石田（し）委員","kind":"質問","question":"それと、入園の申し込みの締め切りが迫ってきた時期に、７階の保育課のところが大変混雑される中で、大勢の方が窓口に来るような事業があるときというのは、区では、専用の電話の窓口を設置されたり、３階の防災センターのところの広いスペースに別の窓口を設置されたりしておりますが、７階の保育課のところが混雑されているのを見ると、何とかできないものなのかと思いまして、例えば。","respondent":"佐藤保育課長、大澤待機児童対策担当課長","answer":"専用窓口の設置に関してですが、保育園の入園相談というのは調書が必須ですので、それを見ながら各担当がきめ細かい丁寧な説明をしていますので、例えば、どこか会議室で場所を持った場合は。ただ、こちら、２方向避難ですとか、要件がかなり厳しくなりますので、ご相談は何件か受けておりますが、なかなか実現せずに、今のところ区内で事業所内保育をやっているところはございません。","voiceIndex":263,"id":"exchange-109"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"この件について、いわゆる在宅の育児世帯への支援について区のお考えをお知らせいただきたいのと、現在、在宅育児をされている世帯が、ざっくりで構いませんので、全体の何％ぐらいあるのか教えていただきたいのと、これもざっくりで構いませんが、年齢等で全然変わってくるのかと思いますが、平均で構いませんので保育園で預かると、園児１人当たりにかかる行政としての費用というのは大体どのくらいなのか。","respondent":"大澤待機児童対策担当課長、佐藤保育課長","answer":"初めに、待機児童解消の観点から、在宅子育てのご質問にお答えいたします。確かに在宅子育ての支援の大切さは認識しております。委員おっしゃられた鳥取県の例も、待機児童解消という観点からは、一定の効果はあるのかなと考えています。保育園で１年間にかかる経費ということですけれども、月額になりますが、０歳児ですと、運営経費から割り返しますと、大体３５万円から３６万円、１歳児に関しましては、２１万円、２歳児は１９万円、３歳児は１０万６,０００円。","voiceIndex":266,"id":"exchange-110"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"確かに保育園の増設が一番のというのはわかるのですが、ぜひ在宅育児世帯へも光を当てていただきたいと思いますので、これは要望で終わります。事業所内保育ですが、実際に問い合わせはあったけれども、なかなか設置が難しく、まだ実績がないといった中で、これは例えば、特に中小企業とかだと、なかなか１社で設置をするのは困難なのかと。","respondent":"大澤待機児童対策担当課長、佐藤保育課長","answer":"そちらのほうでは、地域の会社が共同で保育所をつくることも可能ということになって、運営費の助成ですとか、また、東京都では備品購入の助成、さまざまありますので、そちらのほう、ご相談がありましたときには。指数をつける基準については、窓口のほうで全ての申請の方に丁寧な説明をしておりますが、わかりにくい部分もあるかもしれませんので、今後もご理解いただけるように、丁寧な対応をしてまいります。","voiceIndex":269,"id":"exchange-111"},{"speaker":"石田（し）委員","kind":"質問","question":"実際、なかなか入りづらいという現実があると思いますので、ぜひ対応をお願いしたいと思います。時間があるので、１点、福祉のほうで少しお伺いをしたいのですが、区の保養所というのですか、ありますよね。","respondent":"伊崎地域活動課長","answer":"バリアフリーにつきましても、工事の際に対応できるところは対応しています。ただ、やはり限界がありますので、今、委員からご提案がございました障害者用の器具の使用につきましても、業者と相談しながら検討していきたいと考えております。","voiceIndex":272,"id":"exchange-112"},{"speaker":"若林委員","kind":"質問・要望","question":"それと、１年間の成果と、また、検証がどのようになっているのか、教えていただきたいと思います。もう一点は、２４４ページの児童福祉費に関連しまして、保育園のいわゆる３歳児の壁について確認をします。現状、とりあえず平成２８年度、今年度までの実態は、この３歳児の壁についてはどうなっているか、教えていただきたいと思います。こういう方策が示されました。","respondent":"永尾高齢者福祉課長、大澤待機児童対策担当課長","answer":"要介護度改善ケア奨励助成の成果ですけれども、平成２５年度から開始いたしまして、新規の方の人数が平成２５年度が４７人だったところが、平成２８年度では７１人に増えているところです。平成３０年度以降に開設する新規園には、定員差を３人以上設けるようにしておりますので、平成３０年か平成３１年には、２００人以上の定員差が設けられる見込みですので、認証の卒園児も含めて、のみ込んでいける数だと考えています。","voiceIndex":275,"id":"exchange-113"},{"speaker":"若林委員","kind":"質問・要望","question":"このような取り組みを、今、品川区は施設ということでやっておりますけれども、区内のほかの、今、取り組まれている１５施設以外の、いわゆる一般的な施設についても広がっていくということが、これに先駆的に取り組んでいる品川区ならびに施設サービス向上、今は研究会というのですか。前は委員会といっていましたけれども、研究会になったのですね。","respondent":"永尾高齢者福祉課長","answer":"その中の一部をピックアップしますと、より一層高い意識を持って専門職としてのケアに取り組むことができるだとか、ご家族からも元気になったという言葉をいただくと、自分たちのモチベーションにもつながるというような意見がさまざま出てきているところですので。","voiceIndex":278,"id":"exchange-114"},{"speaker":"松澤委員","kind":"質問","question":"３款民生費、１項社会福祉費、２目高齢福祉費、２３１ページ、家具転倒防止対策助成、１８１万５,０００円、まず、思いを述べていきたいと思います。それと、こうやって質問をしていると、家具転倒防止策は高齢者に対する住宅助成ということだから民生費なのでしょうけれども、本来的には防災対策、総務費で扱うべきではないかと思っておるのですが、この点についてもお聞きしたいと思います。","respondent":"松山高齢者地域支援課長、秋山財政課長","answer":"件数的には、多少、今年は伸びまして、１２月末で４４件ですので、見込みとしては５０件ぐらいはいくのではないかと、達成したいと思っている次第です。こちらのほうでやっておると。そういう形で、住宅施策としても、高齢者施策としても、区としては進めていきたいという予算のつくりになっているものです。","voiceIndex":281,"id":"exchange-115"},{"speaker":"松澤委員","kind":"質問・要望","question":"総務費でやるべきではないですかというのですが、それをはっきりと答えていただきたいと思います。","respondent":"秋山財政課長","answer":"失礼しました。防災対策ですけれども、今、区としては、住宅と高齢にわけてやっているというところで、その辺の今までの経緯等々ありますので、その辺、どちらで計上するかというのは、今後、わかりやすい予算ということも含めて、検討はさせていただきたいと考えています。","voiceIndex":284,"id":"exchange-116"},{"speaker":"松澤委員","kind":"質問・要望","question":"東京都では、やはり世論調査ということで、１つだけ選んでくださいというふうにやっているわけです。ですから、品川区民でも、７割、８割しているかもしれない。ただ、その実数がわかれば、今後の対策もまた違うかなということなので、ぜひともこれは世論調査の中に入れてもらいたいと思いますけれども、款が違いますので、これは要望ということにしておきますので、よろしくお願いしたいと思います。","respondent":"松山高齢者地域支援課長","answer":"シルバーセンターから移行した２カ所の大きな場所とは規模や設備が異なりますけれども、高齢者を主とした子育て世代、障害者等、多世代区民の交流の場、憩いの場というものをゆうゆうプラザということで、愛称で名づけさせていただきました。","voiceIndex":286,"id":"exchange-117"},{"speaker":"藤原委員","kind":"質問","question":"トラブルは、問題はないですよね。それと、２２５ページ、特別養護老人ホーム建設費助成なのですけれども、一般質問でお伺いしましたけれども、従前のお答えは、土地を探しているという趣旨の答弁だったと思うのですが、今回そのことをお尋ねしましたら、今までと少し違っている答弁だったと思うのですけれども、その辺について明確にお答えください。障害のあるお子さんの面倒が見切れなくなってくる。","respondent":"大串福祉計画課長、松山高齢者地域支援課長、中山障害者福祉課長","answer":"こちらにつきましても、従前お答えしているような形ですけれども、特養の整備については総合的な判断といったところで行ってきた中で。友愛活動につきましても、今後、民生委員と連携を密にしていくということで、高齢者クラブのほう、連絡会を行ってあります。来年度、新規で地域生活支援の拠点のマネジャーというのは、そういった位置づけとして、ハイリスク家庭の把握。","voiceIndex":290,"id":"exchange-118"},{"speaker":"藤原委員","kind":"確認","question":"私も特別委員会で行きました。やるのですよね。次に児童相談所について伺いますが、お金の部分なのですが、移管が実行されたら、品川区でどのぐらいの経費がかかると見込んでいるのでしょうか。それと、２４９ページの待機児童解消対策費をお伺いしますが、よく待機児童対策担当課長が、３０年に解消されるということをおっしゃるではないですか。３０年というのは２０３０年のことですよね。確認します。","respondent":"高山子ども育成課長、秋山財政課長、大澤待機児童対策担当課長","answer":"平成２５年に出されました特別区の児童相談所移管モデルという試算がございまして。この点につきましては、都区のあり方検討会の中でも、東京都が、児童相談所の業務は大都市事務だという主張をしておりますので。待機児童解消の時期ですが、現在、大変厳しい状況ではありますけれども、子ども・子育て計画に沿いまして。","voiceIndex":294,"id":"exchange-119"},{"speaker":"藤原委員","kind":"質問・要望","question":"平成３０年というのはもう１年後です。ある意味、どこからそういう数字が出たのでしょうか。これだけ品川区がいい施策をして、すばらしい区ですから、やはり品川区にさまざまな方が入られてきて、やると思いますし、人口も増えるというのは、人口動態調査もして、よくわかっていると思うのですけれども、それでも平成３０年という数字を出したのですよね。もう少し正確に、思いがあれば、言っていただきたい。","respondent":"大澤待機児童対策担当課長、佐藤保育課長、廣田子ども家庭支援課長","answer":"私どもは子ども・子育て計画に基づいて開設計画を進めてまいりますので、現時点ではあくまでも平成３０年を目指して取り組んでいくというお答えになります。入園の結果等に関する窓口の対応等ですが、平成２９年４月入園の１次審査発表においては、１,１９０人の方々に不承諾の通知を送付しております。資金面での、経済面での支援について、今回、委員会の中でかなりさまざまなご意見をいただいているところですけれども、子どもの支援だけではなくて。","voiceIndex":298,"id":"exchange-120"},{"speaker":"藤原委員","kind":"確認","question":"課長、信じています。平成３０年に待機児という言葉がなくなって、解消されると、今日、言ってくださいましたので、心から信じておりますので、また民生費は違う機会に質問するようになると思いますので、改めましてよろしくお願いいたします。そこだけ確認をさせてください。","respondent":"齋藤子ども未来部長","answer":"何ができるというわけではありませんけれども、一緒にお昼ご飯を食べに行ったり、あとは、今年は弁護士をお二人お願いして、法律のクレーム対応の講習もいたしましたし、少しずつ毅然とした対応もとれる、そして、優しく寄り添う。","voiceIndex":302,"id":"exchange-121"},{"speaker":"大倉委員","kind":"質問・要望","question":"２４９ページ、待機児童解消対策費、２２３ページ、福祉団体に対する助成金、２４５ページ、児童相談所移管推進経費について伺います。前の質疑でも、経費はおおむね７億円、財調の中で行われるべきだと区のほうは思っているというところで、そういった区の中の思いはわかるのですが、都とのその辺の調整というか、都との話というのはどのようになっているのか、お知らせいただきたいと思います。","respondent":"大澤待機児童対策担当課長、高山子ども育成課長、中山障害者福祉課長","answer":"品川区子ども・子育て計画の前倒しというご質問ですけれども、今、乳幼児人口が増えていることと、入園を希望する方が多いということで。実際のところ、１２月に入りまして、東京都のほうから、モデル的な確認実施区を数区選んでほしいという動きがありまして、そうした中で。こちら、７団体に対する助成金ということになりますが、金額の差につきましては、活動の内容、それから会員の数、そうしたものに合わせて違いがあります。","voiceIndex":305,"id":"exchange-122"},{"speaker":"大倉委員","kind":"質問・要望","question":"福祉団体に対する助成なのですが、これは会員数の違いなどによりどのぐらい助成の額が違うのでしょうか。ほかの、例えば、これに入っていない団体でも、会員数が多かったり、会報をつくっているところもあるだろうし、確認はしていないのですが、旅行もされていたり、活発に活動しているところもあるのですが、そういった団体は補助金の対象には入ってこられないのでしょうか。","respondent":"柏原企画調整課長、中山障害者福祉課長","answer":"今後、長期基本計画が１０年目の周期に入ってくるというところがありますので、ここは子育ての施策だけではなくて、全体の施策にかかわる部分はありますので、そういった中で、人口の推計というのは、見直しといいますか。社会福祉協議会のほうからどれぐらいの助成が出ているのかというのは、その団体にもよるのですけれども、例えば、５万円ぐらいから、あとはほかの補助金なんかも入れながら。","voiceIndex":309,"id":"exchange-123"},{"speaker":"大倉委員","kind":"質問・要望","question":"団体に関する助成ですが、こうやって金額を見ると、かなりこちらだと、多いのだと６０万円とか、４０万円とか、一方、なかなか１０万円、１５万円とかというところもあるので、そういった部分でしっかりと支援をしていただきたいと考えていますので、これは要望で終わりますが、困っている小さい団体にもしっかりと光を当てていただければと思って、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":312,"id":"exchange-124"},{"speaker":"安藤委員","kind":"質問・要望","question":"私から、後期高齢者医療特別会計と、待機児解消認可保育園増設について伺います。所得割額の軽減については、所得金額１５万円以下の方、２０万円以下の方、５８万円以下の方、それぞれ影響人数と金額を伺います。それとあわせて、被扶養者だった方の軽減も見直しになりますが、それについては、影響する人数、それぞれお答えいただきたいと思います。","respondent":"高森国保医療年金課長","answer":"所得金額５８万円以下の方、対象者２,７８４人、対象金額、軽減額につきましては、１,８４４万円ほどです。被扶養者の方の軽減の対象人数ですが、平成２８年４月から１０月までの７カ月間で、７７２人という数字を持ってあります。","voiceIndex":314,"id":"exchange-125"},{"speaker":"安藤委員","kind":"質問・要望","question":"その方の負担がどれぐらい上がるかということをお伺いしたかったのですけれども、時間もないのでいいです。品川区は、国に特例軽減の段階的解消はやめるよう、強く要望してほしいと思います。次に行きたいと思います。現在の進捗について伺います。２４９ページの保育園用地取得経費２カ所の１つはここのことだと思うのですが、２カ所とはどことどこのことかも確認させてください。","respondent":"柏原企画調整課長、矢木用地担当課長","answer":"今後、契約に向けて手続きに入っていく段階でございまして、予算措置も必要ということがありますので、今回、この購入に関しての予算措置を計上させていただいて、議論いただいているという状況です。現在、平成２９年度中の取得に向けまして鋭意交渉中でございまして、場所、相手方、平米数等詳細につきましては、相手方の意向もございまして、現時点ではお話しすることが難しいということになっております。","voiceIndex":316,"id":"exchange-126"},{"speaker":"安藤委員","kind":"提案","question":"ぜひ積極的に取得に向けて前に進んでいただきたいと思います。私は、まず言いたいのは、目黒駅付近での保育園は本当に不足しておりまして、地域の理解と協力を得て、いい保育園をぜひつくってほしいという立場です。そこで、設計段階から住民説明会を開くことを提案したいと思います。２つの効果があると考えています。設計段階からの住民説明会を開くことを提案いたしますけれども、いかがでしょうか。","respondent":"柏原企画調整課長","answer":"今、委員ご指摘ありました、近隣の方々のお話というのは、我々のほうにもお声は届いております。こちらのほう、施設を設置するに当たっては、丁寧な説明といいますか、お話はしていきたいと思ってあります。","voiceIndex":319,"id":"exchange-127"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ従来の丁寧な説明を超えて、設計段階からの説明会を開いていただくよう、重ねて要望したいと思います。保育を志す方が求めているのは、安心して働き続けられることであることは明らかだと思います。それでお伺いします。今般のこの委員会でも、区は、平成５２年まで保育需要はある旨の答弁もありました。この答弁の意味、どういう意味なのか、もう少し伺わせてください。","respondent":"大澤待機児童対策担当課長","answer":"保育需要ですが、今後、女性の社会進出ということで、ますます弾みがつくですので、乳幼児人口が一定ピークになりましても、保育需要はその後、平成５２年ぐらいまでは下回らないだろうという考えです。","voiceIndex":321,"id":"exchange-128"},{"speaker":"安藤委員","kind":"質問","question":"今と同水準ぐらいの保育需要はあるということだと理解されているのかと思いましたけれども、今年の４月に向けての応募でも、１,１９０人の方が認可保育園を希望しながら不承諾となっているという事態です。お伺いしますけれども、これは品川区子ども・子育て計画に示されています保育の確保方策数を全部実現したとしても、待機児童はゼロにできないという区の認識なのでしょうか。伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"品川区子ども・子育て計画の確保方策の数値としましては、平成３０年度分も平成２９年度に開設しますので、計画の数値上は平成２９年度中にはゼロになることになっています。","voiceIndex":323,"id":"exchange-129"},{"speaker":"安藤委員","kind":"質問","question":"計画上は平成２９年度でゼロになっているはずだということなのですが、現実問題としてそのようになっていないということですが、私は、そうした現実をまさに変えていくといいますか、待機児ゼロを現実のものにするのが政治の役割であり、行政の役割だと思いますが、この計画は既にずれがあるということですけれども、これであれば、この計画を早急に見直すべきだと思いますけれども、いかがでしょうか。","respondent":"大澤待機児童対策担当課長、柏原企画調整課長","answer":"品川区子ども・子育て計画につきましては、子ども・子育て会議で決めているものですので、修正するかどうかも含めまして、子ども・子育て会議にお諮りしたいと考えております。年少人口の部分ですけれども、こちらのほう、実際の動きのほうが伸びが大きいという部分は認識しています。","voiceIndex":325,"id":"exchange-130"},{"speaker":"安藤委員","kind":"質問・要望","question":"修正するかどうかも含めて会議に諮るというのは、あまりにイニシアチブがなさ過ぎるといいますか、修正が必要な時点になっているわけです。ですから、修正を早急にする必要があるし、保育需要に見合った保育園の増設を行わなければ、待機児童はゼロにならないわけですから、ぜひ修正をしていただきたいと思いますが、いかがでしょうか。","respondent":"大澤待機児童対策担当課長、吉田保育施設調整担当課長","answer":"全体的な改訂ということではございませんが、開設数に関しましては、平成２９年につきましても、６園だったところを１２園で会議のほうにかけて、ご了承いただいたです。子ども・子育て会議、平成２９年度運営委員等の改選があるのですけれども、その中で、また品川区子ども・子育て計画について検討していきたいと思います。","voiceIndex":328,"id":"exchange-131"},{"speaker":"安藤委員","kind":"質問・要望","question":"一人一人のお子さんや一人一人の家庭にとっては重大問題で、人生がかかっているような問題だと思いますので、ここにしっかりと解決のために向き合っていただきたいと思うのです。それで、なぜ今回これほどずれたのかというところの分析というのですか、反省といいますか、そこら辺は品川区としてはどのように考えているのか、そちらもお伺いします。","respondent":"大澤待機児童対策担当課長","answer":"計画とのずれですが、これは推計以上に乳幼児人口が増えたことと、希望される方の割合が増えたことという２点に尽きると考えています。","voiceIndex":331,"id":"exchange-132"},{"speaker":"安藤委員","kind":"質問・要望","question":"そうしたずれがこれから起こってはいけないわけです。そうした政策をとりつつ、しかも保育需要も、保育園を希望する方の家庭を低く見ているのではないかというふうに、私もそのように見ていますし、しっかりとそこら辺はずれがないように計画を立ててほしいと思います。区の責任で需要に見合った認可保育園の増設を行い、待機児解消を行うよう求めますが、いかがでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"入園をご希望される方が増えているという認識がありますので、平成２９年度に関しましても、計画の倍の開設を進めているところです。平成３０年度におきましても、計画上では６園となっておりますが、この状況を見て、計画以上の開設を予定すべきと認識しております。","voiceIndex":333,"id":"exchange-133"},{"speaker":"たけうち委員","kind":"質問・要望","question":"私は、２２３ページ、品川介護福祉専門学校、２３１ページの支え愛・ほっとステーション事業、２５１ページの認可外保育施設保育料助成をお伺いします。そういう中で、先ほどもご答弁ありましたけれども、プレス発表の８６ページ、ここにさまざまと確保策が用意されておりますけれども、給料のアップにつながるような支援というのがあるのかどうか、もう一度教えていただきたいと思います。","respondent":"永尾高齢者福祉課長、大串福祉計画課長、佐藤保育課長","answer":"ただ、国のほうの処遇改善加算というのが、平成２７年度４月でも行われて、また、平成２９年度、今年も行われる予定になっておりますので、キャリアパス等。委員からご案内ありましたように、来年度からは５地区、新たに展開して。認可外保育施設の対象施設の件ですが、プレス発表したとおり、１９施設中１１施設が対象となっております。","voiceIndex":336,"id":"exchange-134"},{"speaker":"たけうち委員","kind":"質問・要望","question":"品川区介護福祉専門学校のほうは、保育士もとり合いというか、東京都が上乗せすることで、千葉とか神奈川から非常に東京都へブーイングが出ているようなお話を聞いていますけれども、また２３区間でも競争になってくるという中で、介護士についても、ぜひ区独自で何かしらの拡充を、今回の発表されているのも含めて、またさらに支援をしていただきたいという要望をします。","respondent":"大串福祉計画課長、佐藤保育課長","answer":"こうした基盤があってこそ、こういった今やっております支え愛・ほっとステーション、あるいは今後、２層の協議体といったところの活動、これも展開していくです。ふれあいサポート活動から、逆に支え愛活動という形に移行しています。東京都のほうに確認したところ、立ち入り調査の結果により、これまで基準を満たしていた施設の著しい違反行為が認められ、それを改善するよう指導する場合は非常にレアケースであるです。","voiceIndex":340,"id":"exchange-135"},{"speaker":"たけうち委員","kind":"質問","question":"支え愛・ほっとステーション事業ですけれども、そうしますと、ふれあいサポート活動のほうでやっていただいていたボランティアの方はそのまま今いらっしゃるのか、それとも地域支援員というのですか、そのようになっていらっしゃるのか、そこの今後、裾野というか、支え手の方たちのそういう充実が必要になってくるのですけれども、その辺の連携とか、その辺がどうなっているのかを教えてください。","respondent":"河内協働・国際担当課長","answer":"名称は変わりますが、地域独自の支援体制については、そのまま継続の体制で進むものもあれば、地域の特性に応じまして、また閉じるものもあるということで、しっかり継続してまいるところです。","voiceIndex":343,"id":"exchange-136"},{"speaker":"鈴木（真）委員","kind":"確認","question":"１点目に、児童発達支援です。この点について、まず教えてください。それから、保育園関係です。これは園児の問題ではないのです。これは最初から約束している話ですから、それを取り消せという話ではないのですけれども、やり方として、先方はすでに納品している中で、区では１カ月以上、支払いまでかかる、その辺を何か改善できないのでしょうかというご相談がありました。","respondent":"中山障害者福祉課長、福島会計管理者","answer":"児童発達支援のうち、医療の必要なお子様の通われる、今回４月に開設する「ほわわ品川」についてのご質問です。今までは医療の必要なお子様は、都立城南分園のほうで、児童発達支援ということで、療育を受けていただいておりました。ただ、それにつきましては、業者にもそういう丁寧な説明をしまして、ご理解をいただいています。","voiceIndex":346,"id":"exchange-137"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ぜひうまく進めていただきたいという思いがあります。それから、支払いの件はわかりました。先方も十分わかっているのですけれども、やはり何か少し方法がないかと。ただ、今聞いた５,０００件ということで、もし月に２回としても、作業の問題もあるとのことで、その辺はうまく説明を、またわかるようにしておいてもらいたいと思いますので、よろしくお願いします。","respondent":"中山障害者福祉課長","answer":"医療的ケアが必要なお子さんということになりまして、障害者の手帳をお持ちでないお子さんであっても、例えば、気管切開であったり、胃ろうがあったりというお子さんについては、こちらのほうでお預かりをすることができるようになっております。","voiceIndex":349,"id":"exchange-138"},{"speaker":"鈴木（真）委員","kind":"確認","question":"その辺、医療的ケアの必要なお子さんを障害というふうにとるのか、それとも、保健所の管轄なのか、そういう確認なのですが。","respondent":"中山障害者福祉課長","answer":"肢体不自由であったり知的を伴ったりということであれば、障害児ということにもなりますが、今は本当にただ医療が必要だというお子さんもいらっしゃいます。そうしたお子さんは障害児ではありませんが、こちらの施設のご利用は可能となっております。","voiceIndex":351,"id":"exchange-139","title":"議員研修会の内容と所要時間"},{"speaker":"鈴木（真）委員","kind":"質問","question":"わかりました。さっきも言いましたけれども、積極的に対応していらっしゃるということで、ぜひ今後もよろしくお願いします。ですから、皆さんも手を挙げてどうですかというと、関心のある方が多いから、どうしても品川区はすごくいい数字が出たと思います。これをいかに広げていくかというのに今ご苦労なさっていると思うのですが、この辺で、これからの課題、推進に向けてのお話をお聞きしたいと思います。","respondent":"松山高齢者地域支援課長","answer":"１１月には、荏原第三地区、３月１日は大崎第二地区、それから、３月１５日には、品川第一地区でワークショップを開催する予定です。","voiceIndex":353,"id":"exchange-140"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ぜひ進めていただきたいと思います。都議会自民党のほうから資料が来た中で、今年の都の予算の中で、介護予防による地域づくり推進員の配置というのが新制度で出ていました。既に都の補助金、国の補助金、入っていると思うのですが、こういうのは、また活用して増やすことはできないのでしょうか。","respondent":"松山高齢者地域支援課長","answer":"フォーラムやワークショップの中で、地域で話された課題につきまして、またコーディネーターから情報提供をいただくことになっておりますので、その課題につきまして、リハビリテーションの専門家の視点を含めて検討した上で、今後、介護予防の体制整備。","voiceIndex":355,"id":"exchange-141"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。ぜひうまく進めていっていただきたいと思います。最後に、児童相談所の件がさまざま出ていました。今朝、我が会派の横山委員からもお話しさせていただいたときに、区長にご意見を聞いたら、区長、手を挙げかかったのですが、お答えいただけなかったので、もしよろしければ、区長として今後の対応についてお答えいただきたいと思います。","respondent":"濱野区長","answer":"児童相談所の移管というのは、１０年ぐらい前になりますけれども、都区のあり方検討会というところでいろいろ議論になって、その線でやっていきましょうということになりました。","voiceIndex":357,"id":"exchange-142"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1060#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":134992,"voices":359}}]);
